function Get-WfxAttackTechnique {
    <# Returns name/tactic/url for ATT&CK ids (unknown ids are returned with a blank name). #>
    param([string[]]$Id)
    foreach ($t in @($Id | Where-Object { $_ })) {
        $info = $script:WfxAttack[$t]
        $base = $t -replace '\.', '/'
        [pscustomobject]@{
            Id     = $t
            Name   = if ($info) { $info[0] } else { '' }
            Tactic = if ($info) { $info[1] } else { '' }
            Url    = "https://attack.mitre.org/techniques/$base/"
        }
    }
}


# ===== Private/Core.ps1 =====
# WinForensicX — core engine: findings, scoring, redaction, logging, case management, helpers.
# Compatible with Windows PowerShell 5.1 and PowerShell 7+. Analysis helpers here are
# platform-neutral so analyzers can run (and be tested) on any OS.

$script:WfxVersion = '2.0.0'
$script:WfxSeverities = @('Info', 'Low', 'Medium', 'High', 'Critical')
$script:WfxSeverityWeight = @{ Info = 0; Low = 2; Medium = 5; High = 10; Critical = 20 }
$script:WfxConfidenceFactor = @{ Low = 0.5; Medium = 0.8; High = 1.0 }
$script:WfxCase = $null
$script:WfxGaps = New-Object System.Collections.Generic.List[object]
$script:WfxQuiet = $false

# ───────────────────────────── platform ─────────────────────────────
function Test-WfxWindows {
    if ($PSVersionTable.PSVersion.Major -le 5) { return $true }
    return [bool]$IsWindows
}

function Test-WfxAdmin {
    if (-not (Test-WfxWindows)) { return $false }
    try {
        $id = [Security.Principal.WindowsIdentity]::GetCurrent()
        return ([Security.Principal.WindowsPrincipal]$id).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    } catch { return $false }
}

# ───────────────────────────── console ─────────────────────────────
function Write-WfxConsole {
    <# Single place for interactive console output, so -Quiet and colors are consistent. #>
    param(
        [Parameter(Position = 0)][AllowEmptyString()][string]$Message = '',
        [ValidateSet('Info', 'Ok', 'Warn', 'Bad', 'Head', 'Dim', 'Plain')][string]$Kind = 'Plain',
        [switch]$NoNewline
    )
    if ($script:WfxQuiet) { return }
    $color = @{ Info = 'Cyan'; Ok = 'Green'; Warn = 'Yellow'; Bad = 'Red'; Head = 'White'; Dim = 'DarkGray'; Plain = 'Gray' }[$Kind]
    Write-Host $Message -ForegroundColor $color -NoNewline:$NoNewline
}

function Write-WfxSection {
    param([string]$Title)
    Write-WfxConsole ''
    Write-WfxConsole ("── {0} {1}" -f $Title, ('─' * [Math]::Max(3, 66 - $Title.Length))) -Kind Head
}

# ───────────────────────────── audit log & gaps ─────────────────────────────
function Write-WfxLog {
    <# Appends one JSON line to the case audit log: what the tool did, when, and with what result. #>
    param([string]$Event, [hashtable]$Data = @{})
    if (-not $script:WfxCase -or -not $script:WfxCase.Path) { return }
    $entry = [ordered]@{ time = (Get-Date).ToUniversalTime().ToString('o'); event = $Event }
    foreach ($k in $Data.Keys) { $entry[$k] = $Data[$k] }
    try {
        $line = ($entry | ConvertTo-Json -Compress -Depth 5)
        Add-Content -LiteralPath (Join-Path $script:WfxCase.Path 'audit.log') -Value $line -Encoding UTF8
    } catch { Write-Verbose "audit log write failed: $_" }
}

function Add-WfxGap {
    <# Records something the tool could not collect (missing privilege, disabled log, error) — shown in the report so absence of findings is never mistaken for absence of evidence. #>
    param([string]$Source, [string]$Reason, [string]$Fix = '')
    $script:WfxGaps.Add([pscustomobject]@{ Source = $Source; Reason = $Reason; Fix = $Fix })
    Write-WfxLog -Event 'gap' -Data @{ source = $Source; reason = $Reason }
    Write-Verbose "[$Source] gap: $Reason"
}

function Get-WfxGap { , $script:WfxGaps.ToArray() }
function Clear-WfxGap { $script:WfxGaps.Clear() }

function Invoke-WfxStep {
    <# Runs one collector or analyzer step; failures become recorded gaps instead of aborting the triage. #>
    param([string]$Name, [scriptblock]$Script, $Default = @())
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try {
        $out = & $Script
        Write-WfxLog -Event 'step' -Data @{ name = $Name; ms = $sw.ElapsedMilliseconds; ok = $true }
        return $out
    } catch {
        Add-WfxGap -Source $Name -Reason $_.Exception.Message
        Write-WfxLog -Event 'step' -Data @{ name = $Name; ms = $sw.ElapsedMilliseconds; ok = $false; error = $_.Exception.Message }
        return $Default
    }
}

# ───────────────────────────── findings ─────────────────────────────
function New-WfxFinding {
    <#
    .SYNOPSIS Creates a normalized finding. Every analyzer returns these.
    .PARAMETER Id         Stable rule identifier (e.g. LOTL-CERTUTIL-DOWNLOAD). Used for dedupe, tuning and allowlists.
    .PARAMETER Entity     What the finding is about, in a stable form ("process:4412:powershell.exe", "file:C:\x.ps1").
    #>
    param(
        [Parameter(Mandatory)][string]$Id,
        [Parameter(Mandatory)][string]$Title,
        [ValidateSet('Info', 'Low', 'Medium', 'High', 'Critical')][string]$Severity = 'Medium',
        [ValidateSet('Low', 'Medium', 'High')][string]$Confidence = 'Medium',
        [Parameter(Mandatory)][string]$Category,
        [string[]]$Technique = @(),
        [string]$Description = '',
        [string]$Entity = '',
        $Evidence = $null,
        [string]$Recommendation = '',
        [string]$HostName = '',
        $Time = $null,
        [string]$Source = ''
    )
    $weight = $script:WfxSeverityWeight[$Severity] * $script:WfxConfidenceFactor[$Confidence]
    $t = $null
    if ($Time) { try { $t = ([datetime]$Time).ToUniversalTime().ToString('o') } catch { $t = [string]$Time } }
    [pscustomobject]@{
        PSTypeName     = 'WinForensicX.Finding'
        Id             = $Id
        Title          = $Title
        Severity       = $Severity
        Confidence     = $Confidence
        Score          = [Math]::Round($weight, 1)
        Category       = $Category
        Technique      = @($Technique | Where-Object { $_ })
        Description    = $Description
        Entity         = $Entity
        Evidence       = $Evidence
        Recommendation = $Recommendation
        Host           = $HostName
        Time           = $t
        Source         = $Source
    }
}

function Merge-WfxFinding {
    <# Dedupes findings by Id + Entity (keeps the highest-scoring one and counts repeats) and sorts by severity. #>
    param([object[]]$Finding)
    $byKey = [ordered]@{}
    foreach ($f in @($Finding | Where-Object { $_ })) {
        $key = "$($f.Host)|$($f.Id)|$($f.Entity)"
        if ($byKey.Contains($key)) {
            $prev = $byKey[$key]
            $prev | Add-Member -NotePropertyName Occurrences -NotePropertyValue ([int]$prev.Occurrences + 1) -Force
            if ($f.Score -gt $prev.Score) { $f | Add-Member -NotePropertyName Occurrences -NotePropertyValue $prev.Occurrences -Force; $byKey[$key] = $f }
        } else {
            $f | Add-Member -NotePropertyName Occurrences -NotePropertyValue 1 -Force
            $byKey[$key] = $f
        }
    }
    $sevRank = @{ Critical = 0; High = 1; Medium = 2; Low = 3; Info = 4 }
    , @($byKey.Values | Sort-Object @{ Expression = { $sevRank[$_.Severity] } }, @{ Expression = { $_.Score }; Descending = $true }, Title)
}

function Get-WfxRiskScore {
    <#
    .SYNOPSIS Host risk 0–100. Combines findings as independent evidence: risk = 1 - Π(1 - wᵢ/40).
    One high-confidence Critical ≈ 50, two ≈ 75; many Lows can't add up to a Critical.
    #>
    param([object[]]$Finding)
    $p = 1.0
    foreach ($f in @($Finding | Where-Object { $_ })) {
        $w = [Math]::Min(39.0, [double]$f.Score)
        $p *= (1.0 - $w / 40.0)
    }
    $score = [int][Math]::Round(100 * (1 - $p))
    $level = if ($score -ge 75) { 'Critical' } elseif ($score -ge 50) { 'High' } elseif ($score -ge 20) { 'Elevated' } else { 'Low' }
    [pscustomobject]@{ Score = $score; Level = $level }
}

function Get-WfxSeveritySummary {
    param([object[]]$Finding)
    $o = [ordered]@{}
    foreach ($s in 'Critical', 'High', 'Medium', 'Low', 'Info') { $o[$s] = @($Finding | Where-Object { $_.Severity -eq $s }).Count }
    [pscustomobject]$o
}

# ───────────────────────────── text & entropy ─────────────────────────────
function Get-WfxEntropy {
    <# Shannon entropy (bits per symbol) of a string or byte array. #>
    param([Parameter(Mandatory)][AllowEmptyString()]$InputObject)
    if ($null -eq $InputObject) { return 0.0 }
    $counts = @{}
    $n = 0
    if ($InputObject -is [byte[]]) { foreach ($b in $InputObject) { $counts[$b] = 1 + [int]$counts[$b]; $n++ } }
    else { foreach ($c in ([string]$InputObject).ToCharArray()) { $counts[$c] = 1 + [int]$counts[$c]; $n++ } }
    if ($n -eq 0) { return 0.0 }
    $h = 0.0
    foreach ($v in $counts.Values) { $p = $v / $n; $h -= $p * [Math]::Log($p, 2) }
    [Math]::Round($h, 3)
}

function Format-WfxSecret {
    <# Shows only enough of a secret to identify it: first 4 characters + length. Never the value. #>
    param([AllowEmptyString()][string]$Value)
    if ([string]::IsNullOrEmpty($Value)) { return '' }
    $keep = [Math]::Min(4, [Math]::Floor($Value.Length / 4))
    return ('{0}…[redacted, {1} chars]' -f $Value.Substring(0, $keep), $Value.Length)
}

$script:WfxSecretPatterns = @(
    @{ Name = 'Anthropic API key'; Pattern = 'sk-ant-[A-Za-z0-9_\-]{20,}' }
    @{ Name = 'OpenRouter API key'; Pattern = 'sk-or-v1-[A-Fa-f0-9]{48,}' }
    @{ Name = 'OpenAI API key'; Pattern = 'sk-(?:proj-|svcacct-|admin-)?[A-Za-z0-9_\-]{32,}' }
    @{ Name = 'Google API key'; Pattern = 'AIza[0-9A-Za-z_\-]{35}' }
    @{ Name = 'Hugging Face token'; Pattern = 'hf_[A-Za-z0-9]{30,}' }
    @{ Name = 'Groq API key'; Pattern = 'gsk_[A-Za-z0-9]{40,}' }
    @{ Name = 'xAI API key'; Pattern = 'xai-[A-Za-z0-9]{40,}' }
    @{ Name = 'Replicate token'; Pattern = 'r8_[A-Za-z0-9]{30,}' }
    @{ Name = 'AWS access key id'; Pattern = '(?:AKIA|ASIA)[0-9A-Z]{16}' }
    @{ Name = 'GitHub token'; Pattern = 'gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{60,}' }
    @{ Name = 'Slack token'; Pattern = 'xox[abprs]-[A-Za-z0-9\-]{10,}' }
    @{ Name = 'Private key block'; Pattern = '-----BEGIN (?:RSA |EC |OPENSSH |DSA |ENCRYPTED )?PRIVATE KEY-----' }
)

function Find-WfxSecret {
    <# Finds well-known secret formats in text. Returns type + redacted value + line number; never the secret. #>
    param([AllowEmptyString()][string]$Text)
    $out = New-Object System.Collections.Generic.List[object]
    if ([string]::IsNullOrEmpty($Text)) { return , $out.ToArray() }
    $lines = $Text -split "`r?`n"
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $seen = @{}
        foreach ($p in $script:WfxSecretPatterns) {
            foreach ($m in [regex]::Matches($lines[$i], $p.Pattern)) {
                if ($seen.ContainsKey($m.Index)) { continue }   # one label per match position
                $seen[$m.Index] = $true
                $out.Add([pscustomobject]@{ Type = $p.Name; Line = $i + 1; Redacted = (Format-WfxSecret $m.Value) })
            }
        }
    }
    , $out.ToArray()
}

function Protect-WfxText {
    <# Redacts secrets and key=value credentials in free text before it is displayed or written to a report. #>
    param([AllowEmptyString()][string]$Text)
    if ([string]::IsNullOrEmpty($Text)) { return $Text }
    $t = $Text
    foreach ($p in $script:WfxSecretPatterns) { $t = [regex]::Replace($t, $p.Pattern, { param($m) Format-WfxSecret $m.Value }) }
    # key=value / "key value" credentials. The key name may be embedded in a larger identifier
    # (aws_secret_access_key, db-password, MYSQL_PWD), so allow an identifier prefix/suffix.
    $t = [regex]::Replace($t, '(?i)([A-Za-z0-9_.\-]{0,40}(?:password|passwd|pwd|secret|api[_-]?key|apikey|client[_-]?secret|access[_-]?key|token)[A-Za-z0-9_.\-]{0,20})(\s*[:=]\s*|\s+)("[^"]*"|''[^'']*''|[^\s;,&]+)', '$1$2***')
    # mysql/openssl-style concatenated password flag: -pSecret  (but not a lone -p)
    $t = [regex]::Replace($t, '(?i)(\s-p)(?!assword\b)([^\s]{2,})', '$1***')
    $t = [regex]::Replace($t, '(?i)(-(?:Password|Pass|Secret|Token|Key)\s+)("[^"]*"|''[^'']*''|\S+)', '$1***')
    $t = [regex]::Replace($t, '(?i)(/p(?:ass(?:word)?)?:)(\S+)', '$1***')
    $t = [regex]::Replace($t, '(?i)(\bnet1?\s+user\s+[^\s/]+\s+)([^\s/][^\s]*)', '$1***')
    $t = [regex]::Replace($t, '(?i)(\bschtasks[^\n]*\s/rp\s+)(\S+)', '$1***')
    $t = [regex]::Replace($t, '(?i)(https?://[^:/\s]+:)([^@\s]+)(@)', '$1***$3')
    return $t
}

# ───────────────────────────── paths & command lines ─────────────────────────────
function Get-WfxImagePath {
    <# Extracts the executable path from a command line / service ImagePath / Run value. #>
    param([AllowEmptyString()][string]$CommandLine)
    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return '' }
    $c = [Environment]::ExpandEnvironmentVariables($CommandLine.Trim())
    if ($c.StartsWith('"')) {
        $end = $c.IndexOf('"', 1)
        if ($end -gt 1) { return $c.Substring(1, $end - 1) }
    }
    $m = [regex]::Match($c, '^(.+?\.(?:exe|com|bat|cmd|ps1|vbs|js|jse|wsf|hta|scr|dll|msi|cpl|sys))(?=\s|,|$)', 'IgnoreCase')
    if ($m.Success) { return $m.Groups[1].Value }
    return ($c -split '\s+')[0]
}

function Get-WfxLeaf {
    param([AllowEmptyString()][string]$Path)
    if ([string]::IsNullOrEmpty($Path)) { return '' }
    return ($Path -split '[\\/]')[-1]
}

function Test-WfxUserWritablePath {
    <# True for locations ordinary users can write to — where malware stages itself. #>
    param([AllowEmptyString()][string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    $p = $Path.ToLowerInvariant() -replace '/', '\'
    return [bool]($p -match '\\appdata\\|\\temp\\|\\tmp\\|\\downloads\\|\\desktop\\|\\documents\\|\\users\\public\\|\\programdata\\|\\windows\\temp\\|\\windows\\tasks\\|\\windows\\tracing\\|\\perflogs\\|\\\$recycle\.bin\\|\\recycler\\|\\inetpub\\temp|\\windows\\debug\\|\\spool\\drivers\\color\\|\\music\\|\\videos\\|\\pictures\\' -or
        $p -match '^[a-z]:\\[^\\]+\.(exe|dll|ps1|bat|vbs|js|hta)$')
}

function Test-WfxSystemPath {
    param([AllowEmptyString()][string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    return [bool]($Path -match '(?i)^[a-z]:\\windows\\(system32|syswow64|winsxs)\\')
}

function Test-WfxPrivateIp {
    param([AllowEmptyString()][string]$Ip)
    if ([string]::IsNullOrWhiteSpace($Ip)) { return $true }
    $a = $Ip.Trim('[', ']')
    if ($a -match '^(?:0\.|10\.|127\.|169\.254\.|192\.168\.|172\.(?:1[6-9]|2\d|3[01])\.|100\.(?:6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.|22[4-9]\.|23\d\.|255\.)') { return $true }
    if ($a -match '(?i)^(?:::1?$|::$|fe8|fe9|fea|feb|fc|fd|ff)') { return $true }
    if ($a -match '(?i)^::ffff:(.+)$') { return (Test-WfxPrivateIp $Matches[1]) }
    return $false
}

function ConvertTo-WfxArray {
    <# PS 5.1-safe: always returns an array (handles $null and single objects). #>
    param($InputObject)
    if ($null -eq $InputObject) { return , @() }
    return , @($InputObject)
}

function Get-WfxValue {
    <# Reads a property that may not exist without tripping strict mode. #>
    param($Object, [string]$Name, $Default = $null)
    if ($null -eq $Object) { return $Default }
    if ($Object -is [hashtable] -or $Object -is [System.Collections.Specialized.OrderedDictionary]) {
        if ($Object.Contains($Name)) { return $Object[$Name] } else { return $Default }
    }
    $p = $Object.PSObject.Properties[$Name]
    if ($p) { return $p.Value }
    return $Default
}

# ───────────────────────────── case management ─────────────────────────────
function New-WfxCase {
    <# Creates the case folder (outputs, raw evidence, audit log) and records who ran what, where, when. #>
    param([string]$OutputPath = '', [string]$Name = '', [string]$HostName = '')
    if (-not $HostName) { $HostName = [Environment]::MachineName }
    if (-not $OutputPath) {
        $base = if (Test-WfxWindows) { Join-Path ([Environment]::GetFolderPath('Desktop')) 'WinForensicX' } else { Join-Path $HOME 'WinForensicX' }
        if (-not $base -or $base -eq 'WinForensicX') { $base = Join-Path (Get-Location) 'WinForensicX' }
        $OutputPath = $base
    }
    $stamp = (Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss') + 'Z'
    $safeHost = $HostName -replace '[^A-Za-z0-9._-]', '_'
    $folder = if ($Name) { ($Name -replace '[^A-Za-z0-9._-]', '_') + "_$safeHost`_$stamp" } else { "WFX_$safeHost`_$stamp" }
    $path = Join-Path $OutputPath $folder
    New-Item -ItemType Directory -Path (Join-Path $path 'raw') -Force | Out-Null
    $script:WfxCase = [pscustomobject]@{
        Id          = [guid]::NewGuid().ToString()
        Name        = $Name
        Path        = (Resolve-Path $path).Path
        Host        = $HostName
        StartedUtc  = (Get-Date).ToUniversalTime().ToString('o')
        Operator    = [Environment]::UserName
        OperatorHost = [Environment]::MachineName
        Admin       = (Test-WfxAdmin)
        PSVersion   = $PSVersionTable.PSVersion.ToString()
        ToolVersion = $script:WfxVersion
    }
    Clear-WfxGap
    Write-WfxLog -Event 'case-start' -Data @{ case = $script:WfxCase.Id; host = $HostName; operator = $script:WfxCase.Operator; admin = $script:WfxCase.Admin; ps = $script:WfxCase.PSVersion; tool = $script:WfxVersion }
    return $script:WfxCase
}

function Save-WfxJson {
    param([Parameter(Mandatory)]$InputObject, [Parameter(Mandatory)][string]$Path, [int]$Depth = 8)
    $json = ConvertTo-Json -InputObject $InputObject -Depth $Depth
    [IO.File]::WriteAllText($Path, $json, (New-Object Text.UTF8Encoding($false)))
}

function Complete-WfxCase {
    <# Writes manifest.json with SHA-256 of every output file (chain of custody) and closes the audit log. #>
    if (-not $script:WfxCase) { return }
    Write-WfxLog -Event 'case-end' -Data @{ case = $script:WfxCase.Id }
    $root = $script:WfxCase.Path
    $files = Get-ChildItem -LiteralPath $root -Recurse -File | Where-Object { $_.Name -ne 'manifest.json' } | Sort-Object FullName
    $entries = foreach ($f in $files) {
        [ordered]@{
            path   = $f.FullName.Substring($root.Length).TrimStart('\', '/') -replace '\\', '/'
            bytes  = $f.Length
            sha256 = (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
        }
    }
    $manifest = [ordered]@{
        case = $script:WfxCase.Id; host = $script:WfxCase.Host; tool = "WinForensicX $script:WfxVersion"
        operator = $script:WfxCase.Operator; started = $script:WfxCase.StartedUtc; completed = (Get-Date).ToUniversalTime().ToString('o')
        files = @($entries)
    }
    Save-WfxJson -InputObject $manifest -Path (Join-Path $root 'manifest.json')
}


# ===== Private/Help.ps1 =====
# Single source of truth for user-facing help: commands, examples, limitations, safety.
# Rendered to the terminal by Show-WfxHelp and to HTML by New-WfxGuide, so the two never drift.

function Get-WfxHelpModel {
    [pscustomobject]@{
        Version  = $script:WfxVersion
        Tagline  = 'Read-only DFIR / incident-triage for Windows. Collect a host, analyze it against ATT&CK-mapped rules, score the risk, and get a report you can act on.'
        Commands = @(
            [pscustomobject]@{ Name = 'Invoke-WfxTriage'; Summary = 'Collect -> analyze -> score -> report. The main command.'
                Params = @('[-FileScan] [-ExposureScan]', '-ComputerName <hosts> [-Credential <cred>]  (remote, WinRM)', '-EvtxPath <path>  (offline event logs)', '-InputPath <case>  (re-analyze saved evidence)')
                Examples = @('Invoke-WfxTriage', 'Invoke-WfxTriage -FileScan -ExposureScan', 'Invoke-WfxTriage -ComputerName srv01,srv02 -Credential (Get-Credential)', 'Invoke-WfxTriage -EvtxPath D:\evidence\Security.evtx', 'Invoke-WfxTriage -InputPath C:\cases\WFX_host_20260101-000000Z') }
            [pscustomobject]@{ Name = 'Invoke-WfxAnalyze'; Summary = 'Run all analyzers over a collected bundle (object, bundle.json, or case folder). OS-neutral.'
                Params = @('-Bundle <path|object>'); Examples = @('Invoke-WfxAnalyze -Bundle .\WFX_host\raw\bundle.json') }
            [pscustomobject]@{ Name = 'Start-WfxMonitor'; Summary = 'Live baseline, then alert on new suspicious processes / connections / beacons.'
                Params = @('[-Interval <sec>] [-Duration <sec>] [-MinSeverity <sev>]'); Examples = @('Start-WfxMonitor -Interval 5 -Duration 300') }
            [pscustomobject]@{ Name = 'Invoke-WfxHunt'; Summary = 'Sweep a host (or a saved bundle) for IOCs: hashes, IPs, domains, names, strings.'
                Params = @('-Ioc <list> [-InputPath <case>] [-FileScan]'); Examples = @("Invoke-WfxHunt -Ioc 'evil.com','1.2.3.4','5d41402abc4b2a76b9719d911017c592'") }
            [pscustomobject]@{ Name = 'Save-WfxEvidence'; Summary = 'Collect a hashed, read-only evidence bundle now; analyze later with -InputPath.'
                Params = @('[-FileScan] [-ExposureScan]'); Examples = @('Save-WfxEvidence -FileScan -ExposureScan') }
            [pscustomobject]@{ Name = 'Show-WfxMenu'; Summary = 'Interactive menu over everything above.'
                Params = @(); Examples = @('Show-WfxMenu') }
            [pscustomobject]@{ Name = 'Show-WfxHelp'; Summary = 'This help. Add -Html to open the full guide in a browser.'
                Params = @('[-Html]'); Examples = @('Show-WfxHelp', 'Show-WfxHelp -Html') }
        )
        Outputs  = @(
            'report.html   - self-contained triage report (open in any browser, offline)',
            'result.json   - findings + risk + ATT&CK coverage + gaps (machine-readable)',
            'findings.csv  - flat triage view for a spreadsheet / SIEM import',
            'raw/bundle.json - the normalized collected data (re-analyzable with -InputPath)',
            'audit.log     - every step the tool took, with timings (JSON lines)',
            'manifest.json - SHA-256 of every output file, written last (chain of custody)'
        )
        Safety   = @(
            'Strictly read-only: it observes, it does not change the host.',
            'Credential exposure is AUDITED, never extracted: it reports THAT a secret is exposed with the value redacted to type + length.',
            'No LSASS dumping, no SAM/NTDS hash parsing, no DPAPI/browser decryption, no exfiltration.',
            'Command lines, event messages and file contents are secret-scrubbed at collection time, so the raw bundle is safe to keep and ship.'
        )
        Limits   = @(
            'Findings are LEADS for an analyst, not verdicts. A finding means "look here," not "this host is compromised."',
            'Read findings alongside the collection gaps: with no process auditing and no Sysmon, "nothing found" mostly means "nothing could be seen" - the report says so.',
            'It is a TRIAGE tool, not a forensic imager. It does not acquire disk/memory images or carve deleted files.',
            'Detections are heuristic: expect some false positives and false negatives. Tune with custom rule packs ($env:WFX_RULES) and allowlist by finding Id + Entity.',
            'Administrator rights are recommended; without them some data is unavailable (recorded as gaps). Remote mode needs WinRM enabled on the target.',
            'It will not extract, decrypt, or dump secrets - that is a deliberate boundary, not a missing feature.'
        )
        Requires = 'Windows PowerShell 5.1 or PowerShell 7+. No external modules. Works on a standalone PC, a small business, or across a fleet.'
    }
}


# ===== Private/Rules.ps1 =====
# Rule packs: JSON files in Rules/ (or embedded in the single-file build), plus optional
# custom packs from a folder (-RulePath / $env:WFX_RULES). Regexes are compiled once, with a
# match timeout so a badly written community rule can never hang a triage.

$script:WfxRuleRoot = Join-Path (Split-Path -Parent $PSScriptRoot) 'Rules'
$script:WfxEmbeddedRules = @{}          # filled by the single-file build
$script:WfxRuleCache = @{}
$script:WfxCustomRulePath = $env:WFX_RULES
$script:WfxRegexTimeout = [TimeSpan]::FromMilliseconds(250)

function Set-WfxRulePath {
    <# Adds a folder of custom rule packs (files named <pack>.<anything>.json, e.g. lotl.mycompany.json). #>
    param([string]$Path)
    $script:WfxCustomRulePath = $Path
    $script:WfxRuleCache = @{}
}

function New-WfxRegex {
    param([string]$Pattern)
    if ([string]::IsNullOrEmpty($Pattern)) { return $null }
    return New-Object System.Text.RegularExpressions.Regex($Pattern, [System.Text.RegularExpressions.RegexOptions]::None, $script:WfxRegexTimeout)
}

function Test-WfxRegex {
    <# Regex match that treats a timeout as "no match" instead of throwing. #>
    param($Regex, [AllowEmptyString()][string]$Text)
    if ($null -eq $Regex -or [string]::IsNullOrEmpty($Text)) { return $false }
    try { return $Regex.IsMatch($Text) } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] { return $false }
}

function Read-WfxRuleJson {
    param([string]$Name)
    $docs = New-Object System.Collections.Generic.List[object]
    if ($script:WfxEmbeddedRules.ContainsKey($Name)) {
        $docs.Add(($script:WfxEmbeddedRules[$Name] | ConvertFrom-Json))
    } else {
        $file = Join-Path $script:WfxRuleRoot "$Name.json"
        if (Test-Path -LiteralPath $file) { $docs.Add((Get-Content -LiteralPath $file -Raw -Encoding UTF8 | ConvertFrom-Json)) }
    }
    if ($script:WfxCustomRulePath -and (Test-Path -LiteralPath $script:WfxCustomRulePath)) {
        foreach ($f in Get-ChildItem -LiteralPath $script:WfxCustomRulePath -Filter "$Name.*.json" -File) {
            try { $docs.Add((Get-Content -LiteralPath $f.FullName -Raw -Encoding UTF8 | ConvertFrom-Json)) }
            catch { Add-WfxGap -Source "rules:$($f.Name)" -Reason "custom rule pack could not be parsed: $($_.Exception.Message)" }
        }
    }
    return , $docs.ToArray()
}

function Get-WfxRulePack {
    <#
    .SYNOPSIS Returns a rule pack as an object; list-like packs get compiled regexes attached.
    .DESCRIPTION Packs: lotl (command-line rules), events (event-log rules), ai (AI services/runtimes),
    threats (RMM, tunnels, offensive tools, named pipes, drivers), dns (TLDs and services).
    #>
    param([Parameter(Mandatory)][string]$Name)
    if ($script:WfxRuleCache.ContainsKey($Name)) { return $script:WfxRuleCache[$Name] }
    $docs = Read-WfxRuleJson -Name $Name
    if ($docs.Count -eq 0) { throw "Rule pack '$Name' not found." }
    $pack = $docs[0]
    if ($pack.PSObject.Properties['rules']) {
        $all = New-Object System.Collections.Generic.List[object]
        foreach ($d in $docs) {
            foreach ($r in @($d.rules)) {
                if ($all | Where-Object { $_.id -eq $r.id }) { continue }   # first definition wins
                try {
                    $r | Add-Member -NotePropertyName rx -NotePropertyValue (New-WfxRegex $r.pattern) -Force
                    $ex = Get-WfxValue $r 'exclude'
                    $r | Add-Member -NotePropertyName rxExclude -NotePropertyValue (New-WfxRegex $ex) -Force
                    $imgs = @(Get-WfxValue $r 'images' @()) | ForEach-Object { ([string]$_).ToLowerInvariant() }
                    $r | Add-Member -NotePropertyName imageSet -NotePropertyValue @($imgs) -Force
                    $all.Add($r)
                } catch {
                    Add-WfxGap -Source "rules:$Name" -Reason "rule $($r.id) has an invalid pattern: $($_.Exception.Message)"
                }
            }
        }
        $pack | Add-Member -NotePropertyName rules -NotePropertyValue $all.ToArray() -Force
    }
    $script:WfxRuleCache[$Name] = $pack
    return $pack
}

function Test-WfxCommandLine {
    <#
    .SYNOPSIS Runs the command-line rule pack against one command line. Returns matching rules.
    .PARAMETER Image  Executable name or path; restricts image-specific rules. Inferred from the command line if omitted.
    #>
    param([AllowEmptyString()][string]$CommandLine, [string]$Image = '')
    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return @() }
    if (-not $Image) { $Image = Get-WfxImagePath $CommandLine }
    $leaf = (Get-WfxLeaf $Image).ToLowerInvariant()
    if ($leaf -and $leaf -notmatch '\.') { $leaf += '.exe' }
    $pack = Get-WfxRulePack -Name 'lotl'
    foreach ($r in $pack.rules) {
        if ($r.imageSet.Count -gt 0 -and $r.imageSet -notcontains $leaf) {
            # Image-specific rule: still applies when the binary is invoked through cmd/powershell in the same line.
            $named = $false
            foreach ($i in $r.imageSet) { if ($CommandLine -match ('(?i)(?:^|[\\/\s"''(;&|])' + [regex]::Escape(($i -replace '\.exe$', '')) + '(?:\.exe)?(?=[\s"'']|$)')) { $named = $true; break } }
            if (-not $named) { continue }
        }
        if (-not (Test-WfxRegex $r.rx $CommandLine)) { continue }
        if ($r.rxExclude -and (Test-WfxRegex $r.rxExclude $CommandLine)) { continue }
        $r
    }
}


# ===== Analyzers/Events.ps1 =====
# Event-log analyzer. Operates on normalized events:
#   { Log, Id, TimeCreated, Computer, Fields = @{ TargetUserName=…; IpAddress=…; NewProcessName=…; CommandLine=…; … } }
# Works identically on live logs and .evtx ingested from an image (collector normalizes both).

function Invoke-WfxEventAnalyzer {
    param([object[]]$Event, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $events = @($Event | Where-Object { $_ })
    if ($events.Count -eq 0) { return , $findings.ToArray() }
    $pack = Get-WfxRulePack -Name 'events'

    $f = { param($e, $k) Get-WfxValue (Get-WfxValue $e 'Fields' @{}) $k '' }

    # ── Per-event rules (Sigma-lite) ──
    foreach ($e in $events) {
        $id = [int](Get-WfxValue $e 'Id' 0)
        foreach ($rule in $pack.rules) {
            if (@($rule.eventIds) -notcontains $id) { continue }
            if ($rule.PSObject.Properties['perEvent'] -and -not $rule.perEvent) { continue }   # aggregate-only rule, handled below
            $text = @($rule.fields | ForEach-Object { [string](& $f $e $_) }) -join ' '
            if ($text.Trim() -eq '' -and $rule.fields) { $text = [string](Get-WfxValue $e 'Message' '') }

            if ($rule.pattern -eq '__lotl__') {
                foreach ($r in (Test-WfxCommandLine -CommandLine $text)) {
                    $findings.Add((New-WfxFinding -Id $r.id -Title "$($r.title) (event $id)" -Severity $r.severity -Confidence $r.confidence `
                                -Category 'EventLog' -Technique $r.technique -Description $r.description -Recommendation $r.recommendation `
                                -Entity "event:${id}:$([string](& $f $e 'NewProcessName'))" -HostName $HostName -Time (Get-WfxValue $e 'TimeCreated') -Source "evt:$($e.Log)" `
                                -Evidence ([ordered]@{ EventId = $id; Command = (Protect-WfxText $text); Parent = (& $f $e 'ParentProcessName') })))
                }
                continue
            }
            if ($rule.pattern) {
                $rx = New-WfxRegex $rule.pattern
                if (-not (Test-WfxRegex $rx $text)) { continue }
            }
            $findings.Add((New-WfxFinding -Id $rule.id -Title $rule.title -Severity $rule.severity -Confidence $rule.confidence `
                        -Category 'EventLog' -Technique $rule.technique -Description $rule.description -Recommendation $rule.recommendation `
                        -Entity "event:$($rule.id):$([string](& $f $e ($rule.fields[0])))" -HostName $HostName -Time (Get-WfxValue $e 'TimeCreated') -Source "evt:$($e.Log)" `
                        -Evidence ([ordered]@{ EventId = $id; Time = (Get-WfxValue $e 'TimeCreated'); Details = (Protect-WfxText $text) })))
        }
    }

    # ── Aggregate rules: failed-logon bursts and spraying (4625) ──
    $fails = @($events | Where-Object { [int](Get-WfxValue $_ 'Id' 0) -eq 4625 })
    if ($fails.Count -ge 10) {
        $bySource = $fails | Group-Object { [string](& $f $_ 'IpAddress') }
        foreach ($g in $bySource) {
            $users = @($g.Group | ForEach-Object { [string](& $f $_ 'TargetUserName') } | Where-Object { $_ } | Sort-Object -Unique)
            $src = if ($g.Name) { $g.Name } else { '(unknown source)' }
            if ($g.Count -ge 10 -and $users.Count -ge 5) {
                $findings.Add((New-WfxFinding -Id 'EVT-4625-SPRAY' -Title "Password spraying from $src ($($users.Count) accounts, $($g.Count) failures)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'EventLog' -Technique @('T1110.003') `
                            -Description "Many failed logons for many different accounts from one source — the signature of password spraying." `
                            -Recommendation "Block the source, confirm no logon succeeded, and enforce lockout + MFA." `
                            -Entity "spray:$src" -HostName $HostName -Source 'evt:Security' `
                            -Evidence ([ordered]@{ Source = $src; Accounts = $users.Count; Failures = $g.Count; Sample = ($users | Select-Object -First 8) })))
            } elseif ($g.Count -ge 20 -and $users.Count -le 2) {
                $findings.Add((New-WfxFinding -Id 'EVT-4625-BRUTE' -Title "Brute force on $($users -join ',') from $src ($($g.Count) failures)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'EventLog' -Technique @('T1110') `
                            -Description "Many failed logons for one or two accounts from one source — a password-guessing attack." `
                            -Recommendation "Block the source and confirm whether a success (4624) followed." `
                            -Entity "brute:$src" -HostName $HostName -Source 'evt:Security' `
                            -Evidence ([ordered]@{ Source = $src; Accounts = $users; Failures = $g.Count })))
            }
        }
    }

    # ── Correlation: repeated failures then a success from the same source ──
    $successes = @($events | Where-Object { [int](Get-WfxValue $_ 'Id' 0) -eq 4624 -and [string](& $f $_ 'LogonType') -in @('2', '3', '7', '10', '11') })
    foreach ($s in $successes) {
        $src = [string](& $f $s 'IpAddress'); $user = [string](& $f $s 'TargetUserName')
        if (-not $src -or (Test-WfxPrivateIp $src) -eq $false) {
            if ($src -and -not (Test-WfxPrivateIp $src) -and [string](& $f $s 'LogonType') -in @('10', '7')) {
                $findings.Add((New-WfxFinding -Id 'EVT-RDP-EXTERNAL' -Title "Remote logon for $user from external address $src" `
                            -Severity 'Medium' -Confidence 'Medium' -Category 'EventLog' -Technique @('T1021.001', 'T1133') `
                            -Description "An interactive/remote-desktop logon succeeded from a public IP. Internet-facing RDP is a frequent intrusion vector." `
                            -Recommendation "Confirm the source is expected; restrict RDP behind VPN/MFA." `
                            -Entity "rdp:${src}:$user" -HostName $HostName -Time (Get-WfxValue $s 'TimeCreated') -Source 'evt:Security' `
                            -Evidence ([ordered]@{ User = $user; Source = $src; LogonType = (& $f $s 'LogonType'); Time = (Get-WfxValue $s 'TimeCreated') })))
            }
        }
        $priorFails = @($fails | Where-Object { [string](& $f $_ 'TargetUserName') -eq $user -and [string](& $f $_ 'IpAddress') -eq $src })
        if ($user -and $priorFails.Count -ge 8) {
            $findings.Add((New-WfxFinding -Id 'EVT-4625-THEN-4624' -Title "Successful logon for $user after $($priorFails.Count) failures (same source)" `
                        -Severity 'High' -Confidence 'High' -Category 'EventLog' -Technique @('T1110') `
                        -Description "An account failed to log on repeatedly, then succeeded, from the same source — consistent with a guessed or sprayed password." `
                        -Recommendation "Reset the password, review the session's activity, and investigate the source host." `
                        -Entity "cracked:${src}:$user" -HostName $HostName -Time (Get-WfxValue $s 'TimeCreated') -Source 'evt:Security' `
                        -Evidence ([ordered]@{ User = $user; Source = $src; PriorFailures = $priorFails.Count; SuccessTime = (Get-WfxValue $s 'TimeCreated') })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Exposure.ps1 =====
# Secrets-exposure & security-hygiene analyzer.
#
# This is a DEFENSIVE audit: it reports WHERE sensitive material or a misconfiguration exists and
# WHY it is a risk, so it can be remediated. It never emits secret values — matches are redacted to a
# type + length via Find-WfxSecret / Format-WfxSecret — and it does not read, copy, decrypt or parse
# credential stores (SAM/NTDS, browser login DBs, DPAPI, LSASS). Detecting exposure needs none of that.
#
# Input: normalized exposure records the collector builds:
#   { Kind, Path, Detail, Accessible, WorldReadable, Content (small text only, for secret scanning) }
# Kind ∈ GppCpassword, UnattendPassword, SensitiveHive, ShadowCopy, CredFileWorldReadable,
#        SecretInFile, SecretInEnv, SecretInHistory, AiKey, SshKeyUnprotected, AutoLogon.

function Invoke-WfxExposureAnalyzer {
    param([object[]]$Exposure, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $items = @($Exposure | Where-Object { $_ })
    if ($items.Count -eq 0) { return , $findings.ToArray() }

    foreach ($x in $items) {
        $kind = [string](Get-WfxValue $x 'Kind' '')
        $path = [string](Get-WfxValue $x 'Path' '')
        $detail = [string](Get-WfxValue $x 'Detail' '')
        $content = [string](Get-WfxValue $x 'Content' '')
        $entity = "exposure:$kind`:$path"

        switch ($kind) {
            'GppCpassword' {
                $findings.Add((New-WfxFinding -Id 'EXPO-GPP-CPASSWORD' -Title "Group Policy Preferences password (MS14-025): $(Get-WfxLeaf $path)" `
                            -Severity 'Critical' -Confidence 'High' -Category 'Exposure' -Technique @('T1552.006') `
                            -Description "A GPP XML file contains a cPassword. Microsoft published the decryption key in 2014, so any domain user can recover this password. It is one of the most reliable privilege-escalation findings in a Windows domain." `
                            -Recommendation "Remove the GPP that sets the password, change the affected account's password, and apply KB2962486. Use Windows LAPS to manage local admin passwords instead." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path })))
            }
            'UnattendPassword' {
                $findings.Add((New-WfxFinding -Id 'EXPO-UNATTEND-PASSWORD' -Title "Credential in an unattended-install file: $(Get-WfxLeaf $path)" `
                            -Severity 'High' -Confidence 'High' -Category 'Exposure' -Technique @('T1552.001') `
                            -Description "A Windows unattended-setup file contains a password (sometimes only Base64-wrapped, not encrypted). These are readable by anyone who can reach the file." `
                            -Recommendation "Remove the file or the password element, and rotate the account's password." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path })))
            }
            'SensitiveHive' {
                $acc = [bool](Get-WfxValue $x 'Accessible' $false)
                $findings.Add((New-WfxFinding -Id 'EXPO-HIVE-ACCESS' -Title "$detail readable by non-administrators" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Exposure' -Technique @('T1003.002') `
                            -Description "A registry hive or database that stores password material ($detail) is accessible to accounts that should not be able to read it. An attacker could copy it and recover hashes offline." `
                            -Recommendation "Restore correct ACLs (only SYSTEM/Administrators). If the file is a stray backup, remove it. Review how it became readable." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path; Accessible = $acc })))
            }
            'ShadowCopy' {
                $findings.Add((New-WfxFinding -Id 'EXPO-SHADOW-COPY' -Title "Volume shadow copies present ($detail)" `
                            -Severity 'Low' -Confidence 'Low' -Category 'Exposure' -Technique @('T1003.002') `
                            -Description "Volume Shadow Copies exist. They are useful for recovery, but also let an attacker with admin rights read otherwise-locked files such as the SAM hive. Reported for awareness, not as a compromise." `
                            -Recommendation "This is informational. Ensure admin access to the host is tightly controlled." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Detail = $detail })))
            }
            'CredFileWorldReadable' {
                $findings.Add((New-WfxFinding -Id 'EXPO-CREDFILE-READABLE' -Title "Credential file readable by other users: $(Get-WfxLeaf $path)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Exposure' -Technique @('T1552.001') `
                            -Description "A file that normally holds credentials ($detail) can be read by users other than its owner. On a shared machine this exposes those credentials." `
                            -Recommendation "Restrict the file's permissions to its owner, and rotate any credentials it contains." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path; Detail = $detail })))
            }
            'AutoLogon' {
                $findings.Add((New-WfxFinding -Id 'EXPO-AUTOLOGON' -Title "Automatic logon password stored in the registry" `
                            -Severity 'High' -Confidence 'High' -Category 'Exposure' -Technique @('T1552.001') `
                            -Description "A DefaultPassword is stored in clear text under Winlogon for automatic logon. Any local user can read it." `
                            -Recommendation "Disable auto-logon, or use the LSA-secrets method; rotate the password." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Account = $detail })))
            }
            'SshKeyUnprotected' {
                $findings.Add((New-WfxFinding -Id 'EXPO-SSH-KEY' -Title "Unencrypted SSH private key: $(Get-WfxLeaf $path)" `
                            -Severity 'Medium' -Confidence 'Medium' -Category 'Exposure' -Technique @('T1552.004') `
                            -Description "An SSH private key is stored without a passphrase. If this host or file is compromised, the key can be used directly to reach whatever it unlocks." `
                            -Recommendation "Add a passphrase (ssh-keygen -p), restrict the file's permissions, and rotate the key if exposure is suspected." `
                            -Entity $entity -HostName $HostName -Source 'exposure' -Evidence ([ordered]@{ Path = $path })))
            }
            'AiKey' {
                $findings.Add((New-WfxFinding -Id 'AI-KEY-EXPOSED' -Title "AI provider API key in clear text: $detail" `
                            -Severity 'High' -Confidence 'High' -Category 'Exposure' -Technique @('T1552.001') `
                            -Description "An API key for an AI provider was found in clear text ($detail). These keys are billable and often broadly scoped; a leaked key can be abused immediately and run up cost." `
                            -Recommendation "Revoke and rotate the key with the provider, remove it from the file/variable, and store it in a secret manager." `
                            -Entity $entity -HostName $HostName -Source 'exposure' `
                            -Evidence ([ordered]@{ Where = $path; Type = $detail; Redacted = (Get-WfxValue $x 'Redacted' '') })))
            }
            { $_ -in @('SecretInFile', 'SecretInEnv', 'SecretInHistory') } {
                $where = switch ($kind) { 'SecretInFile' { "file $path" } 'SecretInEnv' { "environment variable $detail" } 'SecretInHistory' { "command history ($path)" } }
                # Prefer a redaction the collector already computed (so the raw value never enters a record
                # that might be persisted). Fall back to scanning Content when a caller supplied it directly.
                $preRedacted = @(Get-WfxValue $x 'Redacted' @() | Where-Object { $_ })
                $secrets = if ($content) { Find-WfxSecret $content } else { @() }
                $redactedList = if ($preRedacted.Count) { $preRedacted } else { @($secrets | ForEach-Object { "$($_.Type) (line $($_.Line)): $($_.Redacted)" }) }
                $label = if ($detail) { $detail } elseif ($secrets) { ($secrets | Select-Object -First 1).Type } elseif ($preRedacted.Count) { (($preRedacted[0] -split ' \(line| \(env')[0]) } else { 'credential-like string' }
                $sev = if ($kind -eq 'SecretInHistory') { 'Medium' } else { 'High' }
                $findings.Add((New-WfxFinding -Id "EXPO-$($kind.ToUpper())" -Title "Possible secret in $where" `
                            -Severity $sev -Confidence 'Low' -Category 'Exposure' -Technique @('T1552.001') `
                            -Description "Text that looks like a credential ($label) was found in $where. Clear-text secrets can be read by anyone (or any malware) with access to this location." `
                            -Recommendation "Confirm whether it is a live secret; if so, rotate it and move it to a secret store. Avoid passing secrets on the command line (they land in history and logs)." `
                            -Entity $entity -HostName $HostName -Source 'exposure' `
                            -Evidence ([ordered]@{ Where = $where; Type = $label; Redacted = $redactedList })))
            }
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Files.ps1 =====
# File and web-shell analyzer. Operates on normalized file records the collector produces:
#   { Path, Directory, Extension, Length, LastWrite, Content (first N KB, optional), Entropy (optional),
#     SignatureStatus, Zone (MOTW), InWebRoot }
# Content is only read for small text files in web roots / script locations, and is never emitted raw —
# only rule ids, a short redacted snippet and line numbers.

# Signatures that indicate a web shell. Each: id, regex, languages, description.
$script:WfxWebShellSigs = @(
    @{ Id = 'eval-request'; Rx = '(?i)\b(?:eval|assert|system|exec|shell_exec|passthru|popen|proc_open)\s*\(\s*(?:\$_(?:GET|POST|REQUEST|COOKIE|SERVER)|request|base64_decode|gzinflate|str_rot13)'; Desc = 'Executes attacker-supplied input from an HTTP request.' }
    @{ Id = 'aspx-process'; Rx = '(?i)(?:Process\.Start|ProcessStartInfo|cmd\.exe|/c\s|Server\.CreateObject\("WScript\.Shell"\)|Runtime\.getRuntime\(\)\.exec)'; Desc = 'Spawns an OS process from a web page.' }
    @{ Id = 'jsp-runtime'; Rx = '(?i)Runtime\.getRuntime\(\)\.exec|ProcessBuilder\(|<%@\s*page\s+import="java\.(?:io|lang)'; Desc = 'Java/JSP page that executes commands.' }
    @{ Id = 'webshell-named'; Rx = '(?i)\b(?:c99|r57|b374k|wso|weevely|china\s*chopper|antsword|behinder|godzilla|p0wny|reGeorg|tunna)\b'; Desc = 'Matches a known web-shell family name/marker.' }
    @{ Id = 'obf-eval'; Rx = '(?i)(?:eval|assert)\s*\(\s*(?:base64_decode|gzinflate|gzuncompress|str_rot13|convert_uudecode)\s*\('; Desc = 'Obfuscated code execution (packed/encoded payload).' }
    @{ Id = 'preg-e'; Rx = '(?i)preg_replace\s*\(\s*["''][^"'']*/[a-z]*e[a-z]*["'']'; Desc = 'preg_replace /e modifier — legacy PHP code execution.' }
    @{ Id = 'create-function'; Rx = '(?i)\b(?:create_function|call_user_func(?:_array)?)\s*\(\s*(?:\$_(?:GET|POST|REQUEST)|base64_decode)'; Desc = 'Builds and calls a function from request input.' }
)

function Invoke-WfxFileAnalyzer {
    param([object[]]$File, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $files = @($File | Where-Object { $_ })
    if ($files.Count -eq 0) { return , $findings.ToArray() }
    $executable = @('.exe', '.dll', '.scr', '.com', '.pif', '.cpl', '.sys', '.ocx')
    $script = @('.ps1', '.bat', '.cmd', '.vbs', '.vbe', '.js', '.jse', '.wsf', '.hta', '.jar')

    foreach ($rec in $files) {
        $path = [string](Get-WfxValue $rec 'Path' '')
        $ext = ([string](Get-WfxValue $rec 'Extension' '')).ToLowerInvariant()
        if (-not $ext -and $path) { $ext = [IO.Path]::GetExtension($path).ToLowerInvariant() }
        $content = [string](Get-WfxValue $rec 'Content' '')
        $inWeb = [bool](Get-WfxValue $rec 'InWebRoot' $false)
        $zone = [string](Get-WfxValue $rec 'Zone' '')
        $entity = "file:$path"

        # 1. Web shells
        if ($content -and ($inWeb -or $ext -in @('.php', '.asp', '.aspx', '.ashx', '.asmx', '.jsp', '.jspx', '.phtml', '.php5', '.cfm'))) {
            foreach ($sig in $script:WfxWebShellSigs) {
                $m = [regex]::Match($content, $sig.Rx)
                if ($m.Success) {
                    $line = ($content.Substring(0, $m.Index) -split "`n").Count
                    $snippet = Protect-WfxText ($content.Substring([Math]::Max(0, $m.Index - 10), [Math]::Min(90, $content.Length - [Math]::Max(0, $m.Index - 10))))
                    $findings.Add((New-WfxFinding -Id 'FILE-WEBSHELL' -Title "Possible web shell in $(Get-WfxLeaf $path)" `
                                -Severity 'Critical' -Confidence 'Medium' -Category 'File' -Technique @('T1505.003', 'T1190') `
                                -Description "A file served by a web application contains code that runs commands or executes request input ($($sig.Desc)). Web shells give attackers remote control of a server." `
                                -Recommendation "Isolate the web server, preserve the file, and review web access logs for requests to it. Determine how it was written (upload flaw, vulnerable app)." `
                                -Entity $entity -HostName $HostName -Time (Get-WfxValue $rec 'LastWrite') -Source 'file' `
                                -Evidence ([ordered]@{ Path = $path; Signature = $sig.Id; Line = $line; Snippet = $snippet; LastWrite = (Get-WfxValue $rec 'LastWrite') })))
                    break
                }
            }
        }

        # 2. Double extension masquerade (e.g. invoice.pdf.exe)
        if ($path -match '(?i)\.(pdf|doc|docx|xls|xlsx|jpg|jpeg|png|txt|csv|zip|rtf)\.(exe|scr|com|pif|bat|cmd|vbs|js|hta|lnk)$') {
            $findings.Add((New-WfxFinding -Id 'FILE-DOUBLE-EXT' -Title "Double-extension file: $(Get-WfxLeaf $path)" `
                        -Severity 'High' -Confidence 'High' -Category 'File' -Technique @('T1036') `
                        -Description "The file name hides its real type behind a fake document/image extension — a classic trick to get users to run malware." `
                        -Recommendation "Do not open it. Hash and analyze it, and find how it reached the host." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $rec 'LastWrite') -Source 'file' `
                        -Evidence ([ordered]@{ Path = $path; LastWrite = (Get-WfxValue $rec 'LastWrite') })))
        }

        # 3. Executable/script downloaded from the internet (Mark-of-the-Web), in a user folder
        if (($ext -in $executable -or $ext -in $script) -and $zone -match '3|4' -and (Test-WfxUserWritablePath $path)) {
            $findings.Add((New-WfxFinding -Id 'FILE-MOTW-EXEC' -Title "Internet-downloaded executable in a user folder: $(Get-WfxLeaf $path)" `
                        -Severity 'Medium' -Confidence 'Medium' -Category 'File' -Technique @('T1105', 'T1204.002') `
                        -Description "An executable or script carrying a Mark-of-the-Web (downloaded from the internet) sits in a user-writable folder." `
                        -Recommendation "Hash it and check reputation; confirm the user intended to download and run it." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $rec 'LastWrite') -Source 'file' `
                        -Evidence ([ordered]@{ Path = $path; Zone = $zone; SHA256 = (Get-WfxValue $rec 'SHA256'); LastWrite = (Get-WfxValue $rec 'LastWrite') })))
        }

        # 4. High-entropy executable in a user folder (packed/encrypted payload)
        $entropy = [double](Get-WfxValue $rec 'Entropy' 0)
        if ($ext -in $executable -and $entropy -ge 7.2 -and (Test-WfxUserWritablePath $path)) {
            $findings.Add((New-WfxFinding -Id 'FILE-PACKED' -Title "Highly compressed/encrypted executable: $(Get-WfxLeaf $path)" `
                        -Severity 'Low' -Confidence 'Low' -Category 'File' -Technique @('T1027') `
                        -Description "The executable's content is near-random (entropy $entropy/8), which is typical of packed or encrypted malware (but also of some legitimate installers)." `
                        -Recommendation "Submit the hash to threat intelligence; treat as suspicious if from an unknown source." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $rec 'LastWrite') -Source 'file' `
                        -Evidence ([ordered]@{ Path = $path; Entropy = $entropy; SHA256 = (Get-WfxValue $rec 'SHA256') })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}

# ─────────────────────────── ransomware note / mass-change heuristic ───────────────────────────
function Invoke-WfxRansomwareAnalyzer {
    <#
    .SYNOPSIS Flags ransom notes and bursts of newly-created encrypted-looking files.
    .PARAMETER Note  Candidate ransom-note files: { Path, Content }
    .PARAMETER RecentFile  Recently modified files: { Path, Extension, Entropy, LastWrite }
    #>
    param([object[]]$Note = @(), [object[]]$RecentFile = @(), [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $noteRx = '(?i)(your files (?:have been|are) (?:encrypted|locked)|all your (?:files|data|documents)|decrypt(?:ion)?\s+(?:key|tool|service|id)|bitcoin|\.onion|recover (?:your )?files|how_to_(?:decrypt|recover)|readme.*decrypt|pay(?:ment)? .*(?:ransom|decrypt)|contact us.*(?:tox|telegram|protonmail|session id))'
    foreach ($n in @($Note | Where-Object { $_ })) {
        $c = [string](Get-WfxValue $n 'Content' '')
        $hits = ([regex]::Matches($c, $noteRx)).Count
        if ($hits -ge 2) {
            $findings.Add((New-WfxFinding -Id 'RANSOM-NOTE' -Title "Possible ransom note: $(Get-WfxLeaf ([string](Get-WfxValue $n 'Path' '')))" `
                        -Severity 'Critical' -Confidence 'Medium' -Category 'Ransomware' -Technique @('T1486') `
                        -Description "A file reads like a ransomware ransom note (encryption claim, payment/decryption instructions)." `
                        -Recommendation "Isolate the host from the network immediately. Preserve evidence, identify the family, and check backups and other hosts." `
                        -Entity "file:$([string](Get-WfxValue $n 'Path' ''))" -HostName $HostName -Source 'file' `
                        -Evidence ([ordered]@{ Path = (Get-WfxValue $n 'Path'); Markers = $hits })))
        }
    }
    $recent = @($RecentFile | Where-Object { $_ })
    $encLike = @($recent | Where-Object {
            $e = ([string](Get-WfxValue $_ 'Extension' '')).ToLowerInvariant()
            $e -match '^\.(?:encrypt(?:ed)?|locked|crypt(?:ed)?|enc|crypto|[a-z0-9]{5,8})$' -and $e -notmatch '^\.(?:exe|dll|docx|xlsx|pptx|jpeg|config|manifest)$' -and ([double](Get-WfxValue $_ 'Entropy' 0) -ge 7.4)
        })
    if ($encLike.Count -ge 25) {
        $exts = @($encLike | ForEach-Object { ([string](Get-WfxValue $_ 'Extension' '')).ToLowerInvariant() } | Group-Object | Sort-Object Count -Descending | Select-Object -First 1)
        $findings.Add((New-WfxFinding -Id 'RANSOM-MASS-ENCRYPT' -Title "Mass creation of encrypted-looking files ($($encLike.Count))" `
                    -Severity 'Critical' -Confidence 'Medium' -Category 'Ransomware' -Technique @('T1486') `
                    -Description "A large number of recently written files have random (high-entropy) content and uniform unusual extensions — consistent with active ransomware encryption." `
                    -Recommendation "Isolate the host now and stop the responsible process. Preserve a sample and the ransom note before any remediation." `
                    -Entity 'ransom:mass-encrypt' -HostName $HostName -Source 'file' `
                    -Evidence ([ordered]@{ Files = $encLike.Count; TopExtension = ($exts.Name); Sample = (@($encLike | Select-Object -First 5 | ForEach-Object { Get-WfxValue $_ 'Path' })) })))
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Network.ps1 =====
# Network and DNS analyzers. Pure functions over normalized data.
#   Connection: Protocol, LocalAddress, LocalPort, RemoteAddress, RemotePort, State, Pid, Process
#   DnsEntry:   Name, Type, Data, (optional) Count
#   Beacon samples: { Remote, Times[] } (connection timestamps to one destination)

function Invoke-WfxNetworkAnalyzer {
    param([object[]]$Connection, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $conns = @($Connection | Where-Object { $_ })
    if ($conns.Count -eq 0) { return , $findings.ToArray() }

    $dns = Get-WfxRulePack -Name 'dns'
    $ai = Get-WfxRulePack -Name 'ai'
    $tunnelHosts = @($dns.tunnelDomains)
    $aiPorts = @($ai.runtimePorts)

    # Listeners on all interfaces (0.0.0.0 / ::) for non-standard ports.
    $commonListen = @(80, 443, 135, 139, 445, 3389, 5985, 5986, 53, 88, 389, 636, 464, 3268, 3269, 25, 110, 143, 993, 995, 1433, 3306, 5432, 22)
    foreach ($c in $conns) {
        $state = [string](Get-WfxValue $c 'State' '')
        $laddr = [string](Get-WfxValue $c 'LocalAddress' '')
        $lport = [int](Get-WfxValue $c 'LocalPort' 0)
        $proc = [string](Get-WfxValue $c 'Process' '')
        $pid2 = Get-WfxValue $c 'Pid' '?'
        if ($state -match 'Listen' -and ($laddr -eq '0.0.0.0' -or $laddr -eq '::' -or $laddr -eq '[::]' -or $laddr -eq '*')) {
            if ($commonListen -notcontains $lport) {
                $isAi = $aiPorts -contains $lport
                $findings.Add((New-WfxFinding -Id ($(if ($isAi) { 'AI-OLLAMA-EXPOSED' } else { 'NET-LISTENER-EXPOSED' })) `
                            -Title ($(if ($isAi) { "Local AI runtime API exposed on all interfaces (port $lport)" } else { "Process listening on all interfaces on non-standard port $lport" })) `
                            -Severity 'Medium' -Confidence ($(if ($isAi) { 'Medium' } else { 'Low' })) -Category 'Network' `
                            -Technique @('T1133') `
                            -Description ($(if ($isAi) { "A local AI model runtime is listening on 0.0.0.0:$lport. Its API is usually unauthenticated, so anyone who can reach the port can use the model and run it at this host's expense." } else { "A process is listening for connections from any network on an unusual port. Confirm it is an expected service and not a backdoor or exposed dev server." })) `
                            -Recommendation ($(if ($isAi) { "Bind the runtime to 127.0.0.1 and restrict the port with the firewall." } else { "Identify the process and confirm the service is intended to be network-reachable." })) `
                            -Entity "listen:${laddr}:$lport" -HostName $HostName -Source 'network' `
                            -Evidence ([ordered]@{ Pid = $pid2; Process = $proc; Local = "${laddr}:$lport"; Protocol = (Get-WfxValue $c 'Protocol' 'TCP') })))
            }
        }

        # Established connections to public addresses on suspicious / tunneling ports or hosts.
        $raddr = [string](Get-WfxValue $c 'RemoteAddress' '')
        $rport = [int](Get-WfxValue $c 'RemotePort' 0)
        if ($state -match 'Establish' -and $raddr -and -not (Test-WfxPrivateIp $raddr)) {
            $rhost = [string](Get-WfxValue $c 'RemoteHost' '')
            $tun = $tunnelHosts | Where-Object { $rhost -and $rhost.ToLowerInvariant().EndsWith($_) }
            if ($tun) {
                $findings.Add((New-WfxFinding -Id 'NET-TUNNEL-SERVICE' -Title "Connection to a tunneling service ($tun)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Network' -Technique @('T1572', 'T1090') `
                            -Description "A connection to an ad-hoc tunneling service was found. $($dns.tunnelNote)" `
                            -Recommendation "Identify the process and what it exposes; block the service if unauthorized." `
                            -Entity "conn:${raddr}:$rport" -HostName $HostName -Source 'network' `
                            -Evidence ([ordered]@{ Pid = $pid2; Process = $proc; Remote = "$rhost ($raddr):$rport" })))
            }
            if ($rport -in @(4444, 5555, 1337, 31337, 8081, 6666, 6667, 9001, 9002, 1234, 12345, 50050)) {
                $findings.Add((New-WfxFinding -Id 'NET-SUSPICIOUS-PORT' -Title "Connection to a commonly malicious port ($rport)" `
                            -Severity 'Medium' -Confidence 'Low' -Category 'Network' -Technique @('T1571', 'T1071') `
                            -Description "An outbound connection targets a port frequently used by C2 frameworks and reverse shells (e.g. Metasploit 4444, Cobalt Strike 50050)." `
                            -Recommendation "Identify the process and destination reputation; this is suggestive, not conclusive." `
                            -Entity "conn:${raddr}:$rport" -HostName $HostName -Source 'network' `
                            -Evidence ([ordered]@{ Pid = $pid2; Process = $proc; Remote = "${raddr}:$rport" })))
            }
            # A non-browser process talking to an AI provider API (billable key use / possible agent exfil path).
            $rhostL = $rhost.ToLowerInvariant()
            if ($rhost -and ($ai.apiDomains | Where-Object { $rhostL -like "*$_*" })) {
                $leaf = (Get-WfxLeaf $proc).ToLowerInvariant()
                if ($leaf -and $leaf -notin @('chrome.exe', 'msedge.exe', 'firefox.exe', 'brave.exe', 'opera.exe')) {
                    $findings.Add((New-WfxFinding -Id 'AI-API-NONBROWSER' -Title "Non-browser process contacting an AI provider API: $leaf" `
                                -Severity 'Info' -Confidence 'Low' -Category 'AI' -Technique @() `
                                -Description "A process other than a web browser is talking to an AI provider's API. Usually benign (a CLI or app), but worth noting when an API key or data exposure is in scope." `
                                -Recommendation "Confirm the tool and that it uses an authorized API key." `
                                -Entity "conn:${leaf}:$rhostL" -HostName $HostName -Source 'network' `
                                -Evidence ([ordered]@{ Pid = $pid2; Process = $leaf; Remote = $rhost })))
                }
            }
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}

function Invoke-WfxDnsAnalyzer {
    param([object[]]$DnsEntry, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $entries = @($DnsEntry | Where-Object { $_ })
    if ($entries.Count -eq 0) { return , $findings.ToArray() }
    $dns = Get-WfxRulePack -Name 'dns'

    foreach ($e in $entries) {
        $fqdn = ([string](Get-WfxValue $e 'Name' '')).Trim('.').ToLowerInvariant()
        if (-not $fqdn -or $fqdn -notmatch '\.') { continue }
        $labels = $fqdn -split '\.'
        $tld = '.' + $labels[-1]
        $reg = if ($labels.Count -ge 2) { $labels[-2] } else { $labels[-1] }

        if ($dns.suspiciousTlds -contains $tld) {
            $findings.Add((New-WfxFinding -Id 'DNS-SUSPICIOUS-TLD' -Title "Lookup of a high-risk TLD domain: $fqdn" `
                        -Severity 'Low' -Confidence 'Low' -Category 'DNS' -Technique @('T1071.004') `
                        -Description "The domain uses a top-level domain disproportionately associated with malware and abuse ($tld)." `
                        -Recommendation "Check the domain's reputation and which process resolved it." `
                        -Entity "dns:$fqdn" -HostName $HostName -Source 'dns' -Evidence ([ordered]@{ Name = $fqdn; TLD = $tld })))
        }
        if ($dns.tunnelDomains | Where-Object { $fqdn.EndsWith($_) }) {
            $findings.Add((New-WfxFinding -Id 'DNS-TUNNEL-SERVICE' -Title "Lookup of a tunneling service: $fqdn" `
                        -Severity 'Medium' -Confidence 'Medium' -Category 'DNS' -Technique @('T1572') `
                        -Description "A tunneling/relay service domain was resolved. $($dns.tunnelNote)" `
                        -Recommendation "Identify the process and whether a tunnel was established." `
                        -Entity "dns:$fqdn" -HostName $HostName -Source 'dns' -Evidence ([ordered]@{ Name = $fqdn })))
        }
        if ($dns.pasteSites | Where-Object { $fqdn -eq $_ -or $fqdn.EndsWith('.' + $_) }) {
            $findings.Add((New-WfxFinding -Id 'DNS-PASTE-SITE' -Title "Lookup of a paste / anonymous-file site: $fqdn" `
                        -Severity 'Low' -Confidence 'Low' -Category 'DNS' -Technique @('T1105', 'T1567') `
                        -Description "A text-paste or anonymous file-sharing site was resolved. $($dns.pasteNote)" `
                        -Recommendation "Check which process accessed it and whether a payload was fetched or data uploaded." `
                        -Entity "dns:$fqdn" -HostName $HostName -Source 'dns' -Evidence ([ordered]@{ Name = $fqdn })))
        }
        # DGA-like: long, high-entropy registrable label, few vowels.
        $entropy = Get-WfxEntropy $reg
        $vowels = ([regex]::Matches($reg, '[aeiou]')).Count
        $digits = ([regex]::Matches($reg, '\d')).Count
        if ($reg.Length -ge 12 -and $entropy -ge 3.6 -and ($vowels / [double]$reg.Length) -lt 0.28 -and $reg -notmatch '^(?:xn--|www\d*$)') {
            $findings.Add((New-WfxFinding -Id 'DNS-DGA-LIKE' -Title "High-entropy domain (possible DGA): $fqdn" `
                        -Severity 'Medium' -Confidence 'Low' -Category 'DNS' -Technique @('T1568.002', 'T1071.004') `
                        -Description "The domain's name looks algorithmically generated (long, random-looking, few vowels). Malware families use domain-generation algorithms for C2 that is hard to block by name." `
                        -Recommendation "Check reputation and resolution history; correlate with connections from the resolving process." `
                        -Entity "dns:$fqdn" -HostName $HostName -Source 'dns' `
                        -Evidence ([ordered]@{ Name = $fqdn; Entropy = $entropy; Length = $reg.Length; Digits = $digits })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}

function Invoke-WfxBeaconAnalyzer {
    <#
    .SYNOPSIS Flags regular, low-jitter connections to one destination (C2 beaconing).
    .PARAMETER Beacon  Objects with Remote (string) and Times (datetime[] of connection events).
    #>
    param([object[]]$Beacon, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    foreach ($b in @($Beacon | Where-Object { $_ })) {
        $times = @(Get-WfxValue $b 'Times' @() | ForEach-Object { [datetime]$_ } | Sort-Object)
        if ($times.Count -lt 6) { continue }
        $deltas = for ($i = 1; $i -lt $times.Count; $i++) { ($times[$i] - $times[$i - 1]).TotalSeconds }
        $deltas = @($deltas | Where-Object { $_ -gt 0 })
        if ($deltas.Count -lt 5) { continue }
        $mean = ($deltas | Measure-Object -Average).Average
        if ($mean -lt 1) { continue }
        $var = ($deltas | ForEach-Object { ($_ - $mean) * ($_ - $mean) } | Measure-Object -Average).Average
        $cv = [Math]::Sqrt($var) / $mean      # coefficient of variation: low = very regular
        if ($cv -le 0.18) {
            $sev = if ($mean -ge 30 -and $mean -le 3600) { 'High' } else { 'Medium' }
            $findings.Add((New-WfxFinding -Id 'NET-BEACON' -Title ("Regular beaconing to $([string](Get-WfxValue $b 'Remote' '?')) (~{0:N0}s)" -f $mean) `
                        -Severity $sev -Confidence 'Medium' -Category 'Network' -Technique @('T1071.001', 'T1573') `
                        -Description "Connections to this destination arrive at a near-constant interval with very little variation ($($deltas.Count + 1) connections, jitter $([Math]::Round($cv*100))%). Regular, low-jitter check-ins are a hallmark of C2 beaconing." `
                        -Recommendation "Identify the process and destination; check the destination's reputation. Legitimate software also polls on a schedule, so confirm before acting." `
                        -Entity "beacon:$([string](Get-WfxValue $b 'Remote' '?'))" -HostName $HostName -Source 'network' `
                        -Evidence ([ordered]@{ Remote = (Get-WfxValue $b 'Remote'); Connections = $times.Count; MeanSeconds = [Math]::Round($mean, 1); JitterPct = [Math]::Round($cv * 100, 1) })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Persistence.ps1 =====
# Persistence analyzer. Operates on normalized autostart entries:
#   { Kind, Name, Command, Path, Location, User, Enabled, SignatureStatus }
# Kind ∈ RunKey, Startup, Service, ScheduledTask, WmiSubscription, Winlogon, AppInit, ImageFileExecution,
#         ComHijack, LsaProvider, BootExecute, Driver, OfficeAddin, BrowserExtension.

function Invoke-WfxPersistenceAnalyzer {
    param([object[]]$Autostart, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $items = @($Autostart | Where-Object { $_ })
    if ($items.Count -eq 0) { return , $findings.ToArray() }

    $threats = Get-WfxRulePack -Name 'threats'
    $drivers = @($threats.vulnerableDrivers | ForEach-Object { $_.ToLowerInvariant() })

    foreach ($a in $items) {
        $kind = [string](Get-WfxValue $a 'Kind' '')
        $name = [string](Get-WfxValue $a 'Name' '')
        $cmd = [string](Get-WfxValue $a 'Command' '')
        $path = [string](Get-WfxValue $a 'Path' '')
        if (-not $path -and $cmd) { $path = Get-WfxImagePath $cmd }
        $loc = [string](Get-WfxValue $a 'Location' '')
        $sig = [string](Get-WfxValue $a 'SignatureStatus' '')
        $entity = "autostart:$kind`:$name"
        $userWritable = (Test-WfxUserWritablePath $path) -or (Test-WfxUserWritablePath $cmd)

        # Command-line rules apply to the autostart command too (encoded PS, proxy exec, etc.)
        foreach ($r in (Test-WfxCommandLine -CommandLine $cmd -Image $path)) {
            $findings.Add((New-WfxFinding -Id $r.id -Title "$($r.title) (in $kind persistence)" -Severity $r.severity -Confidence $r.confidence `
                        -Category 'Persistence' -Technique $r.technique -Description $r.description -Recommendation $r.recommendation `
                        -Entity $entity -HostName $HostName -Source 'persistence' `
                        -Evidence ([ordered]@{ Kind = $kind; Name = $name; Location = $loc; Command = (Protect-WfxText $cmd) })))
        }

        # High-signal persistence locations are suspicious on their own.
        $highSignal = @{
            'WmiSubscription'     = @('T1546.003', 'A WMI event subscription runs code when a system event fires. Rarely legitimate and a favourite stealthy persistence mechanism.')
            'AppInit'             = @('T1546.010', 'AppInit_DLLs loads a DLL into almost every process. Legacy and heavily abused.')
            'ImageFileExecution'  = @('T1546.012', 'An Image File Execution Options debugger hijacks a program so an attacker binary runs in its place (also used to disable security tools).')
            'ComHijack'           = @('T1546.015', 'A COM object was redirected to a user-controlled DLL/command — a quiet persistence and defense-evasion trick.')
            'LsaProvider'         = @('T1547.004', 'A security/authentication package was registered with LSA, which can capture credentials and persist.')
            'Winlogon'            = @('T1547.004', 'A Winlogon helper (Shell/Userinit/Notify) was modified to run extra code at logon.')
            'BootExecute'         = @('T1547.001', 'A BootExecute entry runs before the user logs on and is very rarely changed legitimately.')
        }
        if ($highSignal.ContainsKey($kind)) {
            $info = $highSignal[$kind]
            $sev = if ($userWritable -or ($sig -and $sig -notin @('Valid', 'Signed', 'Trusted', ''))) { 'High' } else { 'Medium' }
            $findings.Add((New-WfxFinding -Id "PERSIST-$($kind.ToUpper())" -Title "$kind persistence: $name" -Severity $sev -Confidence 'Medium' `
                        -Category 'Persistence' -Technique @($info[0]) -Description $info[1] `
                        -Recommendation "Confirm this entry is expected; capture and analyze the referenced code before removing it." `
                        -Entity $entity -HostName $HostName -Source 'persistence' `
                        -Evidence ([ordered]@{ Kind = $kind; Name = $name; Location = $loc; Command = (Protect-WfxText $cmd); Path = $path; Signature = $sig })))
        }

        # Run keys / startup / services / tasks pointing at user-writable or unsigned binaries.
        if ($kind -in @('RunKey', 'Startup', 'Service', 'ScheduledTask') -and ($userWritable -or ($sig -and $sig -notin @('Valid', 'Signed', 'Trusted', '')))) {
            $tech = switch ($kind) { 'RunKey' { 'T1547.001' } 'Startup' { 'T1547.001' } 'Service' { 'T1543.003' } 'ScheduledTask' { 'T1053.005' } }
            $findings.Add((New-WfxFinding -Id "PERSIST-$($kind.ToUpper())-SUSPECT" -Title "$kind autostart from an untrusted location: $name" `
                        -Severity 'Medium' -Confidence 'Medium' -Category 'Persistence' -Technique @($tech) `
                        -Description "A $kind autostart entry runs a program that is unsigned or located in a user-writable folder — a common way malware survives reboot." `
                        -Recommendation "Verify the program's publisher and purpose; remove if not legitimate." `
                        -Entity $entity -HostName $HostName -Source 'persistence' `
                        -Evidence ([ordered]@{ Kind = $kind; Name = $name; Location = $loc; Path = $path; Signature = $sig; Command = (Protect-WfxText $cmd) })))
        }

        # Known-vulnerable driver used for BYOVD.
        if ($kind -eq 'Driver') {
            $leaf = (Get-WfxLeaf $path).ToLowerInvariant()
            if ($drivers -contains $leaf) {
                $findings.Add((New-WfxFinding -Id 'PERSIST-VULN-DRIVER' -Title "Known-vulnerable driver installed: $leaf" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Persistence' -Technique @('T1068', 'T1562.001') `
                            -Description "A driver known to be abused in bring-your-own-vulnerable-driver attacks is present. $($threats.vulnerableDriverNote)" `
                            -Recommendation "Confirm the driver is required. If not, remove it; attackers use these to disable EDR and gain kernel access." `
                            -Entity $entity -HostName $HostName -Source 'persistence' `
                            -Evidence ([ordered]@{ Driver = $leaf; Path = $path; Signature = $sig })))
            } elseif ($userWritable) {
                $findings.Add((New-WfxFinding -Id 'PERSIST-DRIVER-USERPATH' -Title "Driver loaded from a user-writable path: $(Get-WfxLeaf $path)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Persistence' -Technique @('T1014') `
                            -Description "A kernel driver is loaded from an unusual, user-writable location. Legitimate drivers live under System32\drivers." `
                            -Recommendation "Verify the driver's signature and origin." `
                            -Entity $entity -HostName $HostName -Source 'persistence' -Evidence ([ordered]@{ Path = $path; Signature = $sig })))
            }
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Posture.ps1 =====
# Security-posture analyzer. Turns the posture object from Get-WfxSecurityData into findings about
# defensive gaps: disabled/evaded AV, suspicious Defender exclusions (a common tamper IOC), missing
# audit logging (a visibility gap, so "no findings" is interpreted correctly), weak RDP, and LSASS
# protection. These are hardening/visibility findings, not proof of compromise — severities reflect that.

function Invoke-WfxPostureAnalyzer {
    param($Posture, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    if (-not $Posture) { return , $findings.ToArray() }

    $def = Get-WfxValue $Posture 'Defender' $null
    $thirdParty = @(Get-WfxValue $Posture 'ThirdPartyAV' @())
    $hasThirdParty = $thirdParty.Count -gt 0

    # ── Defender: real-time protection / AV off with no third-party engine ──
    if ($def -and (Get-WfxValue $def 'Installed' $false)) {
        $rtp = Get-WfxValue $def 'RealTimeProtectionEnabled' $null
        $av = Get-WfxValue $def 'AntivirusEnabled' $null
        if (($rtp -eq $false -or $av -eq $false) -and -not $hasThirdParty) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-AV-DISABLED' -Title 'Antivirus real-time protection is OFF (no other AV present)' `
                        -Severity 'High' -Confidence 'High' -Category 'Posture' -Technique @('T1562.001') `
                        -Description "Microsoft Defender real-time/antivirus protection is disabled and no third-party AV is registered. The host is running without active malware protection — this is often the first thing an intruder disables." `
                        -Recommendation "Re-enable real-time protection, confirm it was not disabled by malware or GPO, and review when and by what it was turned off." `
                        -Entity 'posture:defender:rtp' -HostName $HostName -Source 'posture' `
                        -Evidence ([ordered]@{ RealTimeProtection = $rtp; AntivirusEnabled = $av; ThirdPartyAV = $thirdParty })))
        }
        # Tamper protection off
        if ((Get-WfxValue $def 'TamperProtectionEnabled' $null) -eq $false) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-TAMPER-OFF' -Title 'Defender Tamper Protection is off' `
                        -Severity 'Low' -Confidence 'Medium' -Category 'Posture' -Technique @('T1562.001') `
                        -Description "Tamper Protection is disabled, so Defender settings can be changed by local admin tools or malware without resistance." `
                        -Recommendation "Enable Tamper Protection (Windows Security > Virus & threat protection settings)." `
                        -Entity 'posture:defender:tamper' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ TamperProtection = $false })))
        }
        # Stale signatures
        $sigAge = Get-WfxValue $def 'SignatureAgeDays' $null
        if ($null -ne $sigAge -and [int]$sigAge -ge 7) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-SIG-STALE' -Title "Antivirus signatures are $sigAge days old" `
                        -Severity 'Medium' -Confidence 'High' -Category 'Posture' -Technique @('T1562.001') `
                        -Description "Defender definitions have not updated in $sigAge days. Detection of recent threats is degraded; updates may be blocked (no connectivity, disabled service, or deliberate tampering)." `
                        -Recommendation "Force a signature update and investigate why updates stopped." `
                        -Entity 'posture:defender:sigage' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ SignatureAgeDays = $sigAge })))
        }
        # Suspicious exclusions — attackers add these to carve out a safe folder for their tools.
        $exPaths = @(Get-WfxValue $def 'ExclusionPath' @())
        foreach ($ex in $exPaths) {
            $broadOrWritable = ($ex -match '(?i)^[a-z]:\\?$' -or $ex -match '(?i)\\$' -and $ex.Length -le 4) -or (Test-WfxUserWritablePath $ex) -or ($ex -match '(?i)\\(users|temp|tmp|downloads|appdata|programdata|public)\b')
            if ($broadOrWritable) {
                $findings.Add((New-WfxFinding -Id 'POSTURE-DEFENDER-EXCLUSION' -Title "Suspicious Defender exclusion: $ex" `
                            -Severity 'Medium' -Confidence 'Medium' -Category 'Posture' -Technique @('T1562.001') `
                            -Description "Defender is configured to ignore '$ex'. Broad or user-writable exclusions are a classic way for an attacker to make a folder where their tools won't be scanned. Verify it was set intentionally." `
                            -Recommendation "Confirm the business reason for this exclusion; remove it if unexplained and scan the excluded location." `
                            -Entity "posture:defender:exclusion:$ex" -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ Exclusion = $ex })))
            }
        }
        $exProc = @(Get-WfxValue $def 'ExclusionProcess' @())
        foreach ($ep in $exProc) {
            if ($ep -match '(?i)(powershell|cmd|wscript|cscript|mshta|rundll32|regsvr32|python|node)\b') {
                $findings.Add((New-WfxFinding -Id 'POSTURE-DEFENDER-PROC-EXCLUSION' -Title "Defender process exclusion for an interpreter: $ep" `
                            -Severity 'Medium' -Confidence 'Medium' -Category 'Posture' -Technique @('T1562.001') `
                            -Description "Defender is told not to scan activity by '$ep'. Excluding a scripting interpreter effectively blinds AV to script-based attacks." `
                            -Recommendation "Remove the exclusion unless there is a strong, documented reason." `
                            -Entity "posture:defender:procexcl:$ep" -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ Process = $ep })))
            }
        }
    } elseif ($def -and -not (Get-WfxValue $def 'Installed' $false) -and -not $hasThirdParty) {
        $findings.Add((New-WfxFinding -Id 'POSTURE-NO-AV' -Title 'No antivirus engine detected' `
                    -Severity 'Medium' -Confidence 'Low' -Category 'Posture' -Technique @('T1562.001') `
                    -Description "Neither Microsoft Defender status nor a third-party AV could be read. The host may have no active AV, or status collection was blocked." `
                    -Recommendation "Confirm an AV product is installed, running and updating." `
                    -Entity 'posture:av:none' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ ThirdPartyAV = $thirdParty })))
    }

    # ── Logging visibility ──
    $audit = Get-WfxValue $Posture 'Audit' $null
    if ($audit) {
        $sysmon = Get-WfxValue $audit 'SysmonInstalled' $false
        if ((Get-WfxValue $audit 'ProcessCreation' $false) -eq $false -and -not $sysmon) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-NO-PROCESS-AUDIT' -Title 'Process-creation auditing is off (4688 / Sysmon absent)' `
                        -Severity 'Medium' -Confidence 'High' -Category 'Visibility' -Technique @('T1562.002') `
                        -Description "Neither Security 4688 process-creation auditing nor Sysmon is active. Most process-based detections in this tool and in any SIEM are blind on this host — absence of findings here does not mean absence of activity." `
                        -Recommendation "Enable 'Audit Process Creation' (Success) via GPO, or deploy Sysmon. Also enable command-line auditing." `
                        -Entity 'posture:audit:proc' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ ProcessCreationAudit = $false; Sysmon = $sysmon })))
        }
        if ((Get-WfxValue $audit 'CommandLineInProcessCreation' $false) -eq $false -and -not $sysmon) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-NO-CMDLINE-AUDIT' -Title 'Command-line logging in 4688 is disabled' `
                        -Severity 'Low' -Confidence 'High' -Category 'Visibility' -Technique @('T1562.002') `
                        -Description "Process-creation events will not include command lines, so encoded/abusive command lines cannot be reviewed after the fact." `
                        -Recommendation "Enable 'Include command line in process creation events' via GPO." `
                        -Entity 'posture:audit:cmdline' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ CommandLineAudit = $false })))
        }
        if ((Get-WfxValue $audit 'ScriptBlockLogging' $false) -eq $false) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-NO-SCRIPTBLOCK-LOG' -Title 'PowerShell script-block logging is off' `
                        -Severity 'Medium' -Confidence 'High' -Category 'Visibility' -Technique @('T1562.002') `
                        -Description "PowerShell Script Block Logging (4104) is disabled, so malicious/obfuscated PowerShell leaves little forensic trace. PowerShell is one of the most abused tools in intrusions." `
                        -Recommendation "Enable Script Block Logging via GPO (Administrative Templates > Windows Components > Windows PowerShell)." `
                        -Entity 'posture:audit:sbl' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ ScriptBlockLogging = $false })))
        }
    }

    # ── Firewall ──
    $fw = Get-WfxValue $Posture 'Firewall' $null
    if ($fw) {
        $off = @()
        foreach ($p in @('Domain', 'Private', 'Public')) { if ((Get-WfxValue $fw $p $true) -eq $false) { $off += $p } }
        if ($off.Count -gt 0) {
            $findings.Add((New-WfxFinding -Id 'POSTURE-FIREWALL-OFF' -Title "Windows Firewall disabled on profile(s): $($off -join ', ')" `
                        -Severity 'Medium' -Confidence 'High' -Category 'Posture' -Technique @('T1562.004') `
                        -Description "One or more firewall profiles are turned off, widening the host's network exposure. Attackers disable the firewall to enable lateral movement and inbound tooling." `
                        -Recommendation "Re-enable the firewall on all profiles and confirm it was not disabled by malware or an overly broad policy." `
                        -Entity 'posture:firewall' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ Disabled = $off })))
        }
    }

    # ── RDP without NLA ──
    $rdp = Get-WfxValue $Posture 'Rdp' $null
    if ($rdp -and (Get-WfxValue $rdp 'Enabled' $false) -and (Get-WfxValue $rdp 'NlaEnabled' $true) -eq $false) {
        $findings.Add((New-WfxFinding -Id 'POSTURE-RDP-NO-NLA' -Title 'RDP is enabled without Network Level Authentication' `
                    -Severity 'Medium' -Confidence 'High' -Category 'Posture' -Technique @('T1021.001') `
                    -Description "Remote Desktop is accepting connections without NLA, which weakens protection against unauthenticated and brute-force attacks on the RDP service." `
                    -Recommendation "Require NLA for RDP, restrict it to a VPN/jump host, and enforce account lockout + MFA where possible." `
                    -Entity 'posture:rdp:nla' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ RdpEnabled = $true; NLA = $false })))
    }

    # ── LSASS not protected (informational hardening) ──
    $lsa = Get-WfxValue $Posture 'Lsa' $null
    if ($lsa -and (Get-WfxValue $lsa 'RunAsPPL' $false) -eq $false -and (Get-WfxValue $lsa 'CredentialGuard' $false) -ne $true) {
        $findings.Add((New-WfxFinding -Id 'POSTURE-LSASS-UNPROTECTED' -Title 'LSASS is not running as a protected process (no PPL / Credential Guard)' `
                    -Severity 'Low' -Confidence 'Medium' -Category 'Posture' -Technique @('T1003.001') `
                    -Description "LSASS has neither RunAsPPL nor Credential Guard enabled, so credential material in memory is easier for an admin-level attacker to access. This is a hardening gap, not evidence of compromise." `
                    -Recommendation "Enable LSA Protection (RunAsPPL) and, where supported, Credential Guard." `
                    -Entity 'posture:lsa:ppl' -HostName $HostName -Source 'posture' -Evidence ([ordered]@{ RunAsPPL = $false; CredentialGuard = (Get-WfxValue $lsa 'CredentialGuard' $null) })))
    }

    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Analyzers/Process.ps1 =====
# Process analyzer: turns a normalized process list into findings. Pure function — no WMI,
# no platform calls — so it runs and is tested anywhere. Each process object is expected to have:
#   Pid, Ppid, Name, Path, CommandLine, User, ParentName, ParentPath, SignatureStatus, Company, CreateTime.

# Legit parents for sensitive system processes (lowercased leaf names).
$script:WfxExpectedParents = @{
    'lsass.exe'    = @('wininit.exe')
    'services.exe' = @('wininit.exe')
    'wininit.exe'  = @('smss.exe', '')
    'csrss.exe'    = @('smss.exe', '')
    'smss.exe'     = @('smss.exe', 'system', '')
    'winlogon.exe' = @('smss.exe', '')
    'lsaiso.exe'   = @('wininit.exe')
    'spoolsv.exe'  = @('services.exe')
    'taskhostw.exe' = @('services.exe', 'svchost.exe')
}
# Processes that should only ever run from System32/SysWOW64.
$script:WfxSystem32Only = @('svchost.exe', 'lsass.exe', 'services.exe', 'wininit.exe', 'csrss.exe',
    'smss.exe', 'winlogon.exe', 'spoolsv.exe', 'conhost.exe', 'dllhost.exe', 'taskhostw.exe',
    'runtimebroker.exe', 'searchindexer.exe', 'sihost.exe', 'fontdrvhost.exe', 'lsaiso.exe')
# Office / browser / mail processes that should not normally spawn script interpreters.
$script:WfxOfficeParents = @('winword.exe', 'excel.exe', 'powerpnt.exe', 'outlook.exe', 'onenote.exe',
    'mspub.exe', 'msaccess.exe', 'visio.exe', 'wordpad.exe', 'acrord32.exe', 'acrobat.exe')
$script:WfxBrowserParents = @('chrome.exe', 'msedge.exe', 'firefox.exe', 'brave.exe', 'opera.exe', 'iexplore.exe')
$script:WfxScriptChildren = @('powershell.exe', 'pwsh.exe', 'cmd.exe', 'mshta.exe', 'wscript.exe',
    'cscript.exe', 'rundll32.exe', 'regsvr32.exe', 'certutil.exe', 'bitsadmin.exe', 'curl.exe',
    'msbuild.exe', 'installutil.exe', 'schtasks.exe')

function Invoke-WfxProcessAnalyzer {
    param([object[]]$Process, [string]$HostName = '')
    $findings = New-Object System.Collections.Generic.List[object]
    $procs = @($Process | Where-Object { $_ })
    if ($procs.Count -eq 0) { return , $findings.ToArray() }

    $threats = Get-WfxRulePack -Name 'threats'
    $ai = Get-WfxRulePack -Name 'ai'
    $offensive = @($threats.offensiveProcesses | ForEach-Object { $_.ToLowerInvariant() })
    $rmm = @($threats.rmmProcesses | ForEach-Object { $_.ToLowerInvariant() })
    $aiRuntime = @($ai.runtimeProcesses | ForEach-Object { $_.ToLowerInvariant() })
    $aiAssist = @($ai.assistantProcesses | ForEach-Object { $_.ToLowerInvariant() })
    $byPid = @{}
    foreach ($p in $procs) { if ($null -ne $p.Pid) { $byPid[[string]$p.Pid] = $p } }

    foreach ($p in $procs) {
        $name = (Get-WfxLeaf (Get-WfxValue $p 'Name' '')).ToLowerInvariant()
        if (-not $name) { $name = (Get-WfxLeaf (Get-WfxValue $p 'Path' '')).ToLowerInvariant() }
        $path = [string](Get-WfxValue $p 'Path' '')
        $cmd = [string](Get-WfxValue $p 'CommandLine' '')
        $parent = (Get-WfxLeaf (Get-WfxValue $p 'ParentName' '')).ToLowerInvariant()
        $entity = "process:$(Get-WfxValue $p 'Pid' '?'):$name"
        $sig = [string](Get-WfxValue $p 'SignatureStatus' '')
        $pcmd = [string](Get-WfxValue $p 'ParentCommandLine' '')

        # 1. Command-line rules (the big one — LotL, proxy exec, cred access, recovery inhibition…)
        foreach ($r in (Test-WfxCommandLine -CommandLine $cmd -Image $path)) {
            $findings.Add((New-WfxFinding -Id $r.id -Title $r.title -Severity $r.severity -Confidence $r.confidence `
                        -Category 'Process' -Technique $r.technique -Description $r.description -Recommendation $r.recommendation `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Parent = $parent; CommandLine = (Protect-WfxText $cmd); Path = $path })))
        }

        # 2. Masquerading: system-process name running from the wrong place
        if ($script:WfxSystem32Only -contains $name -and $path -and -not (Test-WfxSystemPath $path)) {
            $findings.Add((New-WfxFinding -Id 'PROC-SYSNAME-WRONGPATH' -Title "System process name '$name' running from an unusual path" `
                        -Severity 'High' -Confidence 'High' -Category 'Process' -Technique @('T1036.005') `
                        -Description "A process using the name of a core Windows binary is running from outside System32/SysWOW64. Malware often copies a trusted name to blend in." `
                        -Recommendation "Verify the image path and signature. The real $name runs only from the Windows system folders." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path; Parent = $parent })))
        }

        # 3. Parent spoofing of sensitive processes
        if ($script:WfxExpectedParents.ContainsKey($name) -and $parent) {
            if ($script:WfxExpectedParents[$name] -notcontains $parent) {
                $findings.Add((New-WfxFinding -Id 'PROC-PARENT-SPOOF' -Title "$name has an unexpected parent ($parent)" `
                            -Severity 'High' -Confidence 'Medium' -Category 'Process' -Technique @('T1055.012', 'T1036') `
                            -Description "Core Windows processes are started by a fixed parent. A different parent can indicate process hollowing or a masqueraded binary." `
                            -Recommendation "Expected parent for $name is $($script:WfxExpectedParents[$name] -join '/'). Investigate the parent process." `
                            -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                            -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Parent = $parent; Path = $path })))
            }
        }

        # 4. Office / browser spawning a script interpreter → likely malicious document or exploit
        if (($script:WfxOfficeParents -contains $parent -or $script:WfxBrowserParents -contains $parent) -and $script:WfxScriptChildren -contains $name) {
            $isOffice = $script:WfxOfficeParents -contains $parent
            $findings.Add((New-WfxFinding -Id ($(if ($isOffice) { 'PROC-OFFICE-SPAWN' } else { 'PROC-BROWSER-SPAWN' })) `
                        -Title "$parent spawned $name" -Severity 'High' -Confidence 'Medium' -Category 'Process' `
                        -Technique @('T1204.002', 'T1059.001') `
                        -Description "$(if ($isOffice) {'An Office application'} else {'A web browser'}) started a scripting tool. This is the classic result of a malicious document or a browser exploit/ClickFix lure." `
                        -Recommendation "Review the command line and what $parent opened (recent documents / browser history) just before this ran." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Parent = $parent; CommandLine = (Protect-WfxText $cmd); ParentCommandLine = (Protect-WfxText $pcmd) })))
        }

        # 5. Unsigned / untrusted binary from a user-writable location
        if ($path -and (Test-WfxUserWritablePath $path) -and $name -notin @('', 'explorer.exe')) {
            $untrusted = $sig -and $sig -notin @('Valid', 'Signed', 'Trusted', '')
            if ($untrusted) {
                $findings.Add((New-WfxFinding -Id 'PROC-UNSIGNED-USERPATH' -Title "Unsigned process running from a user-writable folder: $name" `
                            -Severity 'Medium' -Confidence 'Medium' -Category 'Process' -Technique @('T1036') `
                            -Description "An unsigned or untrusted executable is running from a location any user can write to — a common staging pattern for malware." `
                            -Recommendation "Hash the file and check it against threat intelligence; confirm the publisher." `
                            -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                            -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path; Signature = $sig; Parent = $parent })))
            }
        }

        # 6. Known offensive / hacking tools
        if ($offensive | Where-Object { $name -eq $_ -or ($_ -notmatch '\.' -and $name -like "*$_*") }) {
            $findings.Add((New-WfxFinding -Id 'PROC-OFFENSIVE-TOOL' -Title "Offensive security tool running: $name" `
                        -Severity 'High' -Confidence 'Medium' -Category 'Process' -Technique @('T1003.001', 'T1558.003') `
                        -Description "A process matching a known credential-dumping, C2 or attack tool is running. $($threats.offensiveNote)" `
                        -Recommendation "Confirm whether an authorized test is in progress. If not, treat the host as compromised." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path; CommandLine = (Protect-WfxText $cmd) })))
        }

        # 7. Remote-management (RMM) tools — attacker persistence / access on endpoints
        if ($rmm -contains $name) {
            $findings.Add((New-WfxFinding -Id 'PROC-RMM-TOOL' -Title "Remote-management tool running: $name" `
                        -Severity 'Low' -Confidence 'Low' -Category 'Process' -Technique @('T1219') `
                        -Description "A remote access / RMM tool is running. These are legitimate, but intruders frequently install one for durable access, especially if it is not your standard tool." `
                        -Recommendation "Confirm this RMM tool is sanctioned on this host and tied to a known administrator." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path })))
        }

        # 8. AI-era context (informational): local LLM runtime + AI assistant with shell access
        if ($aiRuntime -contains $name) {
            $findings.Add((New-WfxFinding -Id 'AI-RUNTIME-PRESENT' -Title "Local AI model runtime running: $name" `
                        -Severity 'Info' -Confidence 'High' -Category 'AI' -Technique @() `
                        -Description "A local large-language-model runtime is running. Noted for context: these often expose an unauthenticated API on localhost (see network findings)." `
                        -Recommendation "Confirm it is bound to localhost and not reachable from the network." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name; Path = $path })))
        }
        if ($aiAssist -contains $name) {
            $findings.Add((New-WfxFinding -Id 'AI-ASSISTANT-PRESENT' -Title "AI assistant / agent running: $name" `
                        -Severity 'Info' -Confidence 'Low' -Category 'AI' -Technique @('T1204.004') `
                        -Description "An AI coding assistant or agent capable of running commands is present. Relevant when attributing activity: some commands may have been generated and run by this tool." `
                        -Recommendation "If reconstructing a timeline, consider this tool as a possible actor for shell activity." `
                        -Entity $entity -HostName $HostName -Time (Get-WfxValue $p 'CreateTime') -Source 'process' `
                        -Evidence ([ordered]@{ Pid = $p.Pid; Process = $name })))
        }
    }
    return , (Merge-WfxFinding -Finding $findings.ToArray())
}


# ===== Collectors/Bundle.ps1 =====
# Collection aggregator — runs the collectors and returns ONE normalized bundle object.
# This is the single unit of data that: (a) the analyzers consume, (b) gets saved as raw evidence,
# and (c) is shipped back from a remote WinRM session. Every field is already OS-neutral and (for
# exposure) pre-redacted, so the bundle is safe to serialize and move off-box.

function Get-WfxCollectionBundle {
    <#
    .SYNOPSIS Collects all triage data into one bundle. Each section degrades to [] on error (recorded as a gap).
    .PARAMETER Hours        Event look-back window (live mode).
    .PARAMETER EvtxPath     Analyze events from exported .evtx instead of the live log.
    .PARAMETER FileScan     Include the web-root / drop-folder file scan (can be slower).
    .PARAMETER ExposureScan Include the deeper config-file secret scan.
    .PARAMETER Sections     Limit collection to these sections (default: all).
    #>
    param(
        [int]$Hours = 72,
        [string]$EvtxPath = '',
        [switch]$FileScan,
        [switch]$ExposureScan,
        [ValidateSet('Host', 'Process', 'Network', 'Dns', 'Persistence', 'Events', 'Files', 'Exposure', 'Security')]
        [string[]]$Sections = @('Host', 'Process', 'Network', 'Dns', 'Persistence', 'Events', 'Files', 'Exposure', 'Security')
    )
    $want = @{}; foreach ($s in $Sections) { $want[$s] = $true }
    Clear-WfxGap

    $hostInfo = if ($want.Host) { Get-WfxHostInfo } else { $null }
    $procs = if ($want.Process) { @(Get-WfxProcessData) } else { @() }
    $net = if ($want.Network) { @(Get-WfxNetworkData) } else { @() }
    $dns = if ($want.Dns) { @(Get-WfxDnsData) } else { @() }

    $persist = @()
    if ($want.Persistence) { $persist = @(Get-WfxPersistenceData) + @(Get-WfxServiceAndDriver) }

    $events = @()
    if ($want.Events) { $events = @(Get-WfxEventData -Hours $Hours -EvtxPath $EvtxPath) }

    $files = @(); $ransom = [pscustomobject]@{ Note = @(); RecentFile = @() }
    if ($want.Files -and $FileScan) {
        $files = @(Get-WfxFileData)
        $ransom = Get-WfxRansomwareData
    }

    $exposure = @()
    if ($want.Exposure) { $exposure = @(Get-WfxExposureData -IncludeFileScan:$ExposureScan) }

    $security = if ($want.Security) { Get-WfxSecurityData } else { $null }

    [pscustomobject]@{
        Schema      = 'winforensicx.bundle/1'
        ToolVersion = $script:WfxVersion
        Collected   = (Get-Date).ToUniversalTime().ToString('o')
        HostName    = if ($hostInfo) { $hostInfo.HostName } else { [Environment]::MachineName }
        Host        = $hostInfo
        Process     = $procs
        Network     = $net
        Dns         = $dns
        Persistence = $persist
        Events      = $events
        Files       = $files
        Ransom      = $ransom
        Exposure    = $exposure
        Security    = $security
        Gaps        = @(Get-WfxGap)
        Meta        = [pscustomobject]@{ Hours = $Hours; EvtxPath = $EvtxPath; FileScan = [bool]$FileScan; ExposureScan = [bool]$ExposureScan; Sections = @($Sections) }
    }
}


# ===== Collectors/Events.ps1 =====
# Event collector — normalizes Windows events from live logs or from .evtx files (offline/image).
# Both paths produce { Log, Id, TimeCreated, Computer, Message, Fields = @{ ... } }.

$script:WfxEventQuery = @(
    @{ Log = 'Security'; Ids = @(4624, 4625, 4648, 4672, 4720, 4728, 4732, 4756, 4697, 4698, 1102) }
    @{ Log = 'System'; Ids = @(7045, 104, 7030, 7040) }
    @{ Log = 'Microsoft-Windows-PowerShell/Operational'; Ids = @(4104, 4103) }
    @{ Log = 'Microsoft-Windows-TaskScheduler/Operational'; Ids = @(106, 140, 141) }
    @{ Log = 'Microsoft-Windows-Windows Defender/Operational'; Ids = @(1116, 1117, 5001, 5007) }
    @{ Log = 'Microsoft-Windows-Sysmon/Operational'; Ids = @(1, 3, 7, 8, 11, 13, 22, 23) }
)

function Get-WfxEventData {
    <#
    .SYNOPSIS Collects security-relevant events.
    .PARAMETER EvtxPath  Folder or single .evtx file to analyze offline (an exported log or forensic image).
    .PARAMETER Hours     Live mode: look back this many hours (default 72).
    .PARAMETER MaxPerLog Cap events per log to bound memory on busy servers.
    #>
    param([string]$EvtxPath, [int]$Hours = 72, [int]$MaxPerLog = 20000)
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]

    if ($EvtxPath) {
        $files = if (Test-Path -LiteralPath $EvtxPath -PathType Container) { Get-ChildItem -LiteralPath $EvtxPath -Filter *.evtx -Recurse -ErrorAction SilentlyContinue } else { @(Get-Item -LiteralPath $EvtxPath -ErrorAction SilentlyContinue) }
        foreach ($f in @($files | Where-Object { $_ })) {
            $ids = ($script:WfxEventQuery | ForEach-Object { $_.Ids }) | Sort-Object -Unique
            Invoke-WfxStep "events:evtx:$($f.Name)" {
                Get-WinEvent -FilterHashtable @{ Path = $f.FullName; Id = $ids } -ErrorAction Stop |
                    Select-Object -First $MaxPerLog | ForEach-Object { $out.Add((ConvertTo-WfxEvent $_ $f.BaseName)) }
            }
        }
        return , @($out.ToArray())
    }

    $start = (Get-Date).AddHours(-[Math]::Abs($Hours))
    foreach ($q in $script:WfxEventQuery) {
        Invoke-WfxStep "events:$($q.Log)" {
            $ev = Get-WinEvent -FilterHashtable @{ LogName = $q.Log; Id = $q.Ids; StartTime = $start } -MaxEvents $MaxPerLog -ErrorAction Stop
            foreach ($e in $ev) { $out.Add((ConvertTo-WfxEvent $e $q.Log)) }
        } | Out-Null
        # A missing/disabled log is a visibility gap worth recording, not a hard error.
    }
    , @($out.ToArray())
}

function ConvertTo-WfxEvent {
    param($Event, [string]$Log)
    $fields = @{}
    try {
        $xml = [xml]$Event.ToXml()
        foreach ($d in $xml.Event.EventData.Data) {
            if ($d.Name) { $fields[$d.Name] = [string]$d.'#text' }
        }
    } catch {}
    # Friendly aliases the analyzer uses regardless of schema.
    if (-not $fields.ContainsKey('CommandLine') -and $fields.ContainsKey('ProcessCommandLine')) { $fields['CommandLine'] = $fields['ProcessCommandLine'] }
    if (-not $fields.ContainsKey('ScriptBlockText') -and $Event.Id -eq 4104) { try { $fields['ScriptBlockText'] = $Event.Properties[2].Value } catch {} }
    $msg = ''
    try { $msg = $Event.Message } catch { $msg = '' }
    # Redact secrets in the message and every field value at collection time (4688 command lines and 4104
    # script blocks in particular can carry passwords/keys). Structure and tool names are preserved.
    $msg = Protect-WfxText $msg
    foreach ($fk in @($fields.Keys)) { $fields[$fk] = Protect-WfxText ([string]$fields[$fk]) }
    [pscustomobject]@{
        Log         = $Log
        Id          = [int]$Event.Id
        TimeCreated = $Event.TimeCreated
        Computer    = $Event.MachineName
        Message     = $msg
        Fields      = $fields
    }
}


# ===== Collectors/Exposure.ps1 =====
# ─────────────────────────────────────────────────────────────────────────────────────────────
# Secrets-exposure & security-hygiene COLLECTOR.  DEFENSIVE / READ-ONLY by design.
#
# What this does:  detects and reports THAT sensitive material or a misconfiguration EXISTS and is
#   exposed (GPP cPassword, unattend passwords, accessible SAM/SYSTEM/SECURITY/NTDS, world-readable
#   cloud-credential files, auto-logon password, unencrypted SSH keys, AI/API keys, secrets in env
#   vars / PowerShell history / config files) so an analyst can remediate it.
#
# What this deliberately does NOT do — and must never be extended to do:
#   • It never opens, copies, parses or decrypts a credential store (SAM/NTDS, LSA secrets, DPAPI
#     blobs, browser login DBs, LSASS). For hives it checks existence and ACLs only.
#   • It never emits a secret VALUE. Every match is reduced to type + length via Find-WfxSecret /
#     Format-WfxSecret BEFORE it leaves this collector. Records returned here carry only redacted
#     strings in a .Redacted field — raw values are discarded immediately and never persisted.
#   • It never decrypts the GPP cPassword (reversible though it is): reporting its presence is enough.
#
# The exposure analyzer consumes: { Kind, Path, Detail, Accessible, WorldReadable, Redacted }.
# ─────────────────────────────────────────────────────────────────────────────────────────────

# Identities that should not normally be able to read a per-user or protected file.
$script:WfxOtherReadSids = @(
    'S-1-1-0'        # Everyone
    'S-1-5-11'       # Authenticated Users
    'S-1-5-32-545'   # BUILTIN\Users
    'S-1-5-4'        # INTERACTIVE
    'S-1-5-7'        # ANONYMOUS
)
# Secret types that are specifically AI-provider keys (routed to the AiKey finding).
$script:WfxAiKeyTypes = @('Anthropic API key', 'OpenAI API key', 'OpenRouter API key', 'Google API key',
    'Hugging Face token', 'Groq API key', 'xAI API key', 'Replicate token')

function Test-WfxOtherUserReadable {
    <# True if a non-admin, non-owner principal (Everyone / Users / Authenticated Users / INTERACTIVE)
       is granted read access. ACL-only; the file's contents are never opened. #>
    param([string]$Path)
    if (-not (Test-WfxWindows) -or -not (Test-Path -LiteralPath $Path)) { return $false }
    try {
        $acl = Get-Acl -LiteralPath $Path -ErrorAction Stop
        foreach ($ace in $acl.Access) {
            if ($ace.AccessControlType -ne 'Allow') { continue }
            if ($ace.FileSystemRights -notmatch 'Read|FullControl|Modify') { continue }
            $sid = ''
            try { $sid = ($ace.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier])).Value } catch { $sid = [string]$ace.IdentityReference }
            if ($sid -in $script:WfxOtherReadSids) { return $true }
        }
    } catch {}
    return $false
}

function Get-WfxRedactedHits {
    <# Returns redacted secret descriptors for a block of text WITHOUT returning any raw value.
       Combines Find-WfxSecret (known key formats) with a generic key=value / assignment detector. #>
    param([AllowEmptyString()][string]$Text, [int]$MaxHits = 20)
    $hits = New-Object System.Collections.Generic.List[object]
    if ([string]::IsNullOrEmpty($Text)) { return , $hits.ToArray() }
    foreach ($s in (Find-WfxSecret $Text)) {
        if ($hits.Count -ge $MaxHits) { break }
        $hits.Add([pscustomobject]@{ Type = $s.Type; Line = $s.Line; Redacted = "$($s.Type) (line $($s.Line)): $($s.Redacted)" })
    }
    # Generic assignments (db_password=..., ANTHROPIC_API_KEY=..., clientSecret: ...) not caught by a
    # known key format. The name may carry an underscore/dot prefix, so we match the whole identifier.
    $lines = $Text -split "`r?`n"
    $assignRx = '(?i)([A-Za-z0-9_.\-]*(?:password|passwd|pwd|secret|api[_-]?key|apikey|token|credential|connectionstring|access[_-]?key)[A-Za-z0-9_.\-]*)\s*[:=]\s*("[^"]{4,}"|''[^'']{4,}''|\S{4,})'
    $seen = @{}
    foreach ($h in $hits) { $seen["$($h.Line)"] = $true }
    for ($i = 0; $i -lt $lines.Count -and $hits.Count -lt $MaxHits; $i++) {
        $m = [regex]::Match($lines[$i], $assignRx)
        if (-not $m.Success) { continue }
        if ($seen.ContainsKey([string]($i + 1))) { continue }   # a known-format key already covered this line
        $raw = $m.Groups[2].Value.Trim('"', "'")
        # Skip obvious placeholders.
        if ($raw -match '(?i)^(?:\*+|x+|changeme|your[_-]?\w+|<[^>]+>|%[^%]+%|\$\{?\w+\}?|null|none|empty|example|xxx+)$') { continue }
        $name = $m.Groups[1].Value
        $hits.Add([pscustomobject]@{ Type = "$name assignment"; Line = $i + 1; Redacted = "$name (line $($i+1)): $(Format-WfxSecret $raw)" })
    }
    # Command-line secrets passed as separate args or concatenated flags (mysql -pSecret, aws ... set
    # aws_secret_access_key <value>) — common in shell history. Guarded to avoid placeholder noise.
    for ($i = 0; $i -lt $lines.Count -and $hits.Count -lt $MaxHits; $i++) {
        if ($seen.ContainsKey([string]($i + 1))) { continue }
        $mp = [regex]::Match($lines[$i], '(?i)(?:^|\s)-p(?!assword\b)([^\s]{4,})')
        if ($mp.Success) { $hits.Add([pscustomobject]@{ Type = 'password flag'; Line = $i + 1; Redacted = "password flag (line $($i+1)): $(Format-WfxSecret $mp.Groups[1].Value)" }); continue }
        $ma = [regex]::Match($lines[$i], '(?i)\b([A-Za-z0-9_.\-]{0,40}(?:password|passwd|pwd|secret|api[_-]?key|access[_-]?key|token)[A-Za-z0-9_.\-]{0,20})\s+(\S{8,})\s*$')
        if ($ma.Success -and $ma.Groups[2].Value -notmatch '(?i)^(?:changeme|example|<[^>]+>|%[^%]+%)$') {
            $hits.Add([pscustomobject]@{ Type = "$($ma.Groups[1].Value) value"; Line = $i + 1; Redacted = "$($ma.Groups[1].Value) (line $($i+1)): $(Format-WfxSecret $ma.Groups[2].Value)" })
        }
    }
    , $hits.ToArray()
}

function Get-WfxExposureData {
    <#
    .SYNOPSIS Defensive secrets-exposure audit. Returns redacted exposure records (see file header).
    .PARAMETER IncludeFileScan  Also scan a small set of likely-credential config files in user profiles.
    #>
    param([switch]$IncludeFileScan)
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]
    $add = { param($Kind, $Path, $Detail = '', $Accessible = $false, $WorldReadable = $false, $Redacted = @())
        $out.Add([pscustomobject]@{ Kind = $Kind; Path = $Path; Detail = $Detail; Accessible = [bool]$Accessible; WorldReadable = [bool]$WorldReadable; Content = ''; Redacted = @($Redacted) }) }

    # ── 1. GPP cPassword (presence only; never decrypted) ──
    Invoke-WfxStep 'expo:gpp' {
        $gppRoots = @("$env:SystemRoot\SYSVOL", 'C:\ProgramData\Microsoft\Group Policy\History')
        try { $dom = (Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue).Domain; if ($dom -and $dom -ne 'WORKGROUP') { $gppRoots += "\\$dom\SYSVOL" } } catch {}
        foreach ($root in $gppRoots) {
            if (-not (Test-Path -LiteralPath $root)) { continue }
            Get-ChildItem -LiteralPath $root -Recurse -File -Include 'Groups.xml', 'Services.xml', 'ScheduledTasks.xml', 'DataSources.xml', 'Printers.xml', 'Drives.xml' -ErrorAction SilentlyContinue |
                Select-Object -First 100 | ForEach-Object {
                    $hit = $false
                    try { $hit = (Select-String -LiteralPath $_.FullName -Pattern 'cpassword\s*=\s*"[^"]+"' -SimpleMatch:$false -Quiet -ErrorAction Stop) } catch {}
                    if ($hit) { & $add 'GppCpassword' $_.FullName 'GPP XML with cpassword attribute' }
                }
        }
    } | Out-Null

    # ── 2. Unattend / sysprep passwords (presence only) ──
    Invoke-WfxStep 'expo:unattend' {
        $cand = @(
            "$env:SystemDrive\unattend.xml", "$env:SystemDrive\autounattend.xml"
            "$env:SystemRoot\Panther\unattend.xml", "$env:SystemRoot\Panther\Unattend\unattend.xml"
            "$env:SystemRoot\System32\Sysprep\unattend.xml", "$env:SystemRoot\System32\Sysprep\Panther\unattend.xml"
            "$env:SystemRoot\System32\Sysprep\sysprep.xml", "$env:SystemRoot\System32\sysprep.inf"
        )
        foreach ($f in $cand) {
            if (-not (Test-Path -LiteralPath $f)) { continue }
            $hasPw = $false
            try { $hasPw = (Select-String -LiteralPath $f -Pattern '<Password>|<AdministratorPassword>|<DomainPassword>|\bpassword\b' -Quiet -ErrorAction Stop) } catch {}
            if ($hasPw) { & $add 'UnattendPassword' $f 'Unattended-setup file containing a password element' }
        }
    } | Out-Null

    # ── 3. Sensitive hives — existence + ACL only, contents NEVER read ──
    Invoke-WfxStep 'expo:hives' {
        $hiveFiles = @(
            @{ P = "$env:SystemRoot\System32\config\RegBack\SAM"; D = 'SAM hive backup (RegBack)' }
            @{ P = "$env:SystemRoot\System32\config\RegBack\SYSTEM"; D = 'SYSTEM hive backup (RegBack)' }
            @{ P = "$env:SystemRoot\System32\config\RegBack\SECURITY"; D = 'SECURITY hive backup (RegBack)' }
            @{ P = "$env:SystemRoot\repair\SAM"; D = 'SAM hive copy (repair)' }
            @{ P = "$env:SystemRoot\repair\SYSTEM"; D = 'SYSTEM hive copy (repair)' }
            @{ P = "$env:SystemRoot\repair\SECURITY"; D = 'SECURITY hive copy (repair)' }
            @{ P = "$env:SystemDrive\Windows.old\Windows\System32\config\SAM"; D = 'SAM hive in Windows.old' }
            @{ P = "$env:SystemDrive\NTDS\ntds.dit"; D = 'Active Directory database (NTDS.dit)' }
        )
        foreach ($h in $hiveFiles) {
            if (-not (Test-Path -LiteralPath $h.P)) { continue }
            $f = Get-Item -LiteralPath $h.P -ErrorAction SilentlyContinue
            if (-not $f -or $f.Length -eq 0) { continue }   # RegBack is often present but zero-length
            $readable = Test-WfxOtherUserReadable $h.P
            & $add 'SensitiveHive' $h.P $h.D $readable $readable
        }
    } | Out-Null

    # ── 4. Shadow copies (informational) ──
    Invoke-WfxStep 'expo:shadow' {
        $sc = @(Get-CimInstance Win32_ShadowCopy -ErrorAction Stop)
        if ($sc.Count -gt 0) { & $add 'ShadowCopy' '' "$($sc.Count) volume shadow copy(ies) present" }
    } | Out-Null

    # ── 5. World/other-readable cloud & credential files ──
    Invoke-WfxStep 'expo:credfiles' {
        $rel = @(
            @{ R = '.aws\credentials'; D = 'AWS CLI credentials' }
            @{ R = '.azure\accessTokens.json'; D = 'Azure CLI access tokens' }
            @{ R = '.azure\msal_token_cache.json'; D = 'Azure MSAL token cache' }
            @{ R = '.config\gcloud\credentials.db'; D = 'gcloud credentials' }
            @{ R = '.config\gcloud\access_tokens.db'; D = 'gcloud access tokens' }
            @{ R = '.docker\config.json'; D = 'Docker registry auth' }
            @{ R = '.kube\config'; D = 'Kubernetes config (cluster tokens)' }
            @{ R = '.git-credentials'; D = 'Git stored credentials' }
            @{ R = '_netrc'; D = 'netrc credentials' }
            @{ R = '.netrc'; D = 'netrc credentials' }
            @{ R = '.npmrc'; D = 'npm auth token' }
            @{ R = '.pypirc'; D = 'PyPI upload credentials' }
        )
        Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $userHome = $_.FullName
            foreach ($c in $rel) {
                $p = Join-Path $userHome $c.R
                if (-not (Test-Path -LiteralPath $p)) { continue }
                if (Test-WfxOtherUserReadable $p) { & $add 'CredFileWorldReadable' $p $c.D $true $true }
            }
        }
    } | Out-Null

    # ── 6. Auto-logon password in Winlogon (presence only; value never read) ──
    Invoke-WfxStep 'expo:autologon' {
        $wl = 'HKLM:\Software\Microsoft\Windows NT\CurrentVersion\Winlogon'
        if (Test-Path $wl) {
            $k = Get-ItemProperty $wl -ErrorAction SilentlyContinue
            if ("$($k.AutoAdminLogon)" -eq '1' -and $k.PSObject.Properties['DefaultPassword'] -and $k.DefaultPassword) {
                & $add 'AutoLogon' $wl ("DefaultUserName=" + $k.DefaultUserName)
            }
        }
    } | Out-Null

    # ── 7. Unencrypted SSH private keys (header inspected for cipher only; key bytes never emitted) ──
    Invoke-WfxStep 'expo:sshkeys' {
        Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $sshDir = Join-Path $_.FullName '.ssh'
            if (-not (Test-Path -LiteralPath $sshDir)) { return }
            Get-ChildItem -LiteralPath $sshDir -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -match '^(id_(rsa|dsa|ecdsa|ed25519)|.*\.(pem|key|ppk))$' -and $_.Name -notmatch '\.pub$' } |
                ForEach-Object {
                    $head = ''
                    try { $head = (Get-Content -LiteralPath $_.FullName -TotalCount 5 -ErrorAction Stop) -join "`n" } catch { return }
                    if ($head -notmatch 'PRIVATE KEY|PuTTY-User-Key') { return }
                    $encrypted = $false
                    if ($head -match 'Proc-Type:\s*4,ENCRYPTED' -or $head -match 'DEK-Info:' -or $head -match 'Encryption:\s*aes') { $encrypted = $true }
                    elseif ($head -match 'BEGIN OPENSSH PRIVATE KEY') {
                        # OpenSSH keys embed the cipher name; 'none' = unencrypted. Inspect header block only.
                        try {
                            $b64 = ((Get-Content -LiteralPath $_.FullName -ErrorAction Stop) | Where-Object { $_ -notmatch 'PRIVATE KEY-----' } | Select-Object -First 2) -join ''
                            $bytes = [Convert]::FromBase64String($b64.PadRight([int](([Math]::Ceiling($b64.Length / 4.0)) * 4), '='))
                            $asText = [Text.Encoding]::ASCII.GetString($bytes)
                            if ($asText -notmatch 'none' -and ($asText -match 'aes|chacha|3des')) { $encrypted = $true }
                        } catch { $encrypted = $true }  # if unsure, assume protected (avoid false alarm)
                    }
                    elseif ($_.Extension -eq '.ppk') { $encrypted = $true }  # conservative
                    if (-not $encrypted) { & $add 'SshKeyUnprotected' $_.FullName 'SSH private key without a passphrase' }
                }
        }
    } | Out-Null

    # ── 8. Secrets in environment variables (redacted immediately) ──
    Invoke-WfxStep 'expo:env' {
        $nameRx = '(?i)(key|token|secret|password|passwd|pwd|credential|conn(ection)?string|sas|dsn)'
        foreach ($scope in @('Process', 'User', 'Machine')) {
            $vars = @{}
            try { $vars = [Environment]::GetEnvironmentVariables([EnvironmentVariableTarget]::$scope) } catch { continue }
            foreach ($name in $vars.Keys) {
                $val = [string]$vars[$name]
                if ([string]::IsNullOrWhiteSpace($val) -or $val.Length -lt 8) { continue }
                $known = Find-WfxSecret $val
                if ($known.Count -gt 0) {
                    $type = $known[0].Type
                    $red = "$type`: $($known[0].Redacted)"
                    if ($type -in $script:WfxAiKeyTypes) { & $add 'AiKey' "env:$scope`:$name" "$type in `$env:$name" $false $false @($red) }
                    else { & $add 'SecretInEnv' "env:$scope" $name $false $false @("$name ($scope): $($known[0].Redacted)") }
                } elseif ($name -match $nameRx -and $val -notmatch '(?i)^(?:\*+|changeme|your[_-]?\w+|%[^%]+%|<[^>]+>|true|false|\d{1,4})$') {
                    & $add 'SecretInEnv' "env:$scope" $name $false $false @("$name ($scope): $(Format-WfxSecret $val)")
                }
            }
        }
    } | Out-Null

    # ── 9. Secrets in PowerShell / shell history (redacted immediately) ──
    Invoke-WfxStep 'expo:history' {
        $histFiles = New-Object System.Collections.Generic.List[string]
        Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $histFiles.Add((Join-Path $_.FullName 'AppData\Roaming\Microsoft\Windows\PowerShell\PSReadLine\ConsoleHost_history.txt'))
            $histFiles.Add((Join-Path $_.FullName '.bash_history'))
        }
        foreach ($hf in $histFiles) {
            if (-not (Test-Path -LiteralPath $hf)) { continue }
            $text = ''
            try { $text = Get-Content -LiteralPath $hf -Raw -ErrorAction Stop } catch { continue }
            $hits = Get-WfxRedactedHits $text
            if ($hits.Count -gt 0) { & $add 'SecretInHistory' $hf 'credential(s) typed on the command line' $false $false @($hits.Redacted) }
        }
    } | Out-Null

    # ── 10. Optional: secrets in common config files (bounded; redacted immediately) ──
    if ($IncludeFileScan) {
        Invoke-WfxStep 'expo:configfiles' {
            $names = @('.env', '.env.local', 'web.config', 'appsettings.json', 'appsettings.Development.json', 'secrets.json', 'config.json', 'settings.py', 'application.properties', 'credentials.json', '.env.production')
            $scanned = 0
            Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                if ($scanned -ge 400) { return }
                Get-ChildItem -LiteralPath $_.FullName -Recurse -File -Depth 4 -Include $names -ErrorAction SilentlyContinue |
                    Where-Object { $_.Length -le 262144 } | Select-Object -First 100 | ForEach-Object {
                        if ($scanned -ge 400) { return }
                        $scanned++
                        $text = ''
                        try { $text = Get-Content -LiteralPath $_.FullName -Raw -ErrorAction Stop } catch { return }
                        $hits = Get-WfxRedactedHits $text
                        if ($hits.Count -gt 0) {
                            $ai = @($hits | Where-Object { $_.Type -in $script:WfxAiKeyTypes })
                            if ($ai.Count -gt 0) { & $add 'AiKey' $_.FullName ($ai[0].Type) $false $false @($ai.Redacted) }
                            $other = @($hits | Where-Object { $_.Type -notin $script:WfxAiKeyTypes })
                            if ($other.Count -gt 0) { & $add 'SecretInFile' $_.FullName (($other[0].Type)) $false $false @($other.Redacted) }
                        }
                    }
            }
        } | Out-Null
    }

    , @($out.ToArray())
}


# ===== Collectors/Files.ps1 =====
# File collector — scans a bounded set of high-signal locations (web roots, user drop folders) and
# produces the normalized file records the File/Ransomware analyzers consume:
#   { Path, Directory, Extension, Length, LastWrite, Content, Entropy, SignatureStatus, Zone, InWebRoot, SHA256 }
# Everything is bounded (file count, file size, read size) so a triage never walks an entire disk.
# Content is read only for small text files in web roots / script locations and is never emitted raw by the
# analyzer; here it is used for web-shell signature matching only.

$script:WfxWebRoots = @(
    'C:\inetpub\wwwroot'
    'C:\inetpub\ftproot'
    "$env:SystemDrive\xampp\htdocs"
    "$env:SystemDrive\wamp\www"
    "$env:SystemDrive\wamp64\www"
    "$env:SystemDrive\Apache24\htdocs"
    "$env:SystemDrive\nginx\html"
    "$env:ProgramFiles\Apache Software Foundation"
    "$env:SystemDrive\laragon\www"
)
$script:WfxWebScriptExt = @('.php', '.php3', '.php4', '.php5', '.php7', '.phtml', '.asp', '.aspx', '.ashx', '.asmx', '.jsp', '.jspx', '.cfm', '.cgi', '.pl')

function Get-WfxZoneId {
    <# Reads the Mark-of-the-Web ZoneId from a file's Zone.Identifier alternate data stream. '' when none. #>
    param([string]$Path)
    if (-not (Test-WfxWindows)) { return '' }
    try {
        $z = Get-Content -LiteralPath $Path -Stream 'Zone.Identifier' -ErrorAction Stop
        $m = [regex]::Match(($z -join "`n"), '(?im)^ZoneId\s*=\s*(\d)')
        if ($m.Success) { return $m.Groups[1].Value }
    } catch {}
    return ''
}

function Get-WfxFileBytesEntropy {
    <# Shannon entropy over the first $Max bytes of a file (bounded read). 0 on failure. #>
    param([string]$Path, [int]$Max = 262144)
    try {
        $fs = [System.IO.File]::OpenRead($Path)
        try {
            $len = [Math]::Min([int]$Max, [int]$fs.Length)
            if ($len -le 0) { return 0.0 }
            $buf = New-Object byte[] $len
            [void]$fs.Read($buf, 0, $len)
            return (Get-WfxEntropy $buf)
        } finally { $fs.Dispose() }
    } catch { return 0.0 }
}

function Get-WfxFileHash256 {
    param([string]$Path)
    try { return (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash } catch { return '' }
}

function Get-WfxFileData {
    <#
    .SYNOPSIS Collects file records from web roots and user drop folders for the File analyzer.
    .PARAMETER ExtraPath   Additional folders to scan (e.g. a mounted image or a custom web root).
    .PARAMETER MaxFiles    Hard cap on files examined (default 4000) so a triage stays fast.
    .PARAMETER MaxReadKB   Max bytes read for content/entropy of a single file.
    .PARAMETER Hours       Only files modified within this window are considered "recent drops" (default 168 = 7d).
    #>
    param([string[]]$ExtraPath = @(), [int]$MaxFiles = 4000, [int]$MaxReadKB = 256, [int]$Hours = 168)
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $budget = [ref]$MaxFiles
    $cutoff = (Get-Date).AddHours(-[Math]::Abs($Hours))

    $emit = {
        param($Item, [bool]$InWeb, [bool]$ReadContent)
        if ($budget.Value -le 0) { return }
        $p = $Item.FullName
        if ($seen.ContainsKey($p)) { return }
        $seen[$p] = $true
        $budget.Value--
        $ext = $Item.Extension.ToLowerInvariant()
        $content = ''
        $entropy = 0.0
        $isExe = $ext -in @('.exe', '.dll', '.scr', '.com', '.sys', '.ocx', '.cpl', '.pif')
        if ($ReadContent -and $Item.Length -le ($MaxReadKB * 1024)) {
            try { $content = Get-Content -LiteralPath $p -Raw -ErrorAction Stop } catch { $content = '' }
            # Scrub secrets (e.g. connection strings in a web.config) before the content enters the bundle.
            # Web-shell code constructs (eval/system/base64) are not secret patterns, so detection is unaffected.
            if ($content) { $content = Protect-WfxText $content }
        }
        if ($isExe) { $entropy = Get-WfxFileBytesEntropy $p (($MaxReadKB * 1024)) }
        $zone = Get-WfxZoneId $p
        $sha = ''
        # Hash only the small set of files most likely to matter (executables / MOTW / web scripts).
        if ($isExe -or $zone -match '3|4' -or $InWeb) { $sha = Get-WfxFileHash256 $p }
        $out.Add([pscustomobject]@{
                Path            = $p
                Directory       = $Item.DirectoryName
                Extension       = $ext
                Length          = $Item.Length
                LastWrite       = $Item.LastWriteTime
                Content         = $content
                Entropy         = $entropy
                SignatureStatus = if ($isExe) { Get-WfxSignature $p } else { '' }
                Zone            = $zone
                InWebRoot       = $InWeb
                SHA256          = $sha
            })
    }

    # ── Web roots: scan served scripts for web shells ──
    Invoke-WfxStep 'files:webroots' {
        foreach ($root in (@($script:WfxWebRoots) + @($ExtraPath))) {
            if ($budget.Value -le 0) { break }
            if (-not $root -or -not (Test-Path -LiteralPath $root)) { continue }
            Get-ChildItem -LiteralPath $root -Recurse -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Extension.ToLowerInvariant() -in $script:WfxWebScriptExt } |
                Select-Object -First ($budget.Value) |
                ForEach-Object { & $emit $_ $true $true }
        }
    } | Out-Null

    # ── User drop folders: recently written executables/scripts (download/exec staging) ──
    Invoke-WfxStep 'files:userdrops' {
        $dirs = New-Object System.Collections.Generic.List[string]
        $dirs.Add("$env:ProgramData\Microsoft\Windows\Start Menu\Programs\StartUp")
        $dirs.Add("$env:PUBLIC\Downloads")
        $dirs.Add($env:TEMP)
        $dirs.Add("$env:SystemRoot\Temp")
        Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            foreach ($sub in @('Downloads', 'Desktop', 'Documents', 'AppData\Local\Temp', 'AppData\Roaming')) {
                $dirs.Add((Join-Path $_.FullName $sub))
            }
        }
        $dropExt = @('.exe', '.dll', '.scr', '.com', '.pif', '.cpl', '.ps1', '.bat', '.cmd', '.vbs', '.vbe', '.js', '.jse', '.wsf', '.hta', '.jar', '.lnk', '.iso', '.img', '.vhd')
        foreach ($d in ($dirs | Sort-Object -Unique)) {
            if ($budget.Value -le 0) { break }
            if (-not (Test-Path -LiteralPath $d)) { continue }
            # One level deep for Roaming (app folders), recurse shallow elsewhere.
            $recurse = $d -notmatch '(?i)\\AppData\\Roaming$'
            Get-ChildItem -LiteralPath $d -File -Recurse:$recurse -Depth 2 -ErrorAction SilentlyContinue |
                Where-Object { $_.Extension.ToLowerInvariant() -in $dropExt -and ($_.LastWriteTime -ge $cutoff -or $_.Extension -in @('.exe', '.scr', '.hta')) } |
                Select-Object -First ($budget.Value) |
                ForEach-Object { & $emit $_ $false $false }
        }
    } | Out-Null

    , @($out.ToArray())
}

function Get-WfxRansomwareData {
    <#
    .SYNOPSIS Collects ransom-note candidates and recently written encrypted-looking files.
    Returns a pscustomobject with .Note (Path, Content) and .RecentFile (Path, Extension, Entropy, LastWrite).
    .PARAMETER Hours  Window for "recent" encrypted files (default 48).
    #>
    param([int]$Hours = 48, [int]$MaxNotes = 200, [int]$MaxRecent = 4000)
    $notes = New-Object System.Collections.Generic.List[object]
    $recent = New-Object System.Collections.Generic.List[object]
    if (-not (Test-WfxWindows)) { return [pscustomobject]@{ Note = @(); RecentFile = @() } }
    $cutoff = (Get-Date).AddHours(-[Math]::Abs($Hours))
    $noteNameRx = '(?i)(?:read[\s_\-]?me|how[\s_\-]?to[\s_\-]?(?:decrypt|recover)|decrypt[\s_\-]?(?:instruction|info|files)?|recover[\s_\-]?(?:files|instruction)|restore[\s_\-]?files|your[\s_\-]?files|unlock|ransom|_readme|help_decrypt)'
    $roots = @("$env:PUBLIC", "$env:SystemDrive\Users")

    Invoke-WfxStep 'files:ransomnotes' {
        foreach ($r in $roots) {
            if (-not (Test-Path -LiteralPath $r)) { continue }
            Get-ChildItem -LiteralPath $r -Recurse -File -Depth 4 -Include '*.txt', '*.html', '*.htm', '*.hta' -ErrorAction SilentlyContinue |
                Where-Object { $_.Length -le 65536 -and ($_.BaseName -match $noteNameRx -or $_.LastWriteTime -ge $cutoff) } |
                Select-Object -First $MaxNotes |
                ForEach-Object {
                    $c = ''
                    try { $c = Get-Content -LiteralPath $_.FullName -Raw -ErrorAction Stop } catch {}
                    if ($c) { $notes.Add([pscustomobject]@{ Path = $_.FullName; Content = $c }) }
                }
        }
    } | Out-Null

    Invoke-WfxStep 'files:recentencrypted' {
        $count = 0
        foreach ($r in $roots) {
            if ($count -ge $MaxRecent) { break }
            if (-not (Test-Path -LiteralPath $r)) { continue }
            Get-ChildItem -LiteralPath $r -Recurse -File -Depth 5 -ErrorAction SilentlyContinue |
                Where-Object { $_.LastWriteTime -ge $cutoff -and $_.Length -ge 1024 -and $_.Length -le 52428800 } |
                ForEach-Object {
                    if ($count -ge $MaxRecent) { return }
                    $count++
                    $e = Get-WfxFileBytesEntropy $_.FullName 65536
                    if ($e -ge 7.3) {
                        $recent.Add([pscustomobject]@{ Path = $_.FullName; Extension = $_.Extension; Entropy = $e; LastWrite = $_.LastWriteTime })
                    }
                }
        }
    } | Out-Null

    [pscustomobject]@{ Note = @($notes.ToArray()); RecentFile = @($recent.ToArray()) }
}


# ===== Collectors/Persistence.ps1 =====
# Persistence collector — enumerates autostart locations into normalized records.
# Covers Run keys, Startup folders, scheduled tasks, WMI subscriptions, Winlogon, AppInit,
# Image File Execution Options, LSA packages, and BootExecute. Services/drivers come from System.ps1.

function Get-WfxPersistenceData {
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]

    $add = {
        param($Kind, $Name, $Command, $Location, $User = '')
        $path = Get-WfxImagePath $Command
        # Store a secret-scrubbed command (a task action or WMI script text can embed credentials); the
        # image path above is taken from the raw value first so analysis is unaffected.
        $out.Add([pscustomobject]@{ Kind = $Kind; Name = $Name; Command = (Protect-WfxText ([string]$Command)); Path = $path; Location = $Location
                User = $User; Enabled = $true; SignatureStatus = (Get-WfxSignature $path) })
    }

    # ── Run / RunOnce keys (HKLM + all user hives) ──
    Invoke-WfxStep 'persist:runkeys' {
        $runPaths = @(
            'HKLM:\Software\Microsoft\Windows\CurrentVersion\Run'
            'HKLM:\Software\Microsoft\Windows\CurrentVersion\RunOnce'
            'HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Run'
            'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\Explorer\Run'
        )
        foreach ($u in (Get-WfxUserHives)) {
            $runPaths += "$u\Software\Microsoft\Windows\CurrentVersion\Run"
            $runPaths += "$u\Software\Microsoft\Windows\CurrentVersion\RunOnce"
        }
        foreach ($rp in $runPaths) {
            if (-not (Test-Path $rp)) { continue }
            $k = Get-Item $rp -ErrorAction SilentlyContinue
            foreach ($v in $k.GetValueNames()) {
                & $add 'RunKey' $v ($k.GetValue($v)) $rp
            }
        }
    }

    # ── Startup folders ──
    Invoke-WfxStep 'persist:startup' {
        $folders = @("$env:ProgramData\Microsoft\Windows\Start Menu\Programs\StartUp")
        Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $folders += "$($_.FullName)\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup"
        }
        foreach ($f in $folders) {
            if (-not (Test-Path $f)) { continue }
            Get-ChildItem $f -File -ErrorAction SilentlyContinue | ForEach-Object { & $add 'Startup' $_.Name $_.FullName $f }
        }
    }

    # ── Scheduled tasks ──
    Invoke-WfxStep 'persist:tasks' {
        Get-ScheduledTask -ErrorAction Stop | ForEach-Object {
            $t = $_
            foreach ($a in @($t.Actions)) {
                $cmd = ''
                if ($a.Execute) { $cmd = $a.Execute; if ($a.Arguments) { $cmd += ' ' + $a.Arguments } }
                if (-not $cmd) { continue }
                & $add 'ScheduledTask' ($t.TaskPath + $t.TaskName) $cmd ('Task:' + $t.State) ($t.Principal.UserId)
            }
        }
    }

    # ── WMI event subscriptions (classic persistence) ──
    Invoke-WfxStep 'persist:wmi' {
        $consumers = Get-CimInstance -Namespace root\subscription -ClassName __EventConsumer -ErrorAction SilentlyContinue
        foreach ($c in $consumers) {
            $cmd = ''
            if ($c.CommandLineTemplate) { $cmd = $c.CommandLineTemplate }
            elseif ($c.ScriptText) { $cmd = $c.ScriptText }
            elseif ($c.ScriptFileName) { $cmd = $c.ScriptFileName }
            if ($cmd) { & $add 'WmiSubscription' ($c.Name) $cmd 'root\subscription' }
        }
    }

    # ── Winlogon (Shell / Userinit / Notify) ──
    Invoke-WfxStep 'persist:winlogon' {
        $wl = 'HKLM:\Software\Microsoft\Windows NT\CurrentVersion\Winlogon'
        if (Test-Path $wl) {
            $k = Get-Item $wl
            foreach ($v in @('Shell', 'Userinit', 'Taskman', 'VmApplet')) {
                $val = $k.GetValue($v)
                if ($val -and $val -notin @('explorer.exe', 'C:\Windows\system32\userinit.exe,')) { & $add 'Winlogon' $v $val $wl }
            }
        }
    }

    # ── AppInit_DLLs ──
    Invoke-WfxStep 'persist:appinit' {
        foreach ($p in @('HKLM:\Software\Microsoft\Windows NT\CurrentVersion\Windows', 'HKLM:\Software\Wow6432Node\Microsoft\Windows NT\CurrentVersion\Windows')) {
            if (-not (Test-Path $p)) { continue }
            $v = (Get-ItemProperty $p -ErrorAction SilentlyContinue).AppInit_DLLs
            if ($v) { & $add 'AppInit' 'AppInit_DLLs' $v $p }
        }
    }

    # ── Image File Execution Options debuggers ──
    Invoke-WfxStep 'persist:ifeo' {
        $ifeo = 'HKLM:\Software\Microsoft\Windows NT\CurrentVersion\Image File Execution Options'
        if (Test-Path $ifeo) {
            Get-ChildItem $ifeo -ErrorAction SilentlyContinue | ForEach-Object {
                $dbg = (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).Debugger
                if ($dbg) { & $add 'ImageFileExecution' ($_.PSChildName) $dbg $ifeo }
            }
        }
    }

    # ── LSA security/authentication packages ──
    Invoke-WfxStep 'persist:lsa' {
        $lsa = 'HKLM:\System\CurrentControlSet\Control\Lsa'
        if (Test-Path $lsa) {
            $k = Get-ItemProperty $lsa -ErrorAction SilentlyContinue
            foreach ($v in @('Security Packages', 'Authentication Packages', 'Notification Packages')) {
                $known = @('kerberos', 'msv1_0', 'schannel', 'wdigest', 'tspkg', 'pku2u', 'cloudap', 'negoexts', 'livessp', '""', 'scecli', 'rassfm')
                foreach ($pkg in @($k.$v | Where-Object { $_ })) {
                    if ($pkg.ToLower().Trim('"') -notin $known) { & $add 'LsaProvider' "$v`:$pkg" $pkg $lsa }
                }
            }
        }
    }

    # ── BootExecute ──
    Invoke-WfxStep 'persist:bootexec' {
        $sm = 'HKLM:\System\CurrentControlSet\Control\Session Manager'
        if (Test-Path $sm) {
            foreach ($be in @((Get-ItemProperty $sm -ErrorAction SilentlyContinue).BootExecute | Where-Object { $_ })) {
                if ($be -notmatch '^autocheck\s+autochk') { & $add 'BootExecute' $be $be $sm }
            }
        }
    }

    , @($out.ToArray())
}

function Get-WfxUserHives {
    <# Returns registry paths for all loaded user hives (Registry::HKEY_USERS\<sid>). #>
    $hives = @('HKCU:')
    try {
        Get-ChildItem 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-' -and $_.PSChildName -notmatch '_Classes$' } | ForEach-Object {
            $hives += "Registry::HKEY_USERS\$($_.PSChildName)"
        }
    } catch {}
    $hives
}


# ===== Collectors/Security.ps1 =====
# Security-posture collector — gathers the host's defensive configuration so the triage can tell the
# difference between "nothing found" and "nothing could be seen". Read-only. Produces one posture
# object the Posture analyzer turns into visibility/hardening findings, plus an AI-tooling inventory.

function Get-WfxRegValue {
    param([string]$Path, [string]$Name)
    try { $p = Get-ItemProperty -Path $Path -Name $Name -ErrorAction Stop; return $p.$Name } catch { return $null }
}

function Get-WfxSecurityData {
    if (-not (Test-WfxWindows)) {
        return [pscustomobject]@{ Defender = $null; ThirdPartyAV = @(); Firewall = $null; Audit = $null; BitLocker = $null; Lsa = $null; Rdp = $null; AiTools = @() }
    }

    # ── Microsoft Defender ──
    $defender = Invoke-WfxStep 'posture:defender' {
        $st = $null; $pf = $null
        try { $st = Get-MpComputerStatus -ErrorAction Stop } catch {}
        try { $pf = Get-MpPreference -ErrorAction Stop } catch {}
        if (-not $st -and -not $pf) { throw 'Defender cmdlets unavailable' }
        $sigAge = $null
        if ($st -and $st.AntivirusSignatureLastUpdated) { try { $sigAge = [int]((Get-Date) - $st.AntivirusSignatureLastUpdated).TotalDays } catch {} }
        [pscustomobject]@{
            Installed                 = $true
            AntivirusEnabled          = if ($st) { [bool]$st.AntivirusEnabled } else { $null }
            RealTimeProtectionEnabled = if ($st) { [bool]$st.RealTimeProtectionEnabled } else { $null }
            TamperProtectionEnabled   = if ($st) { [bool]$st.IsTamperProtected } else { $null }
            BehaviorMonitorEnabled    = if ($st) { [bool]$st.BehaviorMonitorEnabled } else { $null }
            SignatureAgeDays          = $sigAge
            EngineVersion             = if ($st) { [string]$st.AMEngineVersion } else { '' }
            ExclusionPath             = if ($pf) { @($pf.ExclusionPath | Where-Object { $_ }) } else { @() }
            ExclusionProcess          = if ($pf) { @($pf.ExclusionProcess | Where-Object { $_ }) } else { @() }
            ExclusionExtension        = if ($pf) { @($pf.ExclusionExtension | Where-Object { $_ }) } else { @() }
            DisableRealtimeMonitoring = if ($pf) { [bool]$pf.DisableRealtimeMonitoring } else { $null }
        }
    } $null

    # ── Registered AV products (SecurityCenter2) — tells us if a 3rd-party AV is the active engine ──
    $thirdParty = Invoke-WfxStep 'posture:securitycenter' {
        @(Get-CimInstance -Namespace 'root\SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop |
            Where-Object { $_.displayName -and $_.displayName -notmatch '(?i)windows defender|microsoft defender' } |
            ForEach-Object { $_.displayName })
    } @()

    # ── Firewall profiles ──
    $firewall = Invoke-WfxStep 'posture:firewall' {
        $fw = @{}
        Get-NetFirewallProfile -ErrorAction Stop | ForEach-Object { $fw[[string]$_.Name] = [bool]$_.Enabled }
        [pscustomobject]$fw
    } $null

    # ── Audit / logging visibility ──
    $audit = Invoke-WfxStep 'posture:audit' {
        $procAudit = $false
        try {
            $ap = auditpol /get /subcategory:"Process Creation" 2>$null
            if ($ap -match '(?i)Process Creation\s+(Success|Success and Failure)') { $procAudit = $true }
        } catch {}
        [pscustomobject]@{
            ProcessCreation             = $procAudit
            CommandLineInProcessCreation = ((Get-WfxRegValue 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\Audit' 'ProcessCreationIncludeCmdLine_Enabled') -eq 1)
            ScriptBlockLogging          = ((Get-WfxRegValue 'HKLM:\Software\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging' 'EnableScriptBlockLogging') -eq 1)
            ModuleLogging               = ((Get-WfxRegValue 'HKLM:\Software\Policies\Microsoft\Windows\PowerShell\ModuleLogging' 'EnableModuleLogging') -eq 1)
            Transcription               = ((Get-WfxRegValue 'HKLM:\Software\Policies\Microsoft\Windows\PowerShell\Transcription' 'EnableTranscripting') -eq 1)
            SysmonInstalled             = [bool]((Get-Service -Name 'Sysmon', 'Sysmon64' -ErrorAction SilentlyContinue) | Where-Object { $_.Status -eq 'Running' })
        }
    } $null

    # ── LSASS protection / Credential Guard ──
    $lsa = Invoke-WfxStep 'posture:lsa' {
        $cg = $null
        try { $dg = Get-CimInstance -Namespace 'root\Microsoft\Windows\DeviceGuard' -ClassName Win32_DeviceGuard -ErrorAction Stop; $cg = (@($dg.SecurityServicesRunning) -contains 1) } catch {}
        [pscustomobject]@{
            RunAsPPL        = ((Get-WfxRegValue 'HKLM:\System\CurrentControlSet\Control\Lsa' 'RunAsPPL') -in @(1, 2))
            CredentialGuard = $cg
        }
    } $null

    # ── RDP exposure ──
    $rdp = Invoke-WfxStep 'posture:rdp' {
        $deny = Get-WfxRegValue 'HKLM:\System\CurrentControlSet\Control\Terminal Server' 'fDenyTSConnections'
        $nla = Get-WfxRegValue 'HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' 'UserAuthentication'
        [pscustomobject]@{ Enabled = ($deny -eq 0); NlaEnabled = ($nla -eq 1) }
    } $null

    # ── BitLocker (system drive) ──
    $bitlocker = Invoke-WfxStep 'posture:bitlocker' {
        $v = Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction Stop
        [pscustomobject]@{ SystemDriveProtection = [string]$v.ProtectionStatus; Encryption = [string]$v.VolumeStatus }
    } $null

    # ── AI tooling inventory (installed runtimes / assistant CLIs) — context, not a finding by itself ──
    $aiTools = Invoke-WfxStep 'posture:aitools' {
        $found = New-Object System.Collections.Generic.List[object]
        $dirs = @(
            @{ N = 'Ollama'; P = "$env:LOCALAPPDATA\Programs\Ollama" }
            @{ N = 'LM Studio'; P = "$env:LOCALAPPDATA\LM-Studio" }
            @{ N = 'Jan'; P = "$env:LOCALAPPDATA\Programs\Jan" }
            @{ N = 'GPT4All'; P = "$env:LOCALAPPDATA\nomic.ai\GPT4All" }
            @{ N = 'Open WebUI'; P = "$env:LOCALAPPDATA\open-webui" }
        )
        foreach ($d in $dirs) { if (Test-Path -LiteralPath $d.P) { $found.Add([pscustomobject]@{ Name = $d.N; Path = $d.P; Kind = 'runtime' }) } }
        foreach ($cli in @('ollama', 'llm', 'claude', 'openai', 'aider', 'gh-copilot')) {
            $c = Get-Command $cli -ErrorAction SilentlyContinue
            if ($c) { $found.Add([pscustomobject]@{ Name = $cli; Path = $c.Source; Kind = 'cli' }) }
        }
        @($found.ToArray())
    } @()

    [pscustomobject]@{
        Defender     = $defender
        ThirdPartyAV = @($thirdParty)
        Firewall     = $firewall
        Audit        = $audit
        Lsa          = $lsa
        Rdp          = $rdp
        BitLocker    = $bitlocker
        AiTools      = @($aiTools)
    }
}


# ===== Collectors/System.ps1 =====
# Windows collectors — gather live data into the normalized shapes the analyzers consume.
# Every collector: returns [] on non-Windows or on error (recorded as a gap), never throws,
# and degrades gracefully without administrator rights.

function Get-WfxHostInfo {
    if (-not (Test-WfxWindows)) {
        return [pscustomobject]@{ HostName = [Environment]::MachineName; Os = 'Non-Windows (collectors limited)'; Collected = (Get-Date).ToUniversalTime().ToString('o'); Admin = $false }
    }
    $os = Invoke-WfxStep 'hostinfo:os' { Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } $null
    $cs = Invoke-WfxStep 'hostinfo:cs' { Get-CimInstance Win32_ComputerSystem -ErrorAction Stop } $null
    [pscustomobject]@{
        HostName   = [Environment]::MachineName
        Domain     = if ($cs) { $cs.Domain } else { '' }
        Os         = if ($os) { "$($os.Caption) $($os.Version) (build $($os.BuildNumber))" } else { '' }
        Boot       = if ($os) { $os.LastBootUpTime } else { $null }
        Manufacturer = if ($cs) { "$($cs.Manufacturer) $($cs.Model)" } else { '' }
        Collected  = (Get-Date).ToUniversalTime().ToString('o')
        TimeZone   = (Get-TimeZone -ErrorAction SilentlyContinue).Id
        Admin      = (Test-WfxAdmin)
        Operator   = [Environment]::UserName
        PSVersion  = $PSVersionTable.PSVersion.ToString()
    }
}

function Get-WfxProcessData {
    <# Normalized process list with parent linkage, signature status and hashes (admin gets command lines reliably). #>
    if (-not (Test-WfxWindows)) { return @() }
    $raw = Invoke-WfxStep 'process:list' { Get-CimInstance Win32_Process -ErrorAction Stop } @()
    if (-not $raw) { return @() }
    $byPid = @{}
    foreach ($p in $raw) { $byPid[[string]$p.ProcessId] = $p }
    # Signatures/paths are relatively expensive; cache by path.
    $sigCache = @{}
    $out = foreach ($p in $raw) {
        $path = $p.ExecutablePath
        if (-not $path) { $path = Get-WfxImagePath $p.CommandLine }
        $sig = ''
        $company = ''
        if ($path -and (Test-Path -LiteralPath $path -ErrorAction SilentlyContinue)) {
            if ($sigCache.ContainsKey($path)) { $sig = $sigCache[$path].Sig; $company = $sigCache[$path].Co }
            else {
                try {
                    $s = Get-AuthenticodeSignature -LiteralPath $path -ErrorAction Stop
                    $sig = [string]$s.Status
                    try { $company = (Get-Item -LiteralPath $path).VersionInfo.CompanyName } catch { $company = '' }
                } catch { $sig = 'Unknown' }
                $sigCache[$path] = @{ Sig = $sig; Co = $company }
            }
        }
        $parent = $byPid[[string]$p.ParentProcessId]
        $owner = ''
        try { $owner = (Invoke-CimMethod -InputObject $p -MethodName GetOwner -ErrorAction SilentlyContinue).User } catch { $owner = '' }
        [pscustomobject]@{
            Pid             = [int]$p.ProcessId
            Ppid            = [int]$p.ParentProcessId
            Name            = $p.Name
            Path            = $path
            # Scrub secrets out of command lines at collection time, so the raw bundle is safe to persist
            # and ship. Tool/command structure is preserved; only embedded secret values are redacted.
            CommandLine     = (Protect-WfxText $p.CommandLine)
            ParentName      = if ($parent) { $parent.Name } else { '' }
            ParentPath      = if ($parent) { $parent.ExecutablePath } else { '' }
            ParentCommandLine = if ($parent) { Protect-WfxText $parent.CommandLine } else { '' }
            SignatureStatus = $sig
            Company         = $company
            CreateTime      = $p.CreationDate
            User            = $owner
        }
    }
    , @($out)
}

function Get-WfxNetworkData {
    if (-not (Test-WfxWindows)) { return @() }
    $procNames = @{}
    try { Get-Process -ErrorAction SilentlyContinue | ForEach-Object { $procNames[[string]$_.Id] = $_.ProcessName } } catch {}
    $out = New-Object System.Collections.Generic.List[object]
    $tcp = Invoke-WfxStep 'network:tcp' { Get-NetTCPConnection -ErrorAction Stop } $null
    if ($tcp) {
        foreach ($c in $tcp) {
            $out.Add([pscustomobject]@{
                    Protocol = 'TCP'; LocalAddress = $c.LocalAddress; LocalPort = $c.LocalPort
                    RemoteAddress = $c.RemoteAddress; RemotePort = $c.RemotePort; State = [string]$c.State
                    Pid = $c.OwningProcess; Process = $procNames[[string]$c.OwningProcess]
                    RemoteHost = ''
                })
        }
    } else {
        # Fallback for very old hosts: parse netstat.
        $ns = Invoke-WfxStep 'network:netstat' { netstat -ano } @()
        foreach ($line in $ns) {
            if ($line -match '^\s*(TCP|UDP)\s+(\S+):(\d+)\s+(\S+):(\d+|\*)\s+(\S*)\s*(\d*)\s*$') {
                $out.Add([pscustomobject]@{ Protocol = $Matches[1]; LocalAddress = $Matches[2]; LocalPort = [int]$Matches[3]
                        RemoteAddress = $Matches[4]; RemotePort = ($Matches[5] -replace '\*', '0'); State = $Matches[6]
                        Pid = $Matches[7]; Process = $procNames[$Matches[7]]; RemoteHost = '' })
            }
        }
    }
    # Resolve a handful of public remote addresses to names for the DNS/beacon context (best-effort, bounded).
    $resolved = @{}
    foreach ($c in $out) {
        if ($c.State -match 'Establish' -and $c.RemoteAddress -and -not (Test-WfxPrivateIp $c.RemoteAddress) -and -not $resolved.ContainsKey($c.RemoteAddress)) {
            if ($resolved.Count -ge 40) { break }
            try { $resolved[$c.RemoteAddress] = ([System.Net.Dns]::GetHostEntry($c.RemoteAddress)).HostName } catch { $resolved[$c.RemoteAddress] = '' }
        }
    }
    foreach ($c in $out) { if ($resolved.ContainsKey($c.RemoteAddress)) { $c.RemoteHost = $resolved[$c.RemoteAddress] } }
    , @($out.ToArray())
}

function Get-WfxDnsData {
    if (-not (Test-WfxWindows)) { return @() }
    $raw = Invoke-WfxStep 'dns:cache' { Get-DnsClientCache -ErrorAction Stop } $null
    if ($null -eq $raw) {
        # Fallback: ipconfig /displaydns parsing.
        $out = New-Object System.Collections.Generic.List[object]
        $dns = Invoke-WfxStep 'dns:ipconfig' { ipconfig /displaydns } @()
        $cur = ''
        foreach ($line in $dns) {
            if ($line -match 'Record Name[.\s]*:\s*(\S+)') { $cur = $Matches[1] }
            elseif ($line -match 'CNAME Record|A \(Host\) Record|AAAA Record' -and $cur) { $out.Add([pscustomobject]@{ Name = $cur; Type = 'A'; Data = '' }) }
        }
        return , @($out.ToArray())
    }
    , @($raw | ForEach-Object { [pscustomobject]@{ Name = $_.Entry; Type = [string]$_.Type; Data = $_.Data; TTL = $_.TimeToLive } } | Where-Object { $_.Name })
}

function Get-WfxServiceAndDriver {
    <# Services and kernel drivers → autostart records (Kind Service / Driver). #>
    if (-not (Test-WfxWindows)) { return @() }
    $out = New-Object System.Collections.Generic.List[object]
    $svc = Invoke-WfxStep 'persist:services' { Get-CimInstance Win32_Service -ErrorAction Stop } @()
    foreach ($s in $svc) {
        $out.Add([pscustomobject]@{ Kind = 'Service'; Name = $s.Name; Command = (Protect-WfxText $s.PathName); Path = (Get-WfxImagePath $s.PathName)
                Location = "Service:$($s.StartMode)"; User = $s.StartName; Enabled = ($s.StartMode -ne 'Disabled'); SignatureStatus = (Get-WfxSignature (Get-WfxImagePath $s.PathName)) })
    }
    $drv = Invoke-WfxStep 'persist:drivers' { Get-CimInstance Win32_SystemDriver -ErrorAction Stop } @()
    foreach ($d in $drv) {
        if ($d.State -ne 'Running' -and $d.StartMode -eq 'Disabled') { continue }
        $out.Add([pscustomobject]@{ Kind = 'Driver'; Name = $d.Name; Command = (Protect-WfxText $d.PathName); Path = ($d.PathName -replace '^\\\?\?\\', '' -replace '^System32', "$env:SystemRoot\System32")
                Location = "Driver:$($d.StartMode)"; Enabled = ($d.StartMode -ne 'Disabled'); SignatureStatus = (Get-WfxSignature ($d.PathName -replace '^\\\?\?\\', '')) })
    }
    , @($out.ToArray())
}

function Get-WfxSignature {
    param([string]$Path)
    if (-not $Path -or -not (Test-WfxWindows)) { return '' }
    if (-not (Test-Path -LiteralPath $Path -ErrorAction SilentlyContinue)) { return '' }
    try { return [string](Get-AuthenticodeSignature -LiteralPath $Path -ErrorAction Stop).Status } catch { return 'Unknown' }
}


# ===== Report/Guide.ps1 =====
function New-WfxGuide {
    <#
    .SYNOPSIS Writes a self-contained HTML usage guide (how to use, commands, outputs, limitations, safety),
              in the same "Beacon" look as the report.
    .PARAMETER Path  Output .html path.
    .OUTPUTS The output path.
    #>
    [CmdletBinding()]
    param([string]$Path = (Join-Path ([IO.Path]::GetTempPath()) 'WinForensicX-guide.html'))
    $h = Get-WfxHelpModel
    $enc = { param($s) [System.Net.WebUtility]::HtmlEncode([string]$s) }

    $cmdHtml = foreach ($c in $h.Commands) {
        $ex = ($c.Examples | ForEach-Object { "<div class='ex mono'>$(& $enc $_)</div>" }) -join ''
        $pr = if (@($c.Params).Count) { "<div class='params mono'>" + ((@($c.Params) | ForEach-Object { & $enc $_ }) -join '<br>') + "</div>" } else { '' }
        @"
<div class="cmd">
  <div class="cmd-h"><span class="cmd-n mono">$(& $enc $c.Name)</span><span class="cmd-s">$(& $enc $c.Summary)</span></div>
  $pr$ex
</div>
"@
    }
    $outRows = ($h.Outputs | ForEach-Object { "<li class='mono'>$(& $enc $_)</li>" }) -join ''
    $limRows = ($h.Limits | ForEach-Object { "<li>$(& $enc $_)</li>" }) -join ''
    $safeRows = ($h.Safety | ForEach-Object { "<li>$(& $enc $_)</li>" }) -join ''

    $html = @"
<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>WinForensicX $(& $enc $h.Version) · Guide</title>
<style>
$(Get-WfxThemeCss)
.wrap{max-width:900px;margin:0 auto;padding:24px 22px 90px}
.hero{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:26px 28px;box-shadow:var(--sh2);margin-bottom:24px}
.hero .k{font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--faint);margin-bottom:8px}
.hero h1{font-size:26px;font-weight:800;letter-spacing:-.03em;color:var(--ink2)}
.hero h1 small{font-family:var(--mono);font-size:12px;color:var(--faint);font-weight:400;margin-left:9px}
.hero p{color:var(--dim);max-width:70ch;margin-top:11px;font-size:14.5px}
.sec{display:flex;align-items:center;gap:12px;margin:28px 0 14px}
.sec h2{font-size:14px;font-weight:750;color:var(--ink2)}
.sec::after{content:"";flex:1;height:1px;background:var(--line)}
.cmd{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:15px 17px;margin-bottom:11px;box-shadow:var(--sh)}
.cmd-h{display:flex;flex-wrap:wrap;gap:9px;align-items:baseline;margin-bottom:4px}
.cmd-n{color:var(--acc);font-size:14.5px;font-weight:700}.cmd-s{color:var(--dim);font-size:13.5px}
.params{color:var(--ink);font-size:12.5px;margin:9px 0 2px;padding:8px 11px;border-left:2px solid var(--line2);background:var(--card2);border-radius:7px}
.ex{color:var(--ink2);font-size:12.5px;background:var(--card2);border:1px solid var(--line);border-radius:7px;padding:8px 11px;margin-top:7px;overflow-x:auto}
.ex::before{content:"$ ";color:var(--ok)}
ul.list{list-style:none}
ul.list li{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:10px 13px;margin-bottom:8px;font-size:13.5px;color:var(--ink);box-shadow:var(--sh)}
ul.list.mono-list li{font-family:var(--mono);font-size:12px}
ul.list.warn li{border-left:3px solid var(--high)}
ul.list.safe li{border-left:3px solid var(--ok)}
.req{font-family:var(--mono);font-size:12.5px;color:var(--dim);border:1px dashed var(--line2);border-radius:12px;padding:11px 14px;background:var(--card)}
.foot{margin-top:32px;border-top:1px solid var(--line);padding-top:16px;color:var(--faint);font-size:12.5px}
</style></head><body>
<div class="wrap">
  <div class="bar"><div class="bz">W</div><div class="bn">WinForensicX<span>help &amp; how-to</span></div>
    <div class="sp"></div><div class="chip" id="when"></div>
    <button class="gbtn" id="themebtn" title="Toggle theme">Theme</button></div>

  <div class="hero"><div class="k">Getting started</div>
    <h1>WinForensicX <small>$(& $enc $h.Version) · read-only DFIR triage</small></h1>
    <p>$(& $enc $h.Tagline)</p></div>

  <div class="sec"><h2>Commands</h2></div>$($cmdHtml -join "`n")
  <div class="sec"><h2>What a run produces</h2></div><ul class="list mono-list">$outRows</ul>
  <div class="sec"><h2>Safety &amp; defensive posture</h2></div><ul class="list safe">$safeRows</ul>
  <div class="sec"><h2>Limitations</h2></div><ul class="list warn">$limRows</ul>
  <div class="sec"><h2>Requirements</h2></div><div class="req">$(& $enc $h.Requires)</div>
  <div class="foot">WinForensicX $(& $enc $h.Version) · generated $(Get-Date -Format 'u') · self-contained and safe to share.</div>
</div>
<script>
(function(){try{var s=localStorage.getItem('wfx-theme');if(s)document.documentElement.setAttribute('data-theme',s);}catch(e){}
var t=document.getElementById('themebtn');if(t)t.onclick=function(){var c=document.documentElement.getAttribute('data-theme');
var n=c==='light'?'dark':(c==='dark'?'light':(matchMedia('(prefers-color-scheme:dark)').matches?'light':'dark'));
document.documentElement.setAttribute('data-theme',n);try{localStorage.setItem('wfx-theme',n);}catch(e){}};
var w=document.getElementById('when');if(w)w.textContent=new Date().toLocaleString();})();
</script>
</body></html>
"@
    [IO.File]::WriteAllText($Path, $html, (New-Object Text.UTF8Encoding($false)))
    return $Path
}


# ===== Report/Report.ps1 =====
function New-WfxReport {
    <#
    .SYNOPSIS
        Renders a self-contained (no external assets) HTML triage report from an Invoke-WfxAnalyze result.
        Decision-first "Beacon" design. Embeds only already-redacted findings data — never raw collected
        data or secret values.
    .PARAMETER Result  The result object from Invoke-WfxAnalyze.
    .PARAMETER Path    Output .html path.
    .OUTPUTS The output path.
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory)]$Result, [Parameter(Mandatory)][string]$Path)

    $help = Get-WfxHelpModel
    $data = [ordered]@{
        tool      = "WinForensicX $($script:WfxVersion)"
        version   = [string]$script:WfxVersion
        generated = (Get-Date).ToUniversalTime().ToString('o')
        hostName  = [string](Get-WfxValue $Result 'HostName' '')
        host      = (Get-WfxValue $Result 'Host' $null)
        risk      = (Get-WfxValue $Result 'Risk' $null)
        summary   = (Get-WfxValue $Result 'Summary' $null)
        findings  = @(Get-WfxValue $Result 'Findings' @())
        coverage  = @(Get-WfxValue $Result 'AttackCoverage' @())
        gaps      = @(Get-WfxValue $Result 'Gaps' @())
        meta      = (Get-WfxValue $Result 'Meta' $null)
        limits    = @($help.Limits)
        safety    = @($help.Safety)
    }
    $json = ConvertTo-Json -InputObject $data -Depth 12
    # \uXXXX escapes built from a literal backslash char so they can't collapse to a no-op; JSON.parse
    # restores them, so any "</script>" in a field becomes inert "</script>".
    $bs = [string][char]0x5C
    $json = $json.Replace('&', "${bs}u0026").Replace('<', "${bs}u003c").Replace('>', "${bs}u003e").Replace([string][char]0x2028, "${bs}u2028").Replace([string][char]0x2029, "${bs}u2029")

    $html = $script:WfxReportTemplate
    $html = $html.Replace('/*__WFX_THEME__*/', (Get-WfxThemeCss))
    $html = $html.Replace('/*__WFX_DATA__*/', $json)
    $html = $html.Replace('__WFX_HOST__', [System.Net.WebUtility]::HtmlEncode($data.hostName))

    [IO.File]::WriteAllText($Path, $html, (New-Object Text.UTF8Encoding($false)))
    return $Path
}

