.m{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:16px 18px;box-shadow:var(--sh)}
.m .k{font-size:12.5px;color:var(--dim);margin-bottom:10px;font-weight:550}
.m .v{font-size:30px;font-weight:800;letter-spacing:-.03em;line-height:1;color:var(--ink2)}
.m .sb{height:6px;border-radius:4px;background:var(--line);margin-top:13px;overflow:hidden;display:flex}
.m .sb i{height:100%}
.m .leg{display:flex;flex-wrap:wrap;gap:4px 12px;margin-top:11px}
.m .leg span{font-size:12px;color:var(--dim);display:flex;align-items:center;gap:6px}
.m .leg .q{width:8px;height:8px;border-radius:2px}
.m .hint{font-size:12px;color:var(--faint);margin-top:11px}
/* section header + controls */
.sec{display:flex;align-items:center;gap:12px;margin:30px 0 14px;flex-wrap:wrap}
.sec h2{font-size:14px;font-weight:750;letter-spacing:.01em;color:var(--ink2)}
.sec .ct{font-size:12.5px;color:var(--faint);font-weight:600}
.sec .sp{flex:1}
.ctrls{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.ctrls input,.ctrls select{font-size:13px;background:var(--card);border:1px solid var(--line2);color:var(--ink);
  border-radius:9px;padding:8px 11px;box-shadow:var(--sh)}
.ctrls input{min-width:180px}.ctrls input:focus,.ctrls select:focus{outline:none;border-color:var(--acc)}
.filters{display:flex;gap:8px;flex-wrap:wrap}
.ff{font-size:12.5px;font-weight:600;color:var(--dim);background:var(--card);border:1px solid var(--line2);
  border-radius:999px;padding:6px 13px;cursor:pointer;display:flex;align-items:center;gap:7px;box-shadow:var(--sh)}
.ff .d{width:8px;height:8px;border-radius:50%}
/* findings */
.flist{display:flex;flex-direction:column;gap:10px}
.f{background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden;transition:box-shadow .12s,transform .12s}
.f:hover{box-shadow:var(--sh2);transform:translateY(-1px)}
.f.open{transform:none}
.fhead{display:grid;grid-template-columns:96px 1fr auto;gap:18px;align-items:center;padding:16px 18px;cursor:pointer}
.fhead .pill{font-size:11px;font-weight:800;letter-spacing:.05em;padding:5px 0;border-radius:8px;text-align:center;color:#fff}
.fhead .ti{font-size:15.5px;font-weight:650;letter-spacing:-.01em;color:var(--ink2)}
.fhead .wy{font-size:13.5px;color:var(--dim);margin-top:3px}
.fhead .tags{margin-top:9px;display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.fhead .tags .cat{font-size:11px;color:var(--faint);font-weight:600}
.fhead .tags a{font-family:var(--mono);font-size:11px;color:var(--acc);background:var(--acc2);border-radius:6px;padding:2px 8px;text-decoration:none}
.fhead .rt{text-align:right;white-space:nowrap}
.fhead .rt .sc{font-size:22px;font-weight:800;letter-spacing:-1px}
.fhead .rt .id{font-family:var(--mono);font-size:10.5px;color:var(--faint);margin-top:2px}
.fbody{display:none;padding:2px 18px 18px;border-top:1px solid var(--line)}
.f.open .fbody{display:block}
.fbody p{margin:14px 0;color:var(--ink);max-width:80ch;font-size:14px}
.fbody .ent{font-family:var(--mono);font-size:11.5px;color:var(--faint)}
.kv{width:100%;border-collapse:collapse;margin:12px 0;font-family:var(--mono);font-size:12px}
.kv td{border:1px solid var(--line);padding:7px 10px;vertical-align:top}
.kv td.k{color:var(--dim);white-space:nowrap;width:160px;background:var(--card2)}
.kv td.v{color:var(--ink);word-break:break-word}
.rec{border:1px solid var(--line);border-left:3px solid var(--ok);border-radius:11px;background:var(--card2);padding:12px 15px;margin-top:12px;font-size:14px}
.rec .k{font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--ok);font-weight:800;display:block;margin-bottom:4px}
.empty{color:var(--dim);padding:22px;text-align:center;border:1px dashed var(--line2);border-radius:var(--r);background:var(--card)}
/* attack + timeline + notes */
.attack{display:flex;flex-wrap:wrap;gap:9px}
.at{background:var(--card);border:1px solid var(--line);border-radius:11px;padding:11px 14px;box-shadow:var(--sh);min-width:150px}
.at h4{font-size:12px;font-weight:700;color:var(--ink2);margin-bottom:8px}
.at a{display:block;font-family:var(--mono);font-size:11px;color:var(--dim);padding:2px 0;text-decoration:none}
.at a:hover{color:var(--acc)}.at a b{color:var(--acc);font-weight:600}
.tl{border-left:2px solid var(--line);margin-left:7px;padding-left:18px}
.tl .ev{position:relative;padding:4px 0 14px}
.tl .ev::before{content:"";position:absolute;left:-25px;top:6px;width:11px;height:11px;border-radius:50%;border:2px solid var(--bg)}
.tl time{font-family:var(--mono);font-size:12px;color:var(--faint);margin-right:10px}
.cards{display:grid;grid-template-columns:1fr 1fr;gap:10px}@media(max-width:700px){.cards{grid-template-columns:1fr}}
.note{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 15px;box-shadow:var(--sh);font-size:13.5px;color:var(--ink);display:flex;gap:11px}
.note .n{font-family:var(--mono);font-weight:800;color:var(--acc);flex:none}
.gap{background:var(--card);border:1px solid var(--line);border-left:3px solid var(--high);border-radius:12px;padding:11px 14px;margin-bottom:8px;box-shadow:var(--sh);font-size:13.5px}
.gap b{color:var(--high);font-family:var(--mono);font-size:12.5px}
.gap .fix{color:var(--dim);font-size:12.5px;margin-top:3px}
.foot{margin-top:34px;color:var(--faint);font-size:12.5px;border-top:1px solid var(--line);padding-top:16px}
</style>
</head>
<body>
<div class="wrap">
  <div class="bar">
    <div class="bz">W</div><div class="bn">WinForensicX<span>incident triage</span></div>
    <div class="sp"></div>
    <div class="chip">Host <b id="host"></b></div>
    <div class="chip" id="when"></div>
    <button class="gbtn" id="themebtn" title="Toggle theme (t)">Theme</button>
  </div>

  <div class="hero">
    <div class="ring">
      <div class="rwrap"><svg viewBox="0 0 168 168" width="168" height="168">
        <circle cx="84" cy="84" r="72" fill="none" stroke="var(--line)" stroke-width="14"></circle>
        <circle id="ring" cx="84" cy="84" r="72" fill="none" stroke-width="14" stroke-linecap="round" transform="rotate(-90 84 84)"></circle>
      </svg><div class="c"><b id="rn">0</b><small>RISK / 100</small></div></div>
      <div class="rlvl" id="lvl">&mdash;</div>
    </div>
    <div class="hd">
      <div class="k">Executive summary</div>
      <h1 id="verdict">&mdash;</h1>
      <div class="blurb" id="blurb"></div>
      <div class="pa"><div class="t">Priority actions</div><div id="actions"></div></div>
    </div>
  </div>

  <div class="metrics">
    <div class="m"><div class="k">Total findings</div><div class="v" id="tf">0</div><div class="sb" id="sb"></div><div class="leg" id="leg"></div></div>
    <div class="m"><div class="k">Critical &amp; High</div><div class="v fg-Critical" id="tch">0</div><div class="hint">act on these first</div></div>
    <div class="m"><div class="k">ATT&amp;CK techniques</div><div class="v" id="tt">0</div><div class="hint">adversary behaviors seen</div></div>
    <div class="m"><div class="k">Visibility gaps</div><div class="v fg-High" id="tg">0</div><div class="hint">areas the tool couldn't see</div></div>
  </div>

  <div class="sec" id="findings">
    <h2>Findings</h2><span class="ct" id="fct"></span><span class="sp"></span>
    <div class="ctrls">
      <input id="q" placeholder="Search findings…" autocomplete="off" spellcheck="false">
      <select id="sort"><option value="sev">Severity</option><option value="score">Score</option><option value="cat">Category</option></select>
    </div>
  </div>
  <div class="filters" id="filters" style="margin-bottom:14px"></div>
  <div class="flist" id="list"></div>

  <div class="sec" id="attack"><h2>ATT&amp;CK coverage</h2></div>
  <div class="attack" id="matrix"></div>

  <div class="sec" id="timeline"><h2>Timeline</h2></div>
  <div id="tlwrap"></div>

  <div class="sec" id="limits"><h2>Limitations &amp; how to read this</h2></div>
  <div class="cards" id="limwrap"></div>

  <div class="sec" id="gaps"><h2>Collection gaps</h2></div>
  <div id="gapwrap"></div>

  <div class="foot" id="foot"></div>
</div>

<script id="wfx-data" type="application/json">/*__WFX_DATA__*/</script>
<script>
(function(){
  "use strict";
  var D; try{ D=JSON.parse(document.getElementById('wfx-data').textContent); }
  catch(e){ document.body.innerHTML='<p style="padding:24px">Could not load report data.</p>'; return; }
  var SEV=['Critical','High','Medium','Low','Info'], RK={Critical:0,High:1,Medium:2,Low:3,Info:4};
  var el=function(id){return document.getElementById(id);};
  var esc=function(s){var d=document.createElement('div');d.textContent=(s==null?'':String(s));return d.innerHTML;};
  var au=function(id){return 'https://attack.mitre.org/techniques/'+String(id).replace('.','/')+'/';};
  var why=function(f){var d=(f.Description||'').trim();if(d.length>135)d=d.slice(0,132).replace(/\s+\S*$/,'')+'…';return d;};
  var F=(D.findings||[]).slice();
  var COL={Critical:'var(--crit)',High:'var(--high)',Medium:'var(--med)',Low:'var(--low)',Info:'var(--info)'};

  // theme
  try{var sv=localStorage.getItem('wfx-theme');if(sv)document.documentElement.setAttribute('data-theme',sv);}catch(e){}
  el('themebtn').onclick=function(){var cur=document.documentElement.getAttribute('data-theme');
    var nx=cur==='light'?'dark':(cur==='dark'?'light':(matchMedia('(prefers-color-scheme:dark)').matches?'light':'dark'));
    document.documentElement.setAttribute('data-theme',nx);try{localStorage.setItem('wfx-theme',nx);}catch(e){} };

  // header + hero
  el('host').textContent=D.hostName||'(unknown)';
  el('when').textContent=new Date(D.generated).toLocaleString();
  var risk=D.risk||{Score:0,Level:'Low'};
  var vc={Critical:'var(--crit)',High:'var(--high)',Elevated:'var(--med)',Low:'var(--ok)'}[risk.Level]||'var(--ok)';
  el('rn').textContent=risk.Score;
  var ring=el('ring'),C=2*Math.PI*72;ring.style.stroke=vc;ring.style.strokeDasharray=C;ring.style.strokeDashoffset=C*(1-risk.Score/100);
  var lvl=el('lvl');lvl.textContent=risk.Level;lvl.style.color=vc;lvl.style.background='color-mix(in srgb,'+vc+' 15%,transparent)';
  var ch=F.filter(function(f){return f.Severity==='Critical'||f.Severity==='High';}).length;
  el('verdict').textContent=(risk.Level==='Critical'||risk.Level==='High')?'Immediate investigation recommended':(risk.Level==='Elevated'?'Review advised':'No urgent action — monitor');
  el('blurb').textContent='Host '+(D.hostName||'this host')+' scored '+risk.Score+'/100 with '+ch+' high-severity indicator'+(ch===1?'':'s')+' across credential exposure, process tradecraft, network C2 and security posture. Findings are leads for an analyst — confirm before acting, and read them alongside the visibility gaps below.';
  var byScore=F.slice().sort(function(a,b){return RK[a.Severity]-RK[b.Severity]||b.Score-a.Score;});
  el('actions').innerHTML=byScore.slice(0,3).map(function(f){return '<div class="it"><span class="dot" style="background:'+COL[f.Severity]+'"></span><div><b>'+esc(f.Title)+'</b><span>'+esc((f.Recommendation||'').split('. ')[0].replace(/\.$/,''))+'.</span></div></div>';}).join('')||'<div class="empty">No priority actions.</div>';

  // metrics
  var s=D.summary||{},tot=SEV.reduce(function(a,x){return a+(s[x]||0);},0);
  el('tf').textContent=F.length;
  el('sb').innerHTML=SEV.map(function(x){return '<i class="bg-'+x+'" style="width:'+(tot?(s[x]||0)/tot*100:0)+'%"></i>';}).join('');
  el('leg').innerHTML=SEV.filter(function(x){return s[x];}).map(function(x){return '<span><span class="q bg-'+x+'"></span>'+x+' '+s[x]+'</span>';}).join('');
  el('tch').textContent=ch; el('tt').textContent=(D.coverage||[]).length; el('tg').textContent=(D.gaps||[]).length;

  // filters + search + sort + expandable list
  var active='all', q='', sort='sev';
  var counts={}; SEV.forEach(function(x){counts[x]=s[x]||0;});
  var filt=el('filters');
  filt.innerHTML='<button class="ff" data-k="all">All '+F.length+'</button>'+SEV.filter(function(x){return counts[x];}).map(function(x){return '<button class="ff" data-k="'+x+'"><span class="d bg-'+x+'"></span>'+x+' '+counts[x]+'</button>';}).join('');
  function paintFilters(){Array.prototype.forEach.call(filt.children,function(b){var on=b.dataset.k===active;
    b.style.background=on?(b.dataset.k==='all'?'var(--ink)':COL[b.dataset.k]):'';b.style.color=on?'#fff':'';b.style.borderColor=on?'transparent':'';b.style.fontWeight=on?'700':'';});}
  function evidence(ev){
    if(ev==null)return '';
    if(typeof ev!=='object')return '<table class="kv"><tr><td class="k">evidence</td><td class="v">'+esc(ev)+'</td></tr></table>';
    var rows='';Object.keys(ev).forEach(function(k){var v=ev[k];
      if(Array.isArray(v))v=v.length?v.map(function(x){return (x&&typeof x==='object')?esc(JSON.stringify(x)):esc(x);}).join('<br>'):'&mdash;';
      else if(v&&typeof v==='object')v=esc(JSON.stringify(v));else v=esc(v);
      rows+='<tr><td class="k">'+esc(k)+'</td><td class="v">'+v+'</td></tr>';});
    return '<table class="kv">'+rows+'</table>';}
  function card(f){
    var tech=(f.Technique||[]).map(function(t){return '<a href="'+au(t)+'" target="_blank" rel="noopener">'+esc(t)+'</a>';}).join('');
    var occ=(f.Occurrences&&f.Occurrences>1)?('  ×'+f.Occurrences):'';
    var d=document.createElement('div');d.className='f';
    d.innerHTML='<div class="fhead"><div class="pill bg-'+f.Severity+'">'+f.Severity.toUpperCase()+'</div>'+
      '<div class="mid"><div class="ti">'+esc(f.Title)+'</div><div class="wy">'+esc(why(f))+'</div>'+
        '<div class="tags"><span class="cat">'+esc(f.Category)+'</span>'+tech+'</div></div>'+
      '<div class="rt"><div class="sc fg-'+f.Severity+'">'+f.Score+occ+'</div><div class="id">'+esc(f.Id)+'</div></div></div>'+
      '<div class="fbody"><p>'+esc(f.Description)+'</p>'+
        (f.Entity?'<div class="ent">entity: '+esc(f.Entity)+(f.Host?'  ·  host: '+esc(f.Host):'')+(f.Time?'  ·  '+esc(new Date(f.Time).toLocaleString()):'')+'</div>':'')+
        evidence(f.Evidence)+
        (f.Recommendation?'<div class="rec"><span class="k">Recommended</span>'+esc(f.Recommendation)+'</div>':'')+'</div>';
    d.querySelector('.fhead').onclick=function(){d.classList.toggle('open');};
    return d;}
  function render(){
    var rows=F.filter(function(f){
      if(active!=='all'&&f.Severity!==active)return false;
      if(q){var h=(f.Title+' '+f.Id+' '+f.Entity+' '+(f.Technique||[]).join(' ')+' '+JSON.stringify(f.Evidence||'')+' '+f.Category+' '+f.Description).toLowerCase();if(h.indexOf(q)<0)return false;}
      return true;});
    rows.sort(function(a,b){if(sort==='score')return b.Score-a.Score;
      if(sort==='cat')return (a.Category||'').localeCompare(b.Category||'')||(RK[a.Severity]-RK[b.Severity]);
      return (RK[a.Severity]-RK[b.Severity])||(b.Score-a.Score);});
    el('fct').textContent='· '+rows.length+' of '+F.length;
    var list=el('list');list.innerHTML='';
    if(!rows.length){list.innerHTML='<div class="empty">No findings match the current filters.</div>';return;}
    rows.forEach(function(f){list.appendChild(card(f));});}
  filt.addEventListener('click',function(e){var b=e.target.closest('.ff');if(!b)return;active=b.dataset.k;paintFilters();render();});
  el('q').oninput=function(){q=this.value.toLowerCase();render();};
  el('sort').onchange=function(){sort=this.value;render();};
  paintFilters();render();

  // keyboard
  document.addEventListener('keydown',function(e){
    if(e.target.tagName==='INPUT'||e.target.tagName==='SELECT'){if(e.key==='Escape')e.target.blur();return;}
    if(e.key==='/'){e.preventDefault();el('q').focus();return;}
    if(e.key==='t'){el('themebtn').click();return;}
    if(e.key>='1'&&e.key<='5'){var sev=SEV[+e.key-1];active=(active===sev?'all':sev);paintFilters();render();return;}
    if(e.key==='e'){Array.prototype.forEach.call(el('list').children,function(c){c.classList&&c.classList.add('open');});return;}
    if(e.key==='c'){Array.prototype.forEach.call(el('list').children,function(c){c.classList&&c.classList.remove('open');});return;}
  });

  // ATT&CK
  var bt={};(D.coverage||[]).forEach(function(t){var k=t.Tactic||'Other';(bt[k]=bt[k]||[]).push(t);});
  var tk=Object.keys(bt).sort(),mx=el('matrix');
  mx.innerHTML=tk.length?tk.map(function(k){return '<div class="at"><h4>'+esc(k)+'</h4>'+bt[k].map(function(t){return '<a href="'+au(t.Id)+'" target="_blank" rel="noopener"><b>'+esc(t.Id)+'</b> '+esc(t.Name||'')+'</a>';}).join('')+'</div>';}).join(''):'<div class="empty">No techniques observed.</div>';

  // timeline
  var timed=F.filter(function(f){return f.Time;}).sort(function(a,b){return new Date(a.Time)-new Date(b.Time);});
  el('tlwrap').innerHTML=timed.length?'<div class="tl">'+timed.map(function(f){return '<div class="ev"><span class="bg-'+f.Severity+'" style="position:absolute;left:-25px;top:6px;width:11px;height:11px;border-radius:50%;border:2px solid var(--bg)"></span><time>'+esc(new Date(f.Time).toLocaleString())+'</time><span class="fg-'+f.Severity+'" style="font-weight:600">'+esc(f.Title)+'</span></div>';}).join('')+'</div>':'<div class="empty">No time-stamped findings.</div>';

  // limitations
  el('limwrap').innerHTML=(D.limits||[]).map(function(x,i){return '<div class="note"><span class="n">'+String(i+1).padStart(2,'0')+'</span><div>'+esc(x)+'</div></div>';}).join('')||'<div class="empty">&mdash;</div>';

  // gaps
  var g=D.gaps||[];
  el('gapwrap').innerHTML=g.length?g.map(function(x){return '<div class="gap"><b>'+esc(x.Source)+'</b> &mdash; '+esc(x.Reason)+(x.Fix?'<div class="fix">fix: '+esc(x.Fix)+'</div>':'')+'</div>';}).join(''):'<div class="note"><span class="n">ok</span><div>No collection gaps recorded — the triage ran with the visibility it attempted.</div></div>';

  el('foot').innerHTML=esc(D.tool)+' · generated '+new Date(D.generated).toLocaleString()+' · read-only, self-contained. Risk = 1 − Π(1 − wᵢ/40): many low-confidence leads cannot sum to a critical. Keys: <kbd>/</kbd> search · <kbd>1</kbd>–<kbd>5</kbd> filter · <kbd>e</kbd>/<kbd>c</kbd> expand · <kbd>t</kbd> theme.';
})();
</script>
</body>
</html>
'@


# ===== Report/Theme.ps1 =====
# Shared "Beacon" design system for the HTML report and guide, so they look like one product.
# Decision-first, high-readability: light by default, full dark theme, system fonts (self-contained/offline).

function Get-WfxThemeCss {
    @'
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#f6f7f9;--card:#ffffff;--card2:#fcfcfe;--ink:#0f1623;--ink2:#1f2a3a;--dim:#5b6676;--faint:#8a94a4;
  --line:#e7eaef;--line2:#dfe3ea;--acc:#4f46e5;--acc2:#eef0fe;
  --crit:#e11d48;--high:#ea580c;--med:#d97706;--low:#2563eb;--info:#64748b;--ok:#15a06b;
  --sans:"Inter","Segoe UI",system-ui,-apple-system,Roboto,Helvetica,Arial,sans-serif;
  --mono:ui-monospace,"SFMono-Regular","SF Mono",Menlo,Consolas,monospace;
  --sh:0 1px 2px rgba(11,24,48,.04),0 8px 24px -14px rgba(11,24,48,.13);
  --sh2:0 2px 4px rgba(11,24,48,.06),0 16px 38px -18px rgba(11,24,48,.2);
  --r:14px;
}
@media (prefers-color-scheme:dark){:root:not([data-theme=light]){
  --bg:#0a0c10;--card:#12151d;--card2:#161a24;--ink:#e9edf3;--ink2:#ffffff;--dim:#95a0b0;--faint:#667183;
  --line:#20262f;--line2:#2c3340;--acc:#7c83ff;--acc2:#1a1f38;
  --crit:#ff4766;--high:#ff9340;--med:#ffd24a;--low:#5e8fff;--info:#7d8798;--ok:#2ee6a6;
  --sh:0 1px 2px rgba(0,0,0,.3),0 10px 26px -16px rgba(0,0,0,.6);
  --sh2:0 2px 6px rgba(0,0,0,.4),0 18px 40px -20px rgba(0,0,0,.7);
}}
:root[data-theme=dark]{
  --bg:#0a0c10;--card:#12151d;--card2:#161a24;--ink:#e9edf3;--ink2:#ffffff;--dim:#95a0b0;--faint:#667183;
  --line:#20262f;--line2:#2c3340;--acc:#7c83ff;--acc2:#1a1f38;
  --crit:#ff4766;--high:#ff9340;--med:#ffd24a;--low:#5e8fff;--info:#7d8798;--ok:#2ee6a6;
  --sh:0 1px 2px rgba(0,0,0,.3),0 10px 26px -16px rgba(0,0,0,.6);
  --sh2:0 2px 6px rgba(0,0,0,.4),0 18px 40px -20px rgba(0,0,0,.7);
}
html{-webkit-text-size-adjust:100%}
body{background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.55;
  letter-spacing:-.01em;-webkit-font-smoothing:antialiased}
.mono{font-family:var(--mono)}
a{color:var(--acc);text-decoration:none}a:hover{text-decoration:underline}
h1,h2,h3,h4{font-weight:700;letter-spacing:-.02em}
kbd{font-family:var(--mono);font-size:.82em;background:var(--card2);border:1px solid var(--line2);
  border-bottom-width:2px;border-radius:5px;padding:1px 6px;color:var(--ink2)}
::selection{background:var(--acc);color:#fff}
.bg-Critical{background:var(--crit)}.bg-High{background:var(--high)}.bg-Medium{background:var(--med)}.bg-Low{background:var(--low)}.bg-Info{background:var(--info)}
.fg-Critical{color:var(--crit)}.fg-High{color:var(--high)}.fg-Medium{color:var(--med)}.fg-Low{color:var(--low)}.fg-Info{color:var(--info)}
/* top bar (shared) */
.bar{display:flex;align-items:center;gap:13px;margin-bottom:24px}
.bz{width:34px;height:34px;border-radius:10px;background:var(--acc);color:#fff;display:grid;place-items:center;
  font-weight:800;box-shadow:0 6px 16px -6px var(--acc);flex:none}
.bn{font-weight:750;font-size:16px;letter-spacing:-.02em}.bn span{color:var(--faint);font-weight:500;font-size:12.5px;margin-left:7px}
.bar .sp{flex:1}
.chip{font-size:13px;color:var(--ink2);background:var(--card);border:1px solid var(--line2);border-radius:9px;
  padding:7px 12px;box-shadow:var(--sh);white-space:nowrap}
.chip b{color:var(--acc)}
.gbtn{font-size:13px;color:var(--dim);background:var(--card);border:1px solid var(--line2);border-radius:9px;
  padding:7px 13px;cursor:pointer;box-shadow:var(--sh)}
.gbtn:hover{color:var(--ink2);border-color:var(--acc)}
'@
}


# ===== Public/Invoke-WfxAnalyze.ps1 =====
function Invoke-WfxAnalyze {
    <#
    .SYNOPSIS
        Runs every analyzer over a collection bundle and returns a scored result. Pure and OS-neutral:
        it works on any machine, so an analyst can re-analyze evidence collected elsewhere.
    .PARAMETER Bundle
        A bundle object from Get-WfxCollectionBundle, OR a path to a bundle JSON file (raw/bundle.json),
        OR a directory that contains one.
    .PARAMETER HostName
        Override the host label (defaults to the bundle's HostName).
    .OUTPUTS
        [pscustomobject] with Findings, Risk, Summary, AttackCoverage, Gaps, Host, HostName, Analyzed.
    .EXAMPLE
        Invoke-WfxAnalyze -Bundle 'D:\cases\WFX_host_20260101\raw\bundle.json'
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory, ValueFromPipeline)]$Bundle, [string]$HostName = '')

    process {
        # Accept an object, a JSON file, or a case directory.
        if ($Bundle -is [string]) {
            $p = $Bundle
            if (Test-Path -LiteralPath $p -PathType Container) {
                $cand = @(Join-Path $p 'bundle.json'), (Join-Path $p 'raw\bundle.json'), (Join-Path $p 'raw/bundle.json')
                $p = @($cand | Where-Object { Test-Path -LiteralPath $_ }) | Select-Object -First 1
                if (-not $p) { throw "No bundle.json found under '$Bundle'." }
            }
            if (-not (Test-Path -LiteralPath $p)) { throw "Bundle path not found: $Bundle" }
            $Bundle = Get-Content -LiteralPath $p -Raw | ConvertFrom-Json
        }
        if (-not $HostName) { $HostName = [string](Get-WfxValue $Bundle 'HostName' ([Environment]::MachineName)) }

        $all = New-Object System.Collections.Generic.List[object]
        $add = { param($set) foreach ($f in @($set | Where-Object { $_ })) { $all.Add($f) } }

        & $add (Invoke-WfxProcessAnalyzer    -Process     @(Get-WfxValue $Bundle 'Process' @())     -HostName $HostName)
        & $add (Invoke-WfxNetworkAnalyzer    -Connection  @(Get-WfxValue $Bundle 'Network' @())     -HostName $HostName)
        & $add (Invoke-WfxDnsAnalyzer        -DnsEntry    @(Get-WfxValue $Bundle 'Dns' @())         -HostName $HostName)
        & $add (Invoke-WfxPersistenceAnalyzer -Autostart  @(Get-WfxValue $Bundle 'Persistence' @()) -HostName $HostName)
        & $add (Invoke-WfxEventAnalyzer      -Event       @(Get-WfxValue $Bundle 'Events' @())      -HostName $HostName)
        & $add (Invoke-WfxFileAnalyzer       -File        @(Get-WfxValue $Bundle 'Files' @())       -HostName $HostName)
        & $add (Invoke-WfxExposureAnalyzer   -Exposure    @(Get-WfxValue $Bundle 'Exposure' @())    -HostName $HostName)
        & $add (Invoke-WfxPostureAnalyzer    -Posture     (Get-WfxValue $Bundle 'Security' $null)   -HostName $HostName)

        $ransom = Get-WfxValue $Bundle 'Ransom' $null
        if ($ransom) {
            & $add (Invoke-WfxRansomwareAnalyzer -Note @(Get-WfxValue $ransom 'Note' @()) -RecentFile @(Get-WfxValue $ransom 'RecentFile' @()) -HostName $HostName)
        }

        $findings = Merge-WfxFinding -Finding $all.ToArray()
        $risk = Get-WfxRiskScore -Finding $findings
        $summary = Get-WfxSeveritySummary -Finding $findings

        # ATT&CK coverage: distinct techniques observed, resolved to tactic/name.
        $techIds = @($findings | ForEach-Object { $_.Technique } | Where-Object { $_ } | Sort-Object -Unique)
        $coverage = foreach ($t in $techIds) { Get-WfxAttackTechnique $t }

        [pscustomobject]@{
            Schema         = 'winforensicx.result/1'
            HostName       = $HostName
            Analyzed       = (Get-Date).ToUniversalTime().ToString('o')
            ToolVersion    = $script:WfxVersion
            Host           = (Get-WfxValue $Bundle 'Host' $null)
            Risk           = $risk
            Summary        = $summary
            Findings       = @($findings)
            AttackCoverage = @($coverage)
            Gaps           = @(Get-WfxValue $Bundle 'Gaps' @())
            Meta           = (Get-WfxValue $Bundle 'Meta' $null)
        }
    }
}


# ===== Public/Invoke-WfxHunt.ps1 =====
function Invoke-WfxHunt {
    <#
    .SYNOPSIS
        Sweeps a host (or a saved bundle) for specific indicators of compromise — file hashes, IP
        addresses, domains, file names or arbitrary strings — and reports every place each one appears.
        Use it to check a fleet for a known-bad IOC from an advisory or a previous case.
    .PARAMETER Ioc          One or more indicators (SHA-256 hash, IP, domain, file name, or any substring).
    .PARAMETER InputPath    Hunt inside a previously saved case/bundle instead of collecting live.
    .PARAMETER Hours        Event look-back when collecting live (default 72).
    .PARAMETER FileScan     Include the file scan when collecting live (lets hash/name IOCs match files).
    .PARAMETER PassThru     Return the match findings.
    .EXAMPLE
        Invoke-WfxHunt -Ioc 'evil.com','5d41402abc4b2a76b9719d911017c592','1.2.3.4'
    .EXAMPLE
        Invoke-WfxHunt -Ioc 'maldoc.doc' -InputPath C:\cases\WFX_host_20260101-000000Z
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string[]]$Ioc,
        [string]$InputPath = '',
        [int]$Hours = 72,
        [switch]$FileScan,
        [switch]$PassThru
    )
    $iocs = @($Ioc | Where-Object { $_ } | ForEach-Object { $_.Trim() } | Sort-Object -Unique)
    if (-not $iocs.Count) { Write-WfxConsole 'No IOCs supplied.' -Kind Warn; return }

    if ($InputPath) {
        $bundle = if ((Test-Path -LiteralPath $InputPath -PathType Container)) { (Invoke-WfxGetBundle $InputPath) } else { Get-Content -LiteralPath $InputPath -Raw | ConvertFrom-Json }
    } else {
        if (-not (Test-WfxWindows)) { Write-WfxConsole 'Live hunt requires Windows (or pass -InputPath).' -Kind Bad; return }
        $bundle = Get-WfxCollectionBundle -Hours $Hours -FileScan:$FileScan
    }
    $hn = [string](Get-WfxValue $bundle 'HostName' ([Environment]::MachineName))

    # Build a flat, searchable index of (where, text, context) rows from the bundle.
    $rows = New-Object System.Collections.Generic.List[object]
    $push = { param($Where, $Text, $Ctx) if ($Text) { $rows.Add([pscustomobject]@{ Where = $Where; Text = [string]$Text; Ctx = $Ctx }) } }
    foreach ($p in @(Get-WfxValue $bundle 'Process' @())) {
        & $push 'process' $p.Name "pid $($p.Pid)"; & $push 'process' $p.Path "pid $($p.Pid)"; & $push 'process' $p.CommandLine "pid $($p.Pid)"
    }
    foreach ($c in @(Get-WfxValue $bundle 'Network' @())) {
        & $push 'network' $c.RemoteAddress "$($c.Process) → $($c.RemoteAddress):$($c.RemotePort)"; & $push 'network' $c.RemoteHost "$($c.Process)"
    }
    foreach ($d in @(Get-WfxValue $bundle 'Dns' @())) { & $push 'dns' $d.Name 'dns cache' }
    foreach ($a in @(Get-WfxValue $bundle 'Persistence' @())) { & $push 'persistence' $a.Command "$($a.Kind): $($a.Name)"; & $push 'persistence' $a.Path "$($a.Kind): $($a.Name)" }
    foreach ($f in @(Get-WfxValue $bundle 'Files' @())) { & $push 'file' $f.Path 'file'; & $push 'file' (Get-WfxValue $f 'SHA256' '') "sha256 of $(Get-WfxLeaf $f.Path)" }

    $findings = New-Object System.Collections.Generic.List[object]
    foreach ($i in $iocs) {
        $isHash = $i -match '^[0-9a-fA-F]{32}$|^[0-9a-fA-F]{40}$|^[0-9a-fA-F]{64}$'
        foreach ($row in $rows) {
            $match = if ($isHash) { $row.Text -eq $i } else { $row.Text -and $row.Text.IndexOf($i, [StringComparison]::OrdinalIgnoreCase) -ge 0 }
            if ($match) {
                $findings.Add((New-WfxFinding -Id 'HUNT-IOC-MATCH' -Title "IOC '$i' found in $($row.Where): $($row.Ctx)" `
                            -Severity 'High' -Confidence 'High' -Category 'Hunt' -Technique @() `
                            -Description "The indicator '$i' was located in $($row.Where) data on this host. This is a direct IOC hit and should be triaged immediately." `
                            -Recommendation "Correlate with the surrounding activity (process tree, connections, timing) and contain the host if confirmed malicious." `
                            -Entity "hunt:$i`:$($row.Where):$($row.Ctx)" -HostName $hn -Source 'hunt' `
                            -Evidence ([ordered]@{ Ioc = $i; Where = $row.Where; Context = $row.Ctx; Value = (Protect-WfxText $row.Text) })))
            }
        }
    }
    $merged = Merge-WfxFinding -Finding $findings.ToArray()
    Write-WfxSection 'Hunt'
    if (@($merged).Count -eq 0) { Write-WfxConsole ("No matches for {0} IOC(s) on {1}." -f $iocs.Count, $hn) -Kind Ok }
    else {
        Write-WfxConsole ("{0} IOC hit(s) on {1}:" -f @($merged).Count, $hn) -Kind Bad
        foreach ($f in $merged) { Write-WfxConsole "  $($f.Title)" -Kind Bad }
    }
    if ($PassThru) { return $merged }
}

function Invoke-WfxGetBundle {
    <# Loads a bundle.json from a case folder or path (shared by hunt / analyze). #>
    param([string]$PathOrDir)
    $p = $PathOrDir
    if (Test-Path -LiteralPath $p -PathType Container) {
        $cand = @((Join-Path $p 'bundle.json'), (Join-Path (Join-Path $p 'raw') 'bundle.json'))
        $p = @($cand | Where-Object { Test-Path -LiteralPath $_ }) | Select-Object -First 1
        if (-not $p) { throw "No bundle.json found under '$PathOrDir'." }
    }
    Get-Content -LiteralPath $p -Raw | ConvertFrom-Json
}


# ===== Public/Invoke-WfxTriage.ps1 =====
function Get-WfxPortableSource {
    <# Returns the module's collection source as one self-contained string, so it can be sent to a remote
       WinRM session and dot-sourced there. Works whether WinForensicX is loaded from files (module) or
       from the single-file build (one script). Only the Private + Collectors layers are needed to collect. #>
    $files = @(Get-Command -CommandType Function -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -match 'Wfx' -and $_.ScriptBlock.File } |
            ForEach-Object { $_.ScriptBlock.File } | Sort-Object -Unique)
    $sel = @($files | Where-Object { $_ -match '[\\/](Private|Collectors)[\\/]' })
    if (-not $sel.Count) { $sel = $files }   # single-file build: everything lives in one script
    ($sel | ForEach-Object { Get-Content -LiteralPath $_ -Raw }) -join "`n`n"
}

function Invoke-WfxTriage {
    <#
    .SYNOPSIS
        One-shot incident triage for a Windows host: collect → analyze → score → report, with a full
        chain-of-custody case folder. The main entry point.
    .DESCRIPTION
        Four modes, chosen by parameters:
          • Local   (default)        — collect and analyze this host.
          • Remote  (-ComputerName)  — collect over WinRM on one or more hosts, analyze locally.
          • Offline (-EvtxPath)      — analyze exported event logs (plus whatever live data is available).
          • Re-analyze (-InputPath)  — re-run analysis over a previously saved case/bundle (no collection).
        Everything is read-only. Credential exposure is audited and REDACTED, never extracted.
    .PARAMETER OutputPath   Where the case folder is created (default: Desktop\WinForensicX).
    .PARAMETER CaseName     Optional label folded into the case folder name.
    .PARAMETER Hours        Event look-back window in hours (default 72).
    .PARAMETER FileScan     Also scan web roots / user drop folders for web shells, droppers, ransom notes.
    .PARAMETER ExposureScan Also scan common config files for clear-text secrets (redacted).
    .PARAMETER ComputerName One or more remote hosts to triage over WinRM.
    .PARAMETER Credential   Credential for the remote session.
    .PARAMETER EvtxPath     Folder or .evtx file to analyze offline.
    .PARAMETER InputPath    A previous case folder or bundle.json to re-analyze.
    .PARAMETER Quiet        Suppress console output (results still written).
    .PARAMETER NoReport     Skip the HTML report (JSON/CSV still written).
    .PARAMETER PassThru     Return the result object(s).
    .EXAMPLE
        Invoke-WfxTriage -FileScan
    .EXAMPLE
        Invoke-WfxTriage -ComputerName srv01,srv02 -Credential (Get-Credential)
    .EXAMPLE
        Invoke-WfxTriage -EvtxPath D:\evidence\Security.evtx -CaseName acme-ir
    .EXAMPLE
        Invoke-WfxTriage -InputPath 'C:\cases\WFX_host_20260101-000000Z'
    #>
    [CmdletBinding(DefaultParameterSetName = 'Local')]
    param(
        [string]$OutputPath = '',
        [string]$CaseName = '',
        [int]$Hours = 72,
        [switch]$FileScan,
        [switch]$ExposureScan,
        [Parameter(ParameterSetName = 'Remote', Mandatory)][string[]]$ComputerName,
        [Parameter(ParameterSetName = 'Remote')][System.Management.Automation.PSCredential]$Credential,
        [Parameter(ParameterSetName = 'Offline')][string]$EvtxPath,
        [Parameter(ParameterSetName = 'Reanalyze', Mandatory)][string]$InputPath,
        [switch]$Quiet,
        [switch]$NoReport,
        [switch]$PassThru
    )

    $script:WfxQuiet = [bool]$Quiet
    Write-WfxBanner

    # ── Re-analyze: no collection, just re-run analyzers over saved evidence ──
    if ($PSCmdlet.ParameterSetName -eq 'Reanalyze') {
        Write-WfxConsole "Re-analyzing saved evidence: $InputPath" -Kind Info
        $result = Invoke-WfxAnalyze -Bundle $InputPath
        $rname = if ($CaseName) { $CaseName } else { 'reanalysis' }
        $case = New-WfxCase -OutputPath $OutputPath -Name $rname -HostName $result.HostName
        Save-WfxResult -Result $result -Case $case -NoReport:$NoReport
        Complete-WfxCase
        Write-WfxResultSummary -Result $result -Case $case
        if ($PassThru) { return $result }
        return
    }

    # ── Remote: collect each host over WinRM, analyze locally ──
    if ($PSCmdlet.ParameterSetName -eq 'Remote') {
        $results = New-Object System.Collections.Generic.List[object]
        $src = Get-WfxPortableSource
        $sb = {
            param($Source, $Hours, $EvtxPath, $FileScan, $ExposureScan)
            Invoke-Expression $Source
            $b = Get-WfxCollectionBundle -Hours $Hours -EvtxPath $EvtxPath -FileScan:$FileScan -ExposureScan:$ExposureScan
            # Return JSON (not live objects) so deep nesting survives remoting serialization intact.
            $b | ConvertTo-Json -Depth 12 -Compress
        }
        foreach ($cn in $ComputerName) {
            Write-WfxConsole "Collecting from $cn over WinRM..." -Kind Info
            try {
                $icmArgs = @{ ComputerName = $cn; ScriptBlock = $sb; ArgumentList = @($src, $Hours, $EvtxPath, [bool]$FileScan, [bool]$ExposureScan); ErrorAction = 'Stop' }
                if ($Credential) { $icmArgs.Credential = $Credential }
                $json = Invoke-Command @icmArgs
                $bundle = $json | ConvertFrom-Json
                $result = Invoke-WfxAnalyze -Bundle $bundle -HostName $cn
                $rname = if ($CaseName) { $CaseName } else { 'remote' }
                $case = New-WfxCase -OutputPath $OutputPath -Name $rname -HostName $cn
                Save-WfxJson -InputObject $bundle -Path (Join-Path (Join-Path $case.Path 'raw') 'bundle.json') -Depth 12
                Save-WfxResult -Result $result -Case $case -NoReport:$NoReport
                Complete-WfxCase
                Write-WfxResultSummary -Result $result -Case $case
                $results.Add($result)
            } catch {
                Write-WfxConsole "  Failed on $cn`: $($_.Exception.Message)" -Kind Bad
                Add-WfxGap -Source "remote:$cn" -Reason $_.Exception.Message -Fix 'Confirm WinRM is enabled (Enable-PSRemoting) and the account has access.'
            }
        }
        if ($PassThru) { return $results.ToArray() }
        return
    }

    # ── Local / Offline ──
    $hn = [Environment]::MachineName
    $case = New-WfxCase -OutputPath $OutputPath -Name $CaseName -HostName $hn
    Write-WfxConsole "Case: $($case.Path)" -Kind Dim
    if (-not $case.Admin) { Write-WfxConsole 'Running without administrator rights — some data will be limited (recorded as gaps).' -Kind Warn }

    Write-WfxSection 'Collecting'
    $bundle = Get-WfxCollectionBundle -Hours $Hours -EvtxPath ([string]$EvtxPath) -FileScan:$FileScan -ExposureScan:$ExposureScan
    Save-WfxJson -InputObject $bundle -Path (Join-Path (Join-Path $case.Path 'raw') 'bundle.json') -Depth 12

    Write-WfxSection 'Analyzing'
    $result = Invoke-WfxAnalyze -Bundle $bundle -HostName $hn

    Save-WfxResult -Result $result -Case $case -NoReport:$NoReport
    Complete-WfxCase
    Write-WfxResultSummary -Result $result -Case $case
    if ($PassThru) { return $result }
}

function Write-WfxBanner {
    if ($script:WfxQuiet) { return }
    Write-WfxConsole ''
    Write-WfxConsole '  WinForensicX' -Kind Head -NoNewline
    Write-WfxConsole "  v$script:WfxVersion  —  read-only DFIR triage" -Kind Dim
    Write-WfxConsole ''
}

function Save-WfxResult {
    <# Writes findings.json, findings.csv and result.json into the case outputs, plus the HTML report. #>
    param($Result, $Case, [switch]$NoReport)
    $root = $Case.Path
    Save-WfxJson -InputObject $Result -Path (Join-Path $root 'result.json') -Depth 10
    Save-WfxJson -InputObject @($Result.Findings) -Path (Join-Path $root 'findings.json') -Depth 10
    # Flat CSV for triage in a spreadsheet / SIEM import.
    $rows = foreach ($f in @($Result.Findings)) {
        [pscustomobject]@{
            Severity = $f.Severity; Confidence = $f.Confidence; Score = $f.Score; Id = $f.Id
            Title = $f.Title; Category = $f.Category; Technique = (@($f.Technique) -join '; ')
            Entity = $f.Entity; Host = $f.Host; Occurrences = (Get-WfxValue $f 'Occurrences' 1); Recommendation = $f.Recommendation
        }
    }
    try { @($rows) | Export-Csv -Path (Join-Path $root 'findings.csv') -NoTypeInformation -Encoding UTF8 } catch {}
    if (-not $NoReport -and (Get-Command New-WfxReport -ErrorAction SilentlyContinue)) {
        try { New-WfxReport -Result $Result -Path (Join-Path $root 'report.html') | Out-Null }
        catch { Add-WfxGap -Source 'report' -Reason $_.Exception.Message }
    }
}

function Write-WfxResultSummary {
    param($Result, $Case)
    if ($script:WfxQuiet) { return }
    $r = $Result.Risk
    $kind = switch ($r.Level) { 'Critical' { 'Bad' } 'High' { 'Bad' } 'Elevated' { 'Warn' } default { 'Ok' } }
    Write-WfxSection 'Result'
    Write-WfxConsole ("Host {0}   Risk {1}/100 ({2})" -f $Result.HostName, $r.Score, $r.Level) -Kind $kind
    $s = $Result.Summary
    Write-WfxConsole ("Findings  Critical {0}  High {1}  Medium {2}  Low {3}  Info {4}" -f $s.Critical, $s.High, $s.Medium, $s.Low, $s.Info) -Kind Plain
    $top = @($Result.Findings | Select-Object -First 8)
    if ($top.Count) {
        Write-WfxConsole ''
        foreach ($f in $top) {
            $fk = switch ($f.Severity) { 'Critical' { 'Bad' } 'High' { 'Bad' } 'Medium' { 'Warn' } default { 'Dim' } }
            Write-WfxConsole ("  [{0,-8}] {1}" -f $f.Severity, $f.Title) -Kind $fk
        }
    }
    $gaps = @($Result.Gaps)
    if ($gaps.Count) { Write-WfxConsole ''; Write-WfxConsole ("{0} collection gap(s) recorded — see the report so 'nothing found' is read correctly." -f $gaps.Count) -Kind Warn }
    Write-WfxConsole ''
    Write-WfxConsole ("Outputs:  {0}" -f $Case.Path) -Kind Info
    $reportPath = Join-Path $Case.Path 'report.html'
    if (Test-Path -LiteralPath $reportPath) {
        # Printed as a file:// link so the terminal makes it Ctrl/Cmd-clickable.
        Write-WfxConsole ("Report:   {0}" -f (ConvertTo-WfxFileUri $reportPath)) -Kind Info
        Write-WfxConsole '          (open it to filter findings, see ATT&CK coverage, the timeline and the limitations)' -Kind Dim
    }
    Write-WfxConsole ''
    Write-WfxConsole 'Reminder: findings are leads, not verdicts — read them next to the collection gaps.' -Kind Dim
    Write-WfxConsole 'How to use / commands / limits:  Show-WfxHelp   (add -Html to open the guide)' -Kind Dim
}


# ===== Public/Save-WfxEvidence.ps1 =====
function Save-WfxEvidence {
    <#
    .SYNOPSIS
        Collects a full read-only evidence bundle and writes it to a chain-of-custody case folder WITHOUT
        running analysis — for when the priority is to preserve state quickly and analyze later (possibly
        on another machine with Invoke-WfxTriage -InputPath). Every output is hashed in manifest.json.
    .PARAMETER OutputPath   Case folder location (default: Desktop\WinForensicX).
    .PARAMETER CaseName     Optional case label.
    .PARAMETER Hours        Event look-back window (default 72).
    .PARAMETER FileScan     Include the web-root / drop-folder file scan.
    .PARAMETER ExposureScan Include the config-file secret scan (redacted).
    .PARAMETER Quiet        Suppress console output.
    .OUTPUTS The case folder path.
    .EXAMPLE
        Save-WfxEvidence -FileScan -ExposureScan -CaseName acme-ir
    #>
    [CmdletBinding()]
    param(
        [string]$OutputPath = '',
        [string]$CaseName = '',
        [int]$Hours = 72,
        [switch]$FileScan,
        [switch]$ExposureScan,
        [switch]$Quiet
    )
    if (-not (Test-WfxWindows)) { Write-WfxConsole 'Evidence collection requires Windows.' -Kind Bad; return }
    $script:WfxQuiet = [bool]$Quiet
    Write-WfxBanner
    $hn = [Environment]::MachineName
    $case = New-WfxCase -OutputPath $OutputPath -Name ($(if ($CaseName) { $CaseName } else { 'evidence' })) -HostName $hn
    if (-not $case.Admin) { Write-WfxConsole 'Running without administrator rights — some data will be limited (recorded as gaps).' -Kind Warn }
    Write-WfxSection 'Collecting evidence'
    $bundle = Get-WfxCollectionBundle -Hours $Hours -FileScan:$FileScan -ExposureScan:$ExposureScan
    $raw = Join-Path $case.Path 'raw'
    Save-WfxJson -InputObject $bundle -Path (Join-Path $raw 'bundle.json') -Depth 12
    # A human-readable host summary alongside the machine-readable bundle.
    $h = $bundle.Host
    $txt = @(
        "WinForensicX evidence — $hn",
        "Collected (UTC): $($bundle.Collected)",
        "OS: $(Get-WfxValue $h 'Os' '')",
        "Operator: $(Get-WfxValue $h 'Operator' '')  Admin: $(Get-WfxValue $h 'Admin' '')",
        "Processes: $(@($bundle.Process).Count)  Connections: $(@($bundle.Network).Count)  Autostarts: $(@($bundle.Persistence).Count)  Events: $(@($bundle.Events).Count)",
        "Collection gaps: $(@($bundle.Gaps).Count)"
    ) -join "`r`n"
    [IO.File]::WriteAllText((Join-Path $raw 'host-summary.txt'), $txt, (New-Object Text.UTF8Encoding($false)))
    Complete-WfxCase
    Write-WfxSection 'Done'
    Write-WfxConsole ("Evidence bundle written and hashed: {0}" -f $case.Path) -Kind Info
    Write-WfxConsole ("Re-analyze later with:  Invoke-WfxTriage -InputPath '{0}'" -f $case.Path) -Kind Dim
    return $case.Path
}


# ===== Public/Show-WfxHelp.ps1 =====
function ConvertTo-WfxFileUri {
    <# Turns a local path into a file:// URI that most modern terminals render as a clickable link. #>
    param([string]$Path)
    $full = $Path
    try { $full = (Resolve-Path -LiteralPath $Path -ErrorAction Stop).Path } catch {}
    $p = ($full -replace '\\', '/')
    if ($p -notmatch '^/') { $p = '/' + $p }   # Windows "C:/..." -> "/C:/..." so we get file:///C:/...
    return 'file://' + ($p -replace ' ', '%20')
}

function Show-WfxHelp {
    <#
    .SYNOPSIS
        Prints how to use WinForensicX — commands, examples, limitations and the defensive posture — to the
        terminal, and writes a matching HTML guide you can open in a browser.
    .PARAMETER Html      Open the HTML guide in the default browser after printing.
    .PARAMETER GuidePath Where to write the HTML guide (default: a temp file).
    .PARAMETER NoGuide   Don't write the HTML guide (terminal only).
    .EXAMPLE
        Show-WfxHelp
    .EXAMPLE
        Show-WfxHelp -Html
    #>
    [CmdletBinding()]
    param([switch]$Html, [string]$GuidePath = (Join-Path ([IO.Path]::GetTempPath()) 'WinForensicX-guide.html'), [switch]$NoGuide)
    $wasQuiet = $script:WfxQuiet; $script:WfxQuiet = $false
    $h = Get-WfxHelpModel

    Write-WfxConsole ''
    Write-WfxConsole '  WinForensicX' -Kind Head -NoNewline
    Write-WfxConsole "  v$($h.Version)  —  read-only DFIR triage" -Kind Dim
    Write-WfxConsole "  $($h.Tagline)" -Kind Plain
    Write-WfxConsole "  $($h.Requires)" -Kind Dim

    Write-WfxSection 'Commands'
    foreach ($c in $h.Commands) {
        Write-WfxConsole ("  {0}" -f $c.Name) -Kind Info -NoNewline
        Write-WfxConsole ("  $($c.Summary)") -Kind Dim
        foreach ($p in @($c.Params)) { Write-WfxConsole "      $p" -Kind Plain }
        if (@($c.Examples).Count) { Write-WfxConsole ("      e.g.  {0}" -f $c.Examples[0]) -Kind Dim }
    }

    Write-WfxSection 'What a run produces'
    foreach ($o in $h.Outputs) { Write-WfxConsole "  $o" -Kind Plain }

    Write-WfxSection 'Safety'
    foreach ($s in $h.Safety) { Write-WfxConsole "  + $s" -Kind Ok }

    Write-WfxSection 'Limitations'
    foreach ($l in $h.Limits) { Write-WfxConsole "  ! $l" -Kind Warn }

    if (-not $NoGuide -and (Get-Command New-WfxGuide -ErrorAction SilentlyContinue)) {
        try {
            $gp = New-WfxGuide -Path $GuidePath
            $uri = ConvertTo-WfxFileUri $gp
            Write-WfxSection 'Full guide'
            Write-WfxConsole '  Open the full illustrated guide in a browser (Ctrl/Cmd-click the link):' -Kind Plain
            Write-WfxConsole "  $uri" -Kind Info
            if ($Html) { try { Start-Process $gp -ErrorAction Stop } catch { Write-WfxConsole "  (could not auto-open; copy the link above)" -Kind Dim } }
        } catch { Write-WfxConsole "  (HTML guide unavailable: $($_.Exception.Message))" -Kind Dim }
    }
    Write-WfxConsole ''
    $script:WfxQuiet = $wasQuiet
}


# ===== Public/Show-WfxMenu.ps1 =====
function Show-WfxMenu {
    <#
    .SYNOPSIS
        Interactive menu for the common WinForensicX workflows — the simplest way for an analyst to drive
        the toolkit without memorizing parameters. Everything it runs is read-only.
    .EXAMPLE
        Show-WfxMenu
    #>
    [CmdletBinding()]
    param([string]$OutputPath = '')
    $script:WfxQuiet = $false
    while ($true) {
        Write-WfxBanner
        Write-WfxConsole '  Select an action:' -Kind Head
        Write-WfxConsole ''
        Write-WfxConsole '   1  Quick triage (this host)'
        Write-WfxConsole '   2  Full triage (this host + file & exposure scan)'
        Write-WfxConsole '   3  Triage a remote host (WinRM)'
        Write-WfxConsole '   4  Offline: analyze exported event logs (.evtx)'
        Write-WfxConsole '   5  Re-analyze a saved case'
        Write-WfxConsole '   6  Live monitor'
        Write-WfxConsole '   7  Hunt for IOCs'
        Write-WfxConsole '   8  Collect evidence only (no analysis)'
        Write-WfxConsole '   9  Open last case folder'
        Write-WfxConsole '   H  Help — how to use, commands, limitations (opens the guide)'
        Write-WfxConsole '   Q  Quit'
        Write-WfxConsole ''
        $choice = (Read-Host '  Choice').Trim()
        Write-WfxConsole ''
        switch ($choice.ToUpper()) {
            '1' { Invoke-WfxTriage -OutputPath $OutputPath | Out-Null }
            '2' { Invoke-WfxTriage -OutputPath $OutputPath -FileScan -ExposureScan | Out-Null }
            '3' {
                $cn = (Read-Host '  Remote host name(s), comma-separated').Trim()
                if ($cn) {
                    $useCred = (Read-Host '  Use alternate credentials? (y/N)').Trim()
                    $cred = if ($useCred -match '^(y|yes)$') { Get-Credential } else { $null }
                    $tparams = @{ ComputerName = ($cn -split '\s*,\s*'); OutputPath = $OutputPath }
                    if ($cred) { $tparams.Credential = $cred }
                    Invoke-WfxTriage @tparams
                }
            }
            '4' { $p = (Read-Host '  Path to .evtx file or folder').Trim('"', ' '); if ($p) { Invoke-WfxTriage -EvtxPath $p -OutputPath $OutputPath } }
            '5' { $p = (Read-Host '  Path to saved case folder or bundle.json').Trim('"', ' '); if ($p) { Invoke-WfxTriage -InputPath $p -OutputPath $OutputPath } }
            '6' {
                $d = (Read-Host '  Duration in seconds (blank = until Ctrl+C)').Trim()
                $dur = 0; [void][int]::TryParse($d, [ref]$dur)
                Start-WfxMonitor -Duration $dur -OutputPath $OutputPath
            }
            '7' {
                $i = (Read-Host '  IOC(s), comma-separated (hash / IP / domain / name)').Trim()
                if ($i) { Invoke-WfxHunt -Ioc ($i -split '\s*,\s*') }
            }
            '8' { Save-WfxEvidence -OutputPath $OutputPath -FileScan -ExposureScan | Out-Null }
            '9' {
                $root = if ($OutputPath) { $OutputPath } elseif (Test-WfxWindows) { Join-Path ([Environment]::GetFolderPath('Desktop')) 'WinForensicX' } else { Join-Path $HOME 'WinForensicX' }
                if (Test-Path -LiteralPath $root) {
                    $recent = Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
                    if ($recent) { Write-WfxConsole "  Most recent case: $($recent.FullName)" -Kind Info; if (Test-WfxWindows) { try { Start-Process explorer.exe $recent.FullName } catch {} } }
                    else { Write-WfxConsole '  No cases found yet.' -Kind Dim }
                } else { Write-WfxConsole '  No cases found yet.' -Kind Dim }
            }
            'H' { Show-WfxHelp -Html }
            'Q' { return }
            default { Write-WfxConsole '  Unknown choice.' -Kind Warn }
        }
        Write-WfxConsole ''
        [void](Read-Host '  Press Enter to continue')
    }
}


# ===== Public/Start-WfxMonitor.ps1 =====
function Start-WfxMonitor {
    <#
    .SYNOPSIS
        Live monitoring: takes a baseline of processes and network connections, then watches for NEW
        ones and runs the process / network / beacon analyzers over just the changes, alerting as they
        happen. Read-only. Stop with Ctrl+C or a time limit.
    .PARAMETER Interval     Seconds between polls (default 5).
    .PARAMETER Duration     Total seconds to run; 0 = until Ctrl+C (default 0).
    .PARAMETER MinSeverity  Only alert at or above this severity (default Medium).
    .PARAMETER OutputPath   Case folder location (an alerts.jsonl is appended there).
    .PARAMETER CaseName     Optional case label.
    .PARAMETER Quiet        Suppress console output (alerts still written to the case).
    .EXAMPLE
        Start-WfxMonitor -Interval 5 -Duration 300
    #>
    [CmdletBinding()]
    param(
        [int]$Interval = 5,
        [int]$Duration = 0,
        [ValidateSet('Info', 'Low', 'Medium', 'High', 'Critical')][string]$MinSeverity = 'Medium',
        [string]$OutputPath = '',
        [string]$CaseName = '',
        [switch]$Quiet
    )
    if (-not (Test-WfxWindows)) { Write-WfxConsole 'Live monitor requires Windows.' -Kind Bad; return }
    $script:WfxQuiet = [bool]$Quiet
    Write-WfxBanner
    $rank = @{ Info = 4; Low = 3; Medium = 2; High = 1; Critical = 0 }
    $minRank = $rank[$MinSeverity]
    $hn = [Environment]::MachineName
    $case = New-WfxCase -OutputPath $OutputPath -Name ($(if ($CaseName) { $CaseName } else { 'monitor' })) -HostName $hn
    $alertPath = Join-Path $case.Path 'alerts.jsonl'

    Write-WfxConsole "Monitoring $hn — baseline..." -Kind Info
    $seenPid = @{}
    $seenConn = @{}
    $beacon = @{}                      # remote -> [List[datetime]]
    foreach ($p in @(Get-WfxProcessData)) { $seenPid["$($p.Pid):$($p.Name)"] = $true }
    foreach ($c in @(Get-WfxNetworkData)) { $seenConn[(ConnKey $c)] = $true }
    Write-WfxConsole ("Baseline: {0} processes, {1} connections. Polling every {2}s. Ctrl+C to stop." -f $seenPid.Count, $seenConn.Count, $Interval) -Kind Dim
    Write-WfxConsole ''

    $deadline = if ($Duration -gt 0) { (Get-Date).AddSeconds($Duration) } else { [datetime]::MaxValue }
    $alertCount = 0; $iter = 0
    try {
        while ((Get-Date) -lt $deadline) {
            Start-Sleep -Seconds $Interval
            $iter++
            $newProcs = @(); $newConns = @()
            foreach ($p in @(Get-WfxProcessData)) {
                $k = "$($p.Pid):$($p.Name)"
                if (-not $seenPid.ContainsKey($k)) { $seenPid[$k] = $true; $newProcs += $p }
            }
            foreach ($c in @(Get-WfxNetworkData)) {
                $k = ConnKey $c
                if (-not $seenConn.ContainsKey($k)) { $seenConn[$k] = $true; $newConns += $c }
                # Track established public destinations over time for beacon detection.
                if ($c.State -match 'Establish' -and $c.RemoteAddress -and -not (Test-WfxPrivateIp $c.RemoteAddress)) {
                    $rk = "$($c.RemoteAddress):$($c.RemotePort)"
                    if (-not $beacon.ContainsKey($rk)) { $beacon[$rk] = New-Object System.Collections.Generic.List[datetime] }
                    $beacon[$rk].Add((Get-Date))
                }
            }

            $hits = New-Object System.Collections.Generic.List[object]
            if ($newProcs.Count) { foreach ($f in @(Invoke-WfxProcessAnalyzer -Process $newProcs -HostName $hn)) { $hits.Add($f) } }
            if ($newConns.Count) { foreach ($f in @(Invoke-WfxNetworkAnalyzer -Connection $newConns -HostName $hn)) { $hits.Add($f) } }
            # Periodically re-evaluate beaconing (needs several samples).
            if ($iter % 6 -eq 0) {
                $bIn = foreach ($rk in $beacon.Keys) { if ($beacon[$rk].Count -ge 6) { [pscustomobject]@{ Remote = $rk; Times = @($beacon[$rk]) } } }
                foreach ($f in @(Invoke-WfxBeaconAnalyzer -Beacon @($bIn) -HostName $hn)) { $hits.Add($f) }
            }

            foreach ($f in @($hits | Where-Object { $rank[$_.Severity] -le $minRank })) {
                $alertCount++
                $fk = switch ($f.Severity) { 'Critical' { 'Bad' } 'High' { 'Bad' } 'Medium' { 'Warn' } default { 'Dim' } }
                Write-WfxConsole ("[{0:HH:mm:ss}] [{1,-8}] {2}" -f (Get-Date), $f.Severity, $f.Title) -Kind $fk
                try { Add-Content -LiteralPath $alertPath -Value (($f | ConvertTo-Json -Compress -Depth 6)) -Encoding UTF8 } catch {}
            }
        }
    } finally {
        Complete-WfxCase
        Write-WfxConsole ''
        Write-WfxConsole ("Monitor stopped. {0} alert(s) at/above {1}. Case: {2}" -f $alertCount, $MinSeverity, $case.Path) -Kind Info
    }
}

function ConnKey {
    param($C)
    "$($C.Protocol)|$($C.LocalAddress):$($C.LocalPort)|$($C.RemoteAddress):$($C.RemotePort)|$($C.State)"
}


